-- Tillgg till WPS.L.quest: godkanda omgngar ur translation/out/,
-- sammanfogade av tools/merge-translation.py. Gr inte handandringar hr:
-- nsta krning regenererar filen, gamla rader rrs aldrig om.
-- Flt t,o,d,p,c; tomt flt = ingen nyckel (addonet byter bara flt som finns).
-- l-rader (sprarrader i trakern) saknas: tckningsbegrnsning, se PIPELINE.md;
-- sparraderna frblir engelska till vidare, oskadligt.
local _, WPS = ...
local LQ = WPS.L.quest

local extra = {
[105]={t="Ack, Andorhal", o="Ta med Arajs fylakterieskärva till högexekutor Derrington vid Bålverket i Västra pestlanden.", d="Ack, tiden att angripa Andorhal och driva ut lichen som kontrollerar staden är kommen!$B$BInne i stadens ruiner håller lichen - Araj Frammanaren - herravälde.  Han vaktas av talrika från Gisslet som omger resterna av stadens centrum, och hans personliga följe av väktare som är knutna direkt till honom är formidabelt.  Du behöver många allierade för att ens ha en chans att möta honom framgångsrikt.$B$BFörgör Araj, $n, och ta med mig en skärva från hans fylakterie som bevis!"}, -- quests-batch-16-sv
[185]={t="Tigerbehärskning", o="Ajeck Rouack från Nesingwarys expedition vill att du dödar 10 unga strypetörnstigrar.", d="När jag bara var en ung flicka tränade min far mig i konsten att jaga tigrar.$b$bDu kommer att finna de unga kattdjuren mycket lättare att spåra och dräpa. Av den anledningen börjar vi enkelt. Man kan ofta finna unga tigrar nära expeditionslägret.$b$bTesta dina spårningsfärdigheter och se om du kan jaga rätt på några av bestarna."}, -- quests-batch-03-sv
[188]={t="Tigerbehärskning", o="Ajeck Rouack från Nesingwarys expedition vill att du dödar Sin'Dall och återvänder med hennes tass.", d="Här är den sista utmaningen jag lägger fram.  Vi har spårat en svårfångad tiger i flera veckor.  Vi kallar odjuret Sin'Dall.  Se om du kan göra vad ingen $r har gjort förut: jaga ned och döda Sin'Dall.  Ta med mig hennes tass som bevis på din bedrift.$b$bAtt spåra upp henne blir ingen lätt uppgift."}, -- quests-batch-30-sv
[189]={t="Blodskalpöron", o="Skaffa 15 Blodskalpöron och lämna dem till Kebok i Bytesbukten.", d="Satans troll! De har dödat våra agenter i djungeln! Jag har redan förlorat ett gott antal av mina bästa vakter i skärmytslingar med dem. Kostnaderna hopar sig! Hur ska jag förklara det här för baron Revilgaz?$b$bBeslutsamma åtgärder ... Tänk, Kebok ... du blev inte tilldelad posten du har idag för att sitta och dega ... Jag har det! Du ... $n, var det så? Du hjälper mig, eller hur? Det finns pengar att tjäna!$b$bHär är affären ... du tar med mig öronen från femton Blodskalp-troll, så ersätter jag dig väl."}, -- quests-batch-30-sv
[190]={t="Pantermästerskap", o="Sir S. J. Erlgadin från Nesingwarys expedition vill att du dödar 10 unga pantrar.", d="Om du vill vara en del av jakten med den här expertgrupp som Hemet har sammanställt, måste du bevisa att du är en skicklig panterjägare. Vi börjar enkelt -- oroa dig inte. Låt oss se dig döda 10 unga pantrar för att börja.$b$bAtt spåra upp dem är bara halva utmaningen..."}, -- quests-batch-08-sv
[191]={t="Pantermästerskap", o="Sir S. J. Erlgadin från Nesingwarys expedition vill att du dödar 10 pantrar.", d="Nu är du redo att öka tempot.  Om du vill bevisa att du är värdig att umgås med storviltsjägare som dessa måste du bevisa att du kan döda 10 pantrar.$b$bDe stora grabbarna är tuffare.  De är inte lika lätta som de unga du dödade tidigare."}, -- quests-batch-09-sv
[192]={t="Pantermästerskap", o="Sir S. J. Erlgadin från Nesingwarys expedition vill att du dödar 10 Skuggkäftspantrar.", d="Nu kommer den svåra delen.  En sann panterjägare kan visa skicklighet genom att fälla Skuggkäftspantrar, de dödligaste i Strypetörnsdalen.  Bevisa för oss att du kan döda 10 av dessa bestar.$b$bOm du tycker att de är svåra att spåra, vänta tills du försöker döda en ...."}, -- quests-batch-25-sv
[194]={t="Raptormästerskap", o="Hemet Nesingwary vill att du dödar 10 Strypetörnsraptorer.", d="Så du tror att dina jaktkunskaper är i toppform? Jag kan sätta dem på prov på ett ögonblick. Bege dig ut i djungeln och döda 10 Strypetörnsraptorer. Vi får se hur stor av en storviltjägare du egentligen är.$b$bOch nej, jag tänker inte berätta var du kan hitta dem! Att lokalisera bestarna är halva utmaningen."}, -- quests-batch-32-sv
[196]={t="Raptormästerskap", o="Hemet Nesingwary vill att du dödar 10 Djungellurpassare.", d="Låt oss se hur du hanterar nästa utmaning.  Det finns en slug raptorras där ute.  Vi kallar dem Djungellurpassare.  De är mycket svårare att spåra upp och döda än de andra raser du har försökt dig på.  Döda 10 Djungellurpassare så ger jag dig ett tips om den bästa jakten hittills."}, -- quests-batch-26-sv
[197]={t="Raptormästerskap", o="Hemet Nesingwary vill att du dödar Tethis, en svårfångad och farlig raptor i Strypetörnsdalen.", d="Eftersom du visat dig vara så driven i djungeln, låt mig berätta om en vild raptor som till och med jag har misslyckats med att döda. Ajeck här kallar denna sluga raptor för Tethis.$b$bOm du vill bevisa att du är en sann mästare, döda Tethis och ta med mig hans klo. Det vore en bedrift som ingen annan storviltjägare har lyckats med."}, -- quests-batch-32-sv
[201]={t="Undersök lägret", o="Hitta jägarnas läger och rapportera dess plats till Krazek i Bytesbukten.", d="Jag har fått rapporter om en grupp jägare som har slagit läger uppströms Äventyrsbolagets gruvläger vid Nazferitisjön. Normalt skulle jag inte bry mig, men osannolikt nog hörde jag att Hemet Nesingwary var en av jägarna där? Han har verkligen goda kontakter, om du förstår vad jag menar, och man kan aldrig vara för säker.$b$bVarför går du inte och kollar på lägret, $n, och ser vad de sysslar med?Hitta jägarnas läger"}, -- quests-batch-31-sv
[208]={t="Storviltjägare", o="Hemet Nesingwary vill att du hämtar huvudet av King Bangalash, den store vita tigern.", d="$n, du är en jägare värdig vårt sällskap. Från Lordaerons slagfält till den djupaste djungeln har jag sällan bevittnat sådan skicklighet med vapen som du har uppvisat.$b$bDu har dödat den vildsinta Sin'Dall, den svårfångade Bag'thera och den förrädiska Tethis. Men det sanna priset är huvudet av King Bangalash. Den vita tigern är anledningen till att jag är här. Jag har haft siktet inställt på honom under en lång tid nu. Döda King Bangalash så är din jaktförmåga bevisad vara oöverträffad."}, -- quests-batch-32-sv
[209]={t="Skullsplitter-betar", o="Skaffa 18 Skullsplitter-betar och lämna dem till Kebok.", d="Det är dyrt och svårt att döda tillräckligt många tigrar för att stödja exporten av tigertänder till öarna i Söderhavet. Som tur är har vi utvecklat en teknik som gör att vi kan ta vanliga hornliknande föremål och förvandla dem till oupptäckbara förfalskningar.$b$bDen närmaste matchen vi hittat är, förvånansvärt nog, betarna från Skullsplitter-trollen.$b$bHallå, innan du säger något, vad köparen inte vet skadar dem inte, har jag rätt? Ta med mig ett stort antal av dem så att vi kan sätta igång med den månatliga leveransen!"}, -- quests-batch-24-sv
[213]={t="Fientligt övertagande", o="Hämta 8 trumlade kristaller och lämna dem till Kebok i Bytesbukten.", d="Nu har han gjort det! Illa nog att Gelriz muskler ut magnaterna som utsetts av handelsprinsarna, nu försöker han skära sig in hos den mest ökände piraten!$b$bRevilgaz tänker inte tåla det, och han har sagt åt mig att ta hand om problemet på mitt eget sätt.$b$bMitt sätt? Stöld. Äventyrsbolagets geologer nära Nazferitisjön är djupt intresserade av de där märkliga blå kristallerna de har hittat i gruvorna. Ta med mig prover av stenen från deras geologer, jag bryr mig inte om vad du måste göra för att få dem."}, -- quests-batch-28-sv
[348]={t="Strypetörnsfeber", o="Sök upp häxdoktor Unbagwa och låt honom frammana Mokk den Vilde.  Ta Mokks hjärta till Fin Fizracket.", d="Sjuk ... så ... väldigt s-s-sjuk ...$b$b... har drabbats av Strypetörnsfeber ... dödligt v-v-virus ...$b$b... enda botemedlet ... är ... är ... att äta hjärtat av M-m-m-m-mokk den Vilde ... svårfångad vit best ...$b$b... Häxdoktor Unbagwa ... den ende som kan f-f-frammana ....$b$b... sök Unbagwa i dold grotta på södra udden ...$b$b... skynda ... döende ... döende ...."}, -- quests-batch-20-sv
[503]={t="Gol'dir", o="Befria Gol'dir och återvänd sedan till Krusk i Tarrens kvarn.", d="Av vad jag kan utläsa av dokumenten du skaffade hålls Gol'dir i en stor Syndikatbas i norr, troligen i Alteracbergen. Han har hållits fången alldeles för länge och måste befrias.Hitta var Gol'dir hålls fången"}, -- quests-batch-07-sv
[507]={t="Lord Aliden Perenolde", o="Döda lord Aliden Perenolde och fråga hans mätress, Elysa, om Tarethas hängsmycke.", d="Det är tydligt att Perenolde måste dödas, hans vidrighet avlägsnas från världen. Hans herrgård ligger en bit norrut härifrån, vid stränderna av Lordameresjön. Gör din plikt, $n, hämta sedan hängsmycket som krigsherren önskar och återvänd hit."}, -- quests-batch-32-sv
[518]={t="Viljans krona", o="Döda 14 Crushridge Maulers åt Melisara i Tarrens kvarn.", d="Mug'Thol och hans Crushridge-oger har tagit över Alteracruinerna. Det kommer att bli svårt att utdela något allvarligt straff till honom utan att minska ogernas antal.$b$bNär vi har försvagat dem, går vi vidare.$b$bFörstått? Bra. Gå nu."}, -- quests-batch-23-sv
[533]={t="Infiltration", o="Hämta information om Gol'dirs vistelseort till Krusk i Tarrens kvarn.", d="Äntligen börjar vi höra rykten och få ledtrådar om var Gol'dir befinner sig. Människorna har flyttat runt honom, men vi smalnar av vår sökning och fokuserar på det stora Syndikatlägret precis norr om här.$b$bGå dit, $n, och ta med dig all information du kan komma över."}, -- quests-batch-13-sv
[535]={t="Valik", o="Ta med en sejdel Sydstrandsporter till Valik i Syndikatlägret.", d="Urrgh ... Skadad och döende och konfronterad med fienden.$b$bUtan tvekan dödar du mig ändå, men om du tar med lite Sydstrandsporter--ni dricker väl, eller hur?--berättar jag vad du vill veta."}, -- quests-batch-23-sv
[544]={t="Inbrott i fängelset", o="Hitta förrädarna och återta deras artefakter, och återvänd sedan till mig, $n.", d="Jag kom till Tarrens kvarn för att forska, men måste nu lösa en kris. Du förstår, fyra av de bortglömda flydde från Understaden för några månader sedan. De vände sina bröder ryggen, men vad värre är ... de stal från Mörka damen.\\r\\n\\r\\nDe här tjuvarna bröt sig in i ett säkrat valv och stal fyra artefakter, föremål som våra apotekare behövde för vissa studier. Sylvanas vill ha tillbaka de här artefakterna.\\r\\n\\r\\nTjuvarna flydde från Understaden till Dalaran, och trollkarlarna där satte dem i karantän i Lordamere-interneringslägret."}, -- quests-batch-03-sv
[545]={t="Dalaranpatruller", o="Döda $1oa Dalaranframmanare och $2oa elementarslavar och återvänd sedan till magus Voidglare i Tarrens kvarn.", d="Innan den mystiskt försvann fanns det en enorm magisk barriär runt den nyuppbyggda staden Dalaran. Jag bryr mig inte om vad som fick ett sådant magiskt under att brista, men jag bryr mig om att stadens nyss blottade utkanter kan gömma värdefulla magiska skatter. Lämningar av ruinerna som den nya staden är byggd på. $B$BMen området patrulleras av trollkarlarna och deras elementarslavar.$B$BSå jaga dem, och kom tillbaka när deras antal har minskat tillräckligt."}, -- quests-batch-02-sv
[550]={t="Slaget vid Hillsbrad", o="Lämna Darthalias förseglade rekommendationsbrev till Varimathras i Understaden.", d="Eftersom du stred med sådan tapperhet och uthållighet i slaget vid Hillsbrad har jag skrivit detta rekommendationsbrev, som hyllar dina heroiska insatser i strid så att den högsta ledningen kan erkänna dem.$b$bLämna detta förseglade rekommendationsbrev till Varimathras i Understaden. Gå med stolthet, $c."}, -- quests-batch-11-sv
[552]={t="Helculars hämnd", o="Hämta Helculars stav från yetin och ta med den till novis Thaivand i Tarren Mill.", d="Mästare Helcular var nästan färdig med sin förvandling till en Lich när en lynchmobb av människor upptäckte hans rituallya i kullarna och brutalt dödade honom. För att göra saken värre begravde de hans lik på kyrkogården i Sydstrand.$b$bEtt sådant förakt för den store trollkarlen är oacceptabelt. Som hans lärling ska jag se till att hämndens regn faller över staden Sydstrand.$b$bVi behöver först Helculars stav. Yetier tog över hans rituallya. Utan tvekan har ett av odjuren den."}, -- quests-batch-07-sv
[553]={t="Helculars hämnd", o="Ladda Helculars stav med krafterna från Azels flamma, Verazs flamma och Uzels flamma.$b$bSätt ner den laddade staven i Helculars grav i Sydstrand.", d="Här, ta Helculars stav. Du kommer att behöva den.$b$bHelcular skapade tre ceremoniella bål som en del av sin mäktigaste besvärjelse. Azels flamma och Verazs flamma finns i Förbergsgrottorna. Uzels flamma finns i en grotta ovanför grottorna, längre norrut i bergen.$b$bHelculars stav måste laddas från var och en av de tre flammorna. När ritualen är fullbordad, sätt ner staven i Helculars grav i Sydstrand, den hårt bevakade människostaden i söder. Hämnen ska bli vår!"}, -- quests-batch-09-sv
[556]={t="Stentokens", o="Lämna 10 slitna stentokens till Keeper Bel'varil i Tarrens kvarn.", d="En anmärkningsvärd talang hos magikerna i Dalaran är deras bekantskap med elementaler: kraftfulla varelser från andra dimensioner. Magikerna använder magiska tokens som ett sätt att kontrollera dessa elementaler. Magus Voidglare skulle vilja ha några av dessa tokens för att studera dem.$B$BGå in i Dalaranmagikernas territorier, väster om Hillsbrad, och samla in tokens.$B$BDu kan hitta tokens hos vilken medborgare i Dalaran som helst, men jag föreslår att du jagar vid interneringslägret. Det är säkrare än Dalaran självt."}, -- quests-batch-02-sv
[557]={t="Bindningens armskydd", o="Ta med 4 Armskydd av jordbindning till väktare Bel'varil i Tarrens kvarn.", d="Magus kommer att vara upptagen med att studera de där stenbrickorna du samlade, men jag vet att han så småningom vill ha exemplar av deras motsvarighet: bindningens armskydd.  De sätts runt handlederna på verkliga elementarer och binder dem i magikerns tjänst.$B$BJaga elementarer i Dalarans ruiner och samla deras Armskydd av jordbindning, så blir Magus nöjd."}, -- quests-batch-09-sv
[568]={t="Försvaret av Grom'gol", o="Befälhavare Aggro'gosh vid Grom'gols basläger vill att du dödar 15 piskvansraptorer.", d="Throm'ka, $c!$b$bDin ankomst till Grom'gol är sannerligen i rätt tid. Som befälhavare för krigsledarens basläger här i djungeln är jag bunden av heder att garantera säkerheten för alla medlemmar av Horden. Vårt uppdrag att tillhandahålla en säker försörjningskedja till Stonard hindras av några av de lokala invånarna.$b$bJag sätter dig ansvarig för att gallra ut raptorpopulationen utanför Grom'gol. När du har gjort betydande framsteg, rapportera tillbaka till mig för omplacering."}, -- quests-batch-32-sv
[570]={t="Mok'thardins förtrollning", o="Fjärrsiare Mok'thardin vid Grom'gol-baslägret vill ha 8 Shadowmaw-klor och en fläckfri tigerrandshuggtand.", d="Djungelmagins kraft måste förstås och sedan tämjas av Horden. Mina ritualer har varit framgångsrika hittills. Jag kan kasta mycket kraftfulla förtrollningar. För dig, tappre $c, ska jag skapa ett sannerligen speciellt föremål.$b$bTa med mig några klor från Shadowmaw-pantrar tillsammans med en tigerrandshuggtand. Inte vilken tand som helst duger. Den måste vara i fläckfritt skick.$b$bBestarna lurar i hela djungeln, men du kommer att hitta några i närheten, precis över floden från Mizjah-ruinerna i sydost."}, -- quests-batch-25-sv
[571]={t="Mok'thardins förtrollning", o="För med dig en åldrad gorillsena till fjärrseende Mok'thardin i Grom'gol.", d="Det jag behöver av dig nu kommer att vara mycket svårt att få tag på.$b$bFör att hålla alla dessa fjädrar, klor och den fläckfria beten på plats behöver jag ett magiskt fäste. Endast en åldrad gorillsena kommer att fungera.$b$bDu kan bara hitta en sådan på en äldre Mistvale-gorilla. De är kända för att söka föda öster om Bytesbukten.$b$bSenan måste vara perfekt. Det kan krävas en hel del dödande innan du hittar precis det jag behöver, men det kommer att vara väl värt jakten."}, -- quests-batch-32-sv
[572]={t="Mok'thardins förtrollning", o="Ta med 10 Djungellurpassarfjädrar till Fjärrsiare Mok'thardin vid Grom'gol-baslägret.", d="Sakerna du samlade från de kattlika bestarna i dalen är bara det första kravet för ett mäktigt förtrollat föremål.  Dessa djungelprylar i kombination med min shamanistiska ritual ger dig ett mycket användbart verktyg för att hjälpa Horden och Krigshövdingen.$b$bMen nu måste du samla några Djungellurpassarfjädrar åt mig.  Fjädrarna bärs traditionellt av bestarna på deras armband.  Du hittar en stam av raptorer rakt söder om Grom'gol, inte långt från den stora arenan."}, -- quests-batch-24-sv
[573]={t="Mok'thardins förtrollning", o="Fjärrsiare Mok'thardin i Grom'gol behöver heligt källvatten. Han vill också att du dödar 10 nagaupptäckare.", d="Det finns bara en sista ingrediens kvar för att slutföra förtrollningen.$b$bI söder, mot västkusten, högt ovanför klipporna, ligger en helig källa. Denna källa är föremål för stora konflikter mellan religiösa och mystiska lärda. Varje ras i Azeroth hävdar att källvattnet gjordes gudomligt för just deras folk.$b$bMin sista begäran till dig: hämta heligt källvatten till mig. Var varnad. En expedition av nagaupptäckare har avancerat mot källan. De måste också tas om hand."}, -- quests-batch-19-sv
[575]={t="Utbud och efterfrågan", o="Ta med 2 stora flodkrokoliskskinn till Drizzlik i Bytesbukten.", d="\"Södra havens och den gamla och nya världens främste läderhantverkare.\" Så kallar de mig. Mig! Drizzlik! Den främste läder... Hm. Ja.$b$bMina lädervaror är kända vida omkring som de mest utsökta, en kännares val!$b$bJag har just fått en beställning från direktör Riddlevox i Mekanikerförbundet på ett dussin av hans favorit Excelsior-stövlar. Våra storsäljare, faktiskt.$b$bFör att börja med grundformen behöver jag krokoliskskinn från krokodilerna längs floden i norra Strypetörnsdalen."}, -- quests-batch-10-sv
[576]={t="Håll ögonen öppna", o="Dizzy One-Eye i Bytesbukten vill att du hämtar hans öga från Blodseglens bukanjärer.", d="Ahoj!  Vem där?$b$bArgh, jag är bara värdelös utan mitt speciella förtrollade öga.  Illa nog att ha förlorat mina ögon i strid till att börja med!  Men av en slump lade vi till i Menethil och en resande trollkarl förtrollade ett speciellt glasöga som lät mig se igen.$b$bIgår kväll blev jag överfallen av några Blodseglens bukanjärer på väg ut.  Tog mitt öga, de gjorde!  Det verkar som att de där karlarna har hittat till Bytesbukten.$b$bHjälp en gammal sjöbuss och få tillbaka mitt öga?"}, -- quests-batch-20-sv
[581]={t="Jakten på Yenniku", o="Lämna 9 Bloodscalp-betar till Nimboya vid Grom'gol-baslägret.", d="En undergång, det finns. En undergång över min hövdings yngsta son, Yenniku. Enligt vår folks sed gavs han till Gurubashi-trollen i Zul'Gurub, men efter att min stam, Mörkspjutsstammen, lämnade med orchen Thrall, gick stackars Yenniku förlorad för oss. Jag skickades från fjärran Orgrimmar, tillbaka till Strypetörnsdalen, för att leta efter min hövdings son.$B$BAnd jag tror att Bloodscalp-stammen har honom.$B$BOm du vill hjälpa mig, jaga då Bloodscalps. Du kan finna dem i norr. Samla deras betar och återvänd till mig."}, -- quests-batch-32-sv
[584]={t="Blodskalpklanens huvuden", o="Ta med Gan'zulahs huvud och Nezzlioks huvud till den bubblande kitteln vid Grom'gol-baslägret.", d="Yenniku fanns inte bland huvudena, och jag tackar den Stora ormen för det.  Men vi är inte närmare att hitta honom.$B$BVi måste få veta sanningen, och jag fruktar att bara Blodskalp-hövdingen och hans häxdoktor känner till den.  De är fiender till Mörkspjutsstammen och talar inte fritt, så vi måste tvinga fram sanningen ur deras döda läppar!$B$BTa med mig huvudena av Gan'zulah och Nezzliok den Fruktansvärde och placera dem i den här kitteln.$B$BDe finns djupt inne i Zul'Kunda.  Ta med deras huvuden ... så får vi dem att tala."}, -- quests-batch-27-sv
[585]={t="Samtal med Nezzliok", o="Ta med en Balia'mah-trofé, en Ziata'jai-trofé och en Zul'Mamwe-trofé till den bubblande kitteln vid Grom'gol-baslägret.", d="<Nezzlioks huvud talar.>$B$BDet är sant.  Jag vet vart Mörkspjutens barn fördes.  Du har besegrat mig och bundit min ande, men jag säger ingenting utan blidkande!$B$BBlodskalparna ligger i krig med Skullsplitterna.  För att vinna min ynnest, stjäl 3 av deras trofékranier från Skullsplitterna och placera dem här hos oss, så att min ande får slavar i Nether.  Ett kranium måste vara från deras trofébunt i Balia'mah, ett annat från Ziata'jai och det sista från Zul'Mamwe."}, -- quests-batch-31-sv
[586]={t="Samtal med Gan'zulah", o="Döda 8 Skullsplitter-jägare, 6 Skullsplitter-huvudjägare och 4 Skullsplitter-berserker.$B$BFör Ana'theks sönderslagna rustning till den bubblande kitteln i Grom'gol-baslägret.", d="<Gan'zulahs huvud talar.>$B$BFörbanna dig! Och förbanna dina förfäder!!$B$BEndast blod och hämnd kan kyla min vrede, så om det är din önskan ... gör detta:$B$BKasta dig in i hjärtat av Skullsplitternas land österut. Dräp de vildaste bland dem, och om du överlever ... krossar du dig mot deras hövding, Ana'thek den Grymme. Hah! För mig hans sönderslagna rustning om du kan!$B$BMå han riva av dig lemmarna och lämna dig att ruttna och ätas av asätare."}, -- quests-batch-19-sv
[595]={t="Blodseglens bukanjärer", o="Förste styrman Crazz vill att du undersöker viken norr om Bytesbukten.", d="Du verkar verkligen ivrig att arbeta, kamrat. Vet inte varför någon landkärring till $r $c erbjuder hjälp till Blackwater-plundrarna, men jag tänker inte neka dig.$b$bVårt skepp har precis lagt till här i Bytesbukten och ryktet säger att våra rivaler – dessa förbannade, smutsiga Blodseglens bukanjärer – har siktats över hela södra Strypetörnsdalen.$b$bAlla grabbarna är för upptagna med att dricka grog och leta efter damer! Vad jag behöver är en spanare.$b$bUndersök viken precis norr om Bytesbukten längs Vilda kusten och se vad du hittar."}, -- quests-batch-30-sv
[596]={t="Blodiga benhalsband", o="För med dig 25 blodiga benhalsband till Kin'weelay vid Grom'gol-baslägret.", d="Jag skickades till Grom'gol för att hjälpa Nimboya i hans sökande, men... jag har också mina skäl till att vara här.$B$BBlodskalpstammen är vår stams fiende. Att samla troféer från våra fiender ger oss makt över dem. Du kan hjälpa vår stam genom att jaga våra fiender.$B$BDe bor i norr. Dräp Blodskalptroll och ta deras blodiga benhalsband. Samla många, så kommer din belöning att bli stor."}, -- quests-batch-07-sv
[598]={t="Kluvet benhalsband", o="Ta med 25 kluvna benhalsband till Kin'weelay vid Grom'gol-baslägret.", d="Nu när du har samlat Blodskalp-troféer har jag en uppgift till åt dig.  Skullsplitter-trollstammen bor i sydost, och i åratal har vi legat i krig med dem.  Även om Mörkspjutstrollen inte längre bor i Strypetörnsdalen är vi bundna till vår konflikt med Skullsplitterna.$B$BSå, jaga dem.  Samla deras kluvna benhalsband och återvänd till mig.  Hjälp oss i vårt krig, så vinner du Mörkspjutstrollens vänskap."}, -- quests-batch-26-sv
[604]={t="Blodseglens bukanjärer", o="Flottmästare Seahorn i Bytesbukten vill att du dödar 10 Blodsegelsvärdsvingare och tar med Blodsegelskartor och Blodsegelsorder.", d="Crazz talar väl om ditt engagemang för Blackwaters pirater. Jag tänker anförtro dig ett uppdrag av yttersta vikt för flottan.$b$bInfiltrera den så kallade södra kommandoposten som Blodseglens bukanjärer har upprättat på Vilda stranden.  Plundra lägret.  Ta med mig deras kartor tillsammans med deras skrivna order.  Vi får se exakt vad det avskummet har för sig."}, -- quests-batch-21-sv
[605]={t="Sjungande blå skärvor", o="Lämna 10 sjungande kristallskärvor till Crank Fizzlebub.", d="De sjungande kristallerna är unika för Strypetörnsdalen och är mycket värdefulla för vissa parter. Jag kan sälja dessa kristaller, men den förbannade Äventyrsbolaget gör det svårt för en ärlig entreprenör som jag att samla in några!$B$BJag skulle vilja anställa dig.$B$BBasilisker i Strypetörnsdalen äter kristallen. Detta ger dem deras härdade hud, och ibland kan kristaller av anständig kvalitet skördas från den.$B$BDu kan få dem från vilken basilisk som helst, men de mindre elaka finns längs kusterna söder om Zul'Kunda, i norr."}, -- quests-batch-24-sv
[606]={t="Skrämma Shaky", o="Ta 5 Mistvale-inälvor till \"Shaky\" Phillipe i Bytesbukten.", d="Om det är en sak jag inte kan stå ut med, så är det folk som inte betalar sina spelskulder! Och det finns många som är skyldiga mig. Tror du att du kan hjälpa mig att driva in dem?$B$BFörst har vi \"Shaky\" Phillipe nere vid dockorna. Han är skyldig mig gott och väl efter förra veckans spel och jag vill ha min rätt! Men för att få den måste vi skrämma honom.$B$BGå ut ur staden och jaga äldre Mistvale-gorillor. Hitta ett fint urval av inälvor och ta dem sedan till Shaky. Låt honom inte ana att de kommer från ett djur; låt honom tro det värsta."}, -- quests-batch-24-sv
[609]={t="Voodoo-skulder", o="Ta med Maurys klumpfot, Jon-Jons gyllene tubkikare och Chuckys jättestora ring till \"Sea Wolf\" MacKinley i Bytesbukten.", d="Min lista blir kortare, men det finns fortfarande folk som är skyldiga mig.$B$BNästa är Maury \"Club Foot\" Wilkins, Jon-Jon the Crow och Chucky \"Ten Thumbs.\"$B$BDessa skabbiga hundars skulder har varit obetalda i månader och jag trodde att de stack från stan för att slippa betala!  Senare hörde jag att de är förbannade och förhäxade och nu vandrar omkring bland djungelruinerna.  Men jag bryr mig inte om vad som blir av dem - jag vill ha det som är mitt!$B$BDe finns vid Aborazruinerna och Jubuwalruinerna, nordost om här.  Hitta dem och driv in."}, -- quests-batch-19-sv
[617]={t="Akiris i knippen", o="Ta med 10 knippen akirisvass till kaparen Bloads i Bytesbukten.", d="Letar du efter jobb, $n? Jag kanske har något om du är sugen på en liten utmaning.$B$BJag har en vän som heter Groy som tjänar storkovan på att sälja det nagorna kallar akirisvass: någon sorts värdefull havsvass. Jag vet inte riktigt vad den ska användas till, men han betalar bra för knippen av grejerna.$B$BDu tar med mig tio strån av grejerna, så ska vi göra affärer. Nagorna sågs senast längs stranden norr om här."}, -- quests-batch-21-sv
[621]={t="Zanzils hemlighet", o="Ta med 12 prover av Zanzils blandning till Crank Fizzlebub i Bytesbukten.", d="Zanzil den Förskjutne bor med sina anhängare i Jubuwai- och Aborazruinerna, nordost om Bytesbukten.  Han är förvisad från sin stam.  Varför? Tja ...$B$BZanzil har metoder för att böja andras sinnen, och hans ledare fruktar honom.  Han använder en blandning av djungelväxter på sina anhängare för att undertrycka deras vilja och stärka deras kroppar.$B$BHans blandning vore värd mycket för dem som vill kontrollera andra.$B$BTa med mig prover av hans blandning, så hittar jag en användning för dem."}, -- quests-batch-19-sv
[628]={t="Excelsior", o="Ta med ett skinn från åldrig krokolisk till Drizzlik i Bytesbukten.", d="När insidan är klar återstår bara att lägga till det yttre lagret. För detta använder jag bara de bästa åldriga krokodilskinnen. De är mer hållbara och en bättre duk--om man så vill--för att lägga till de mönster och accenter som gör Drizzliks Excelsior-serie.$b$bDet är svårt att hitta det perfekta skinnet, dock, det enda som passar min plan är skinnet från en åldrig saltvattenkrokolisk. De åldriga kommer bara ut för att försvara de andra saltvattenkrokoliskerna, så du kan behöva döda några för att locka fram en."}, -- quests-batch-28-sv
[629]={t="Det vidriga revet", o="Lämna ett tavelskärva till Kin'weelay vid Grom'gol-baslägret.", d="För länge sedan sänkte en stor jordbävning en gammal trollstad under vattnen vid Vilda kusten i nordväst. Vi kallar den platsen för Det vidriga revet, för murlocs bor nu i stadens ruiner och attackerar alla som kommer nära.$B$BDet finns en gammal tavla bland dessa ruiner som berättar den forna sagan om Gri'lek, en hjälte i trollens legender. Sagan är helig för Mörkspjutstrollen, och även om tavlan är för stor för att flyttas, vill jag ha en skärva av den för att viga den i vårt nya hem i Orgrimmar."}, -- quests-batch-02-sv
[635]={t="Kristallen i bergen", o="Hitta kristallen från din vision.", d="Denna skärva pulserar när du håller i den...$B$BDu känner en känsla av bön från skärvan, som om någon försöker kommunicera, någon som desperat behöver din hjälp.$B$BEn vision dyker upp i ditt sinne - av de norra bergen i Arathi, och av en strålande kristall som sticker upp ur jorden där.$B$BDu känner dig dragen till den platsen."}, -- quests-batch-06-sv
[638]={t="Trollbane", o="Res till Hammarfall i Arathihöglandet och tala med Zengu.", d="Med Thoras Trollbane död och Stromgarde i ruiner har Vol'jin instruerat att vi gör allt för att smyga bort det legendariska svärdet Trol'kalar ur människornas händer, så att vi kan använda det i våra kommande strider mot trollen i Zul'Gurub.$b$bZengu, en av våra erfarna jägare, skickades till Hammarfall i nordöstra Arathihöglandet för att övervaka anskaffandet av det."}, -- quests-batch-19-sv
[639]={t="Stroms sigill", o="Hämta Stroms sigill till Zengu i Hammarfall.", d="I forntiden stred trollen mot Arathors imperium och vår mest kapabla motståndare, lord Ignaeus av Strom, kallad Trollbane. Han red i strid med Trol'kalar -- trolldräparen, på deras forntida tungmål.$b$bMen nu är Trollbanes söner försvagade och deras fäste lagt i ruiner.$b$bSvärdet skyddas av flera sigill som fördelades mellan de överlevande från Stromgarde, och vi måste återta dem.$b$bDet första togs av Syndikatet; en av deras män i Stromgarde borde ha det."}, -- quests-batch-09-sv
[640]={t="Det söndriga sigillet", o="Hämta de 11 sigillfragmenten från försvararna i Stromgarde och ta dem till Tor'gan i Hammarfall.", d="Thoras Trollbanes grav skyddas av tre sigill--det första hämtade du från Syndikatet. De andra två blir svårare att få tag på, eftersom de hålls av den fast förskansade Stromgarde-milisen.$b$bThoradins sigill delades i elva delar av Thoras son, Galen, och spreds bland Stromgardes försvarare. Hämta delarna och ta dem till Tor'gan, trollshamanen, han kan binda ihop dem till det kompletta sigillet."}, -- quests-batch-25-sv
[642]={t="Den fångna prinsessan", o="Samla 12 Myzraels stoftkorn och ta dem sedan till de Regnbågsskimrande skärvorna i Torrmustaschklyftan.", d="Mitt namn är Myzrael.  Jag är en jordens prinsessa, och mina fångvaktare, jättarna, har fångat mig djupt under Arathihöglandet.  Dessa kristallskärvor är det enda sätt jag kan tala med ytvärlden.$B$BVar snäll och hjälp mig.  Jättarnas allierade, Torrmustasch-kobolderna, har en skärva som den här i sin Torrmustaschklyfta, österut.  För att ge klustret kraft måste du samla Myzraels stoftkorn från kobolderna och applicera dem på det.$B$BJag ber dig, $n, hjälp mig!"}, -- quests-batch-30-sv
[643]={t="Arathors sigill", o="Hämta Arathors sigill och lämna det till Zengu i Hammarfall.", d="Även om man knappt kan säga att de kontrollerar Stromgarde, än mindre hela Arathihöglandet, trampar människoprinsen runt med resterna av sitt kavalleri över landsbygden. Jag kan inte förstå varför han gör det, men vem förstår hur människor tänker, hm?$b$bOavsett hans resonemang, och viktigare, har han gett ett av sigillen till löjtnant Valorcall, deras kavalleriledare. Hitta honom och ta tillbaka hans sigill till mig."}, -- quests-batch-23-sv
[644]={t="Trollbanes sigill", o="Döda prins Galen Trollbane och ta med Trollbanes sigill till Zengu i Hammarfall.", d="Det sista av sigillen som behövs för att låsa upp Thoras Trollbanes grav hålls personligen av hans son. Han bor djupt inne i Stromgarde, i ett kapell i de milisbevakade distrikten. Prins Galen är väl skyddad och själv ingen slöfock till krigare, så den här uppgiften kan visa sig mycket svår."}, -- quests-batch-27-sv
[645]={t="Trol'kalar", o="Hämta Trol'kalar från Trollbanes grav i Stromgarde.", d="Vad är detta? Med de fyra sigillen samlade har de förenats och bildat ett enda sigill. Det råder ingen tvekan om att detta kommer att kunna bryta skydden som lagts över Trollbanes grav.$b$bTrollbanes kvarlevor vilar i Helgedomen bakom kapellet i Stromgarde. Hämta Trol'kalar."}, -- quests-batch-26-sv
[651]={t="Bindningens stenar", o="Samla Brinnande nyckeln, Brusande nyckeln och Dundrande nyckeln från Västra bindningsstenen, Östra bindningsstenen och Yttre bindningsstenen.$B$BTa dem till Inre bindningsstenen.", d="Fyra bindningens stenar är utspridda över Arathi.  Dessa stenar håller mig fastnålad under jorden.$B$BFör att låsa upp dem måste du låsa upp den starkaste: Inre bindningsstenen.  Och för att göra det måste du samla nycklar från de andra tre.$B$BDessa stenar bevakas av väktare, men om du är listig, eller heldig, kan du hitta sätt att förvisa dem."}, -- quests-batch-26-sv
[652]={t="Bryta Nyckelstenen", o="Hitta och döda Fozruk.  Ta Ordningens stav till Nyckelstenen i Arathihöglandet.", d="När Bindningens stenar öppnades lossnade mycket av min fångenskap, men ett lås håller mig fortfarande bunden.  Det är Nyckelstenen du ser bland den här stencirkeln.  Och nyckeln hålls av en av mina fångvaktare, stenväktaren Fozruk.$B$BDu måste få tag på den nyckeln, som stenväktarna kallar Ordningens stav, från Fozruk och använda den för att öppna Nyckelstenen.$B$B$n, du har gjort så mycket för att hjälpa mig.  Bara lite till ... så ska min tacksamhet skaka jordens själva grundvalar!"}, -- quests-batch-23-sv
[655]={t="Hammarfall", o="Tala med Tor'gan i Hammarfall.", d="Det är fortfarande tydligt för mig, som i går ... Så många år utan hopp, med trä och stål som band mig vid den här fruktansvärda platsen. Sedan äntligen, äntligen! Där var Krigshövdingen. Domedagshammaren i sin midnattsplåt, sin krigshammare höjd.$b$bDet var ... alltför fruktansvärt ... Att en fegis slag skulle fälla vår störste hjälte. Bakifrån stormade han på sin häst, och sedan genomborrade hans lans honom ... Jag föll på knä. Vilket hopp fanns det? Vilket hopp finns det ..."}, -- quests-batch-15-sv
[656]={t="Frammaning av prinsessan", o="Gå till Shards of Myzrael, frammana henne och besegra henne.$B$BSamla hennes Eldritch Shackles och bind dem vid Shards of Myzrael.", d="Du måste besegra Myzrael innan hon växer i styrka. Om du inte gör det, kommer hon att utmana sina fångvaktare så snart hon har samlat tillräckligt med kraft! Det finns vissa som tror att de kan kontrollera henne, men om hon kan kontrolleras, varför kedjade jättarna då fast henne från första början??$B$BGalen logik, va?$B$BFör att besegra henne, frammana henne vid Shards of Myzrael där du först talade med henne. Besegra henne och samla hennes Eldritch Shackles, och bind dem sedan vid Shards of Myzrael.$B$BGör det, så kommer hon återigen att bli fångad."}, -- quests-batch-29-sv
[671]={t="Vidrig magi", o="Hämta 10 blodstensamuletter till Tor'gan i Hammarfall.", d="Jag har känt något märkligt i luften... en känsla som sjuder i mitt blod. Jag hade mina misstankar. Jag gav mig av för att finna källan till mitt obehag och upptäckte i väster, vid Northfold Manor, kvarlevor av demonisk frammaning. När jag kom nära började mitt blod koka och vreden inom mig växte.$b$bPå marken fick jag syn på en amulett av blodsten, som används för att hjälpa till vid demonisk frammaning. Den jag fann var dock tömd. Jag behöver en annan att undersöka, men jag vågar inte återvända till herrgården. Kan du hämta några åt mig?"}, -- quests-batch-16-sv
[672]={t="Väcka andar", o="Samla 10 Highland Raptor-ögon från Highland Striders och Highland Thrashers till Tor'gan i Hammarfall.", d="Vi försökte få honom att komma till rätta, muntra upp honom genom att berätta historier om vår mäktiga stad Orgrimmar i Kalimdor, men inget hjälpte.$b$bBerättelser om vår unge krigsherre, Thrall, som bär Orgrims rustning och hammare... men, kanske... Kanske! En demonstration av vår nyfunna schamanistiska magi skulle ge honom nytt hopp. Det är värt ett försök!$b$bEtt litet föremål vi skulle kunna tillverka åt honom, ja... Hämta några raptorögon till mig, så ska jag se vad jag kan göra."}, -- quests-batch-12-sv
[673]={t="Orena magier", o="Hämta Marez Cowls blodstensglob och lämna den till Tor'gan i Hammarfall.", d="Jag är helt övertygad om att en mäktig häxmästare håller till inom Stromgardes murar. Med hjälp av en arkan magisk relik har denna häxmästare då och då frammanat fruktansvärda demoner i stora mängder. Vi måste avlägsna källan till hans energi.$b$bHitta häxmästaren och döda honom. För med dig det magiska föremål du finner på honom, så ska jag vidta åtgärder för att förstöra det och se till att dess kraft inte längre används för att besudla detta land."}, -- quests-batch-29-sv
[674]={t="Väcka andarna", o="Ge Raptorklosamulett till Gor'mul.", d="Här, ta den här amuletten till Gor'mul, och se om raptorernas styrka kan väcka lågan hos krigaren som en gång brann i hans ådror."}, -- quests-batch-08-sv
[675]={t="Väcka andarna", o="Tala med Tor'gan.", d="<Gor'mul slänger amuletten i marken.>$b$bTor'gan skickade dig, eller hur? Pah! Varför han känner någon barmhärtighet mot mig förstår jag inte. Barmhärtighet nekades mig när jag inte fick dö med min krigshövding i strid. Ett grymt slag har ödet utdelat ..."}, -- quests-batch-12-sv
[676]={t="Hammaren kan falla", o="Döda 8 Boulderfist-oger och 10 Boulderfist-ordningsvakter, och leta sedan upp Drum Fel i Hammerfall-utposten i Arathihöglandet.", d="Vecklingar... varenda en. Du, $c, vad glor du på? Tror du att du är något speciellt, va? Varför bevisar du det inte?$B$BHammerfall-utposten i Arathi är under attack. Om vi inte skickar hjälp snart är deras undergång nära.$B$BMen innan du rusar iväg vill du kanske testa dina färdigheter först. Nordost om Stromgarde i Arathi finns en ogerkulle där Boulderfist-stammen bor. När du kan hantera ogerna och ordningsvakterna där, rapportera då till Drum Fel i Hammerfall."}, -- quests-batch-04-sv
[677]={t="Kallelse till vapen", o="Döda 10 Vissenbark-yxkastare, 10 huvudjägare och 8 häxdoktorer, och återvänd sedan till Drum Fel i utposten Hammarfall.", d="Vissenbarkstrollen och Boulderfist-ogerna i Arathi samarbetar för att göra sig av med oss här, men vi ska inte möta vårt öde i deras eller någon annans händer. Vi ska slå ned dem och visa dem att också vi har ett hem här. $B$BTrollen vände oss ryggen; ogerna skulle använda oss som mat och sängkläder om vi lät dem--sådant ska inte ske.$B$BVi inleder vårt angrepp mot Vissenbarkstrollen söder om här. Slakta dem i drivor, och återvänd först när deras läger dryper av blod."}, -- quests-batch-01-sv
[679]={t="Kallelse till vapen", o="Döda 15 Boulderfist-schamaner och 10 Boulderfist-herrar och återvänd till Drum Fel i utposten Hammerfall.", d="Bestens huvud är redo att huggas av... med stor kraft, $n. Du har visat alla tecken på att du kan hjälpa oss med detta sista mäktiga slag. Ledarna för dessa attacker har gjort sitt läger i ruinerna av Stromgarde, en tydlig symbol för människans svaghet.$B$BHitta och dräp dessa Boulderfist-herrar och deras hantlangare till schamaner som försöker driva oss från dessa marker."}, -- quests-batch-24-sv
[680]={t="Det verkliga hotet", o="Dräp Or'Kalar och för hans huvud till Korin Fel i utposten Hammarfall.", d="Du tjänar min make väl, $c, men han vet inte varför Hammarfall är under attack.$B$BOr'Kalar, Mug'thols bricka i Stromgarde, hyser ett intensivt hat mot min make och önskar inget hellre än min makes död för att han besegrade honom för många år sedan.$B$BMina varsel säger mig att Or'Kalar har lagt en fälla för min make, så jag har dolt tecknen på ogerns närvaro för honom.$B$BMin make kommer att rusa iväg dåraktigt om han får reda på var ogern befinner sig, så jag ber om din hjälp att dräpa varelsen."}, -- quests-batch-30-sv
[687]={t="Theldurin den förlorade", o="Hitta Theldurin den förlorade.", d="Theldurin den förlorade var en gång medlem i vår orden, Skymningshammaren. Men han förlorade förståndet och föraktade våra läror. Och innan han flydde från oss stal han Myzraels rulle! Vi kunde inte fånga honom, men rykten säger att han gömmer sig i Ofärdsmarken, jattrande och galen.$B$BFör att föra Lady tillbaka till oss måste du hitta rullen. Och för att göra det måste du hitta Theldurin."}, -- quests-batch-32-sv
[698]={t="Brist på överskott", o="Lämna 8 oförberedda sågtandssidor till Tok'Kar i Sorgeträsket.", d="Jag arbetar med att samla ihop förnödenheter till vår utpost nära stranden i öster – Tok'kar gör vad han kan, men mellan vaktskiften och matlagning till sina soldater finns det inte mycket tid kvar på dagen.$B$BDe tycker om att tillaga sågtandskött när de kan, men jag har inte haft tid att skicka dem en ny leverans. Skulle du vilja hjälpa dem?$B$BDe unga sågtänderna är inte lika goda som de äldre, så håll dig borta från dem; låt dem växa i ett år eller två tills de nått full storlek."}, -- quests-batch-32-sv
[701]={t="Raptorns list", o="Skaffa 12 raptorhjärtan från Höglandsköttlurpassare åt Tor'gan.", d="Med några ytterligare föremål kommer jag att kunna skapa ett föremål som fyller Gor'mul med raptorns list! Med raptorns kraft flödande genom honom kommer Gor'mul att känna vår nya makt och återupptäcka krigaren som slumrar inom honom!$b$bJag kommer att behöva raptorhjärtan för att tillverka föremålet och besvärjelsen."}, -- quests-batch-28-sv
[703]={t="Grillade vråkvingar", o="Ta med 4 vråkvingar till Rigglefuzz.", d="Åh ja, mina grillade vråkvingar är en favorit!  Såsen är fyllig och köttet pikant.  Och doften lockar de hungriga springande från mils avstånd!$B$BJag har allt jag behöver för att laga en sats.  Allt ... utom vråkvingarna!$B$BOm du vill ha några så skaffa mig vråkvingarna.  Ta med tillräckligt mycket, så delar jag kanske till och med receptet med dig!"}, -- quests-batch-22-sv
[705]={t="Pärldykning", o="Lämna 9 blå pärlor till Rigglefuzz i Ofärdsmarken.", d="Ofärdsmarken är en hård plats, fylld med grymma rovdjur och djärva asätare. Skrämmande, särskilt för en liten kort gnom. För att överleva måste jag vara slug!$B$BJag kan receptet på blixtbomber. Jag använder dem för att skrämma bort vilda djur. Men jag börjar få slut på en av ingredienserna: krossat blått pärlpulver. Skaffa åt mig lite så ska jag se till att det lönar sig.$B$BHeh, och jag hoppas att du har bra stövlar på dig. De blå pärlorna jag behöver finns i musslor vid Vidrigrevet.$B$BJapp, Vidrigrevet i Strypetörnsdalen!"}, -- quests-batch-24-sv
[709]={t="Lösningen på undergången", o="Lämna Ryun'ehs tavla till Theldurin the Lost.", d="O herregud! O herregud! En undergång närmar sig. Märk mig! En undergång!$B$BNej, jag kan inte tala om det... kan inte uttala deras namn ifall de hör mig! Men om vi får veta, ja, om vi får veta mer om dem... då kan vi kanske lära oss hur vi stoppar dem!$B$BKanske.$B$BGå in i Uldaman. Nej! Jag sa det! Du måste hitta... hitta tavlan av... Ryun'eh. Ja, hitta den! Och få mig inte att uttala det namnet igen!$B$BDen finns djupt inne på den platsen, i en uråldrig kista. Det är där den gömmer sig... i en kista tillverkad före något dvärgarbete."}, -- quests-batch-27-sv
[712]={t="Studier av elementen: Sten", o="Lämna 5 Bracers of Rock Binding till Lotwil Veriatus i Ofärdsmarken.", d="$n, det finns ytterligare en del jag behöver från elementalen här i Ofärdsmarken: Bracers of Rock Binding från de större stenelementalerna. Enligt mina beräkningar bör dessa handledsskydd räcka för att mäta styrkan i mina egna bojor.$B$Bmina försök att spåna efter de större stenelementalerna visade en grupp av dem sydväst om här, nära några oger om jag minns rätt.$B$BBring mig 5 av deras handledsskydd så att jag har extra. Servo är ökänd för att komma bort med mina reagenser och forskningsmaterial."}, -- quests-batch-32-sv
[713]={t="Kylmedelshuvuden segrar", o="Hitta frostolja och lämna den till Lotwil Veriatus i Ofärdsmarken.", d="Låt mig berätta något om frostolja: inget kan förhindra en motor eller kugghjul från att överhettas så effektivt som det.$B$BDess kylande egenskaper är extraordinära, och dess hållbarhet som smörjmedel är utan like. Det är inte allt: det hjälper även till att bevara förtrollningar på magiska föremål.$B$BJag behöver en flaska av det för att öka den magiska kapaciteten i mina bojor och göra dem kraftfulla nog att stoppa vår frammanade vän från att döda oss alla.$B$BBro'kin, en goblinvän till mig, kan lära dig att tillverka det. Han finns i Alterac."}, -- quests-batch-32-sv
[1048]={t="In i Scharlakansklostret", o="Döda High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion och Houndmaster Loksey och rapportera sedan tillbaka till Varimathras i Understaden.", d="Medan den mörka damen tar hand om den pressande frågan om Lichkungens frammarsch i norr, ser jag till att angelägenheter närmare hemmet tas om hand på ett tillbörligt sätt.$b$bUtan tvekan är de mänskliga skadedjuren som kallar sig Scharlakanskorståget den vassaste törnen i vår sida här hemma. Tirisfalgläntorna kryllar bokstavligen av små röda myror.$b$bRes till klostret, $c, och förgör High Inquisitor Whitemane och hennes främsta löjtnanter."}, -- quests-batch-10-sv
[1049]={t="De fallnas kompendium", o="Hämta De fallnas kompendium från klostret i Tirisfalgläntorna och återvänd till Sage Truthseeker i Dunderklippan.", d="Jordringen hade rena avsikter gentemot våra pestdrabbade bröder. Men vem kan veta motiven hos dem som viskar i Äldsterådets öron?$b$bDe bortglömda som vi har allierat oss med har en historia präglad av svek. Vårt pakt var alltför förhastad. Kanske hade Cairne varit klok i att lyssna på varningarna från Orgrimmar.$b$bDjupt inne i Scharlakansklostret ligger De fallnas kompendium, bevakat av galna mänskliga fanatiker. Deras metod är smidd av vansinne, men deras forskning kan visa sig vara användbar."}, -- quests-batch-04-sv
[1050]={t="Titanernas mytologi", o="Hämta Titanernas mytologi från klostret och ta den till bibliotekarie Mae Paledust i Järnsmedjan.", d="Framtiden är oundviklig! Vi kastar oss mot den som fallande regndroppar mot Stora havet.$b$bMen kanske kan vi, genom att studera det förflutna, veta vad vi kan vänta oss och vara bättre förberedda på det okända.$b$bInnan svåra olyckor drabbade Lordaeron fanns det ett kunskapens bålverk undanstoppat i Tirisfalgläntorna. Det ryktas att en bok kallad Titanernas mytologi fanns i det gamla klostrets bibliotek.$b$bTa den till mig och kanske kan vi tillsammans låsa upp det förflutnas hemligheter!"}, -- quests-batch-05-sv
[1051]={t="Vorrels hämnd", o="Lämna tillbaka Vorrel Sengutz vigselring till Monika Sengutz i Tarrens kvarn.", d="Även om min vilja är fri kan jag inte tjäna Mörka damen längre. Jag känner att min tid på Azeroth har tagit slut. Min livskraft är krossad.$b$bFörhörsledare Vishas gjorde detta mot mig! Torterade mig i veckor! Tog min vigselring och gav den till sin fru. Den jäveln!$b$bHämnd ... jag vill ha hämnd!$b$bDen pompösa dåren skröt om sin dyrbara fru, Nancy, som bodde vid Lordameresjön. Spåra upp kvinnan, döda henne och lämna tillbaka min vigselring till min fru, Monika i Tarrens kvarn.$b$bBeakta mina sista önskningar ...."}, -- quests-batch-15-sv
[1053]={t="I Ljusets namn", o="Döda höginkvisitor Whitemane, Scharlakansröd befälhavare Mograine,  Herod, den Scharlakansröde kämpen, och hundmästare Loksey och rapportera sedan tillbaka till Raleigh den fromme i Sydstrand.", d="Jag tjänade en gång Scharlakanskorståget med heder, lojalitet och stolthet. Jag trodde att deras sak var ädel: att befria Azeroth från de odöda.$b$bMen medan jag vistades i klostret i Tirisfalgläntorna insåg jag att deras grepp om verkligheten höll på att slippa. De tror nu att alla är pestsmittade som inte bär korstågets vapenrock. Oskyldiga män och kvinnor torterades för att de förmodades vara pestsmittade. $b$bScharlakanskorståget måste krossas i Ljusets namn. Du, $n, måste förgöra den sinnessjuka regimen."}, -- quests-batch-12-sv
[1101]={t="Käringen i snårskogen", o="Ta med Razorflanks medaljong till Falfindel Waywarder i Thalanaar.", d="Stackars Heralath! Och den här dvärgen ... Lonebrow. Vilken modig själ han var.$b$bVi får inte låta deras tapperhet vara förgäves. Den här käringen ... Charlga Razorflank ... måste stoppas.$b$bDet kommer säkert att vara farligt att infiltrera snårskogen. Det finns inte tid att skicka bud till Darnassus. $n, samla ett sällskap för att döda käringen.$b$bTa med mig Razorflanks medaljong som bevis på hennes död."}, -- quests-batch-30-sv
[1102]={t="Ett hämndlystet öde", o="Ta med Razorflanks hjärta till Auld Stonespire i Dunderklippan.", d="Cairne är en ädel ledare som har enat vårt folk här på Dunderklippan.$b$bMen jag kan inte förlåta dem som drev oss från våra förfäders land lika lätt som vissa. Mitt folk bebodde södra Kargmarkerna i decennier. Landet var heligt för oss. Men vi drevs bort av många fiender.$b$bEtt hämndlystet öde väntar käringen Charlga Razorflank, som samlar en vidrig armé inifrån Knivkärrets snårskog.$b$bTa med mig Razorflanks hjärta så kan jag dö i frid, $n."}, -- quests-batch-11-sv
[1106]={t="Martek den landsförvisade", o="För Fizzles brev till Martek den landsförvisade i Ofärdsmarken.", d="Jag utvecklar en ny motor som kommer att få bilen att gå så snabbt! Snabbt nog att flyga, jag vet det! Jag behöver bara tillverka kolvar som tål mycket, mycket hög belastning. Alla mina försök har misslyckats eftersom jag inte kan göra kolvarna tillräckligt hårda!$B$BMen det finns någon som kanske vet hur.$B$BHans namn är Martek den landsförvisade. Han är en stor smed och vet mer om metall än någon annan. Ge honom det här brevet, jag vet att han kan hjälpa till!$B$BMen han är långt, långt borta -- i Azeroth, i Ofärdsmarken, i ett läger, med en gnom!$B$BHitta honom!"}, -- quests-batch-22-sv
[1107]={t="Inkrusterade stjärtfenor", o="För 10 inkrusterade stjärtfenor till Wizzle Brassbolts på Glittrande slätterna.", d="Vår raketbil är det snabbaste på slätterna! Så snabb att ... jag är rädd att friktionen kommer att slita isär den!$B$BFör att förhindra det behöver jag skapa ett kompositmaterial för att belägga bilens rörliga delar. Det måste vara hårt men inte sprött, och måste vara resistent mot saltkorrosion, annars kommer tiden på Glittrande slätterna att fräta bort det.$B$BHar du hört talas om Vidriga revet, $n? Det ligger utanför kusten av Stranglethorn Vale. Saltfjällsmurlocs lever där, och deras stjärtfenor är en avgörande ingrediens i mitt kompositmaterial."}, -- quests-batch-21-sv
[1109]={t="Går, går, guano!", o="Lämna 1 hög Kraulguano till mästerapotekare Faranell i Understaden.", d="Som du ser, $n, ägnar vi oss åt några mycket... intressanta experiment här vid det kungliga apotekarsällskapet.$b$bSom mästare här är det mitt jobb att övervaka våra mest ambitiösa alkemiska försök. Så mycket arbete och så lite tid!$b$bDu ser ut att ha rest mycket för att vara en $c. Kanske kan du hjälpa mig.$b$bJag behöver ett sällsynt ämne. Det är ett vidrigt material som kommer från en sällsynt art fladdermöss som bara finns i dynghålet känt som Knivkärrets snårskog. För med mig guanon från Kraulfladdermössen så att vi kan påbörja vårt arbete..."}, -- quests-batch-11-sv
[1110]={t="Raketbilsdelar", o="Ta med 30 raketbilsdelar till Kravel Koalbeard på Skimmerslätterna.", d="Hehe, med alla tävlingar som körs här är det inte konstigt att några missöden inträffar på vägen.  Om du tittar dig omkring på Skimmerslätterna ser du spår av tidigare krascher -- skrot från raketbilsdelar ligger utspritt överallt!$B$BOch de delarna är värda pengar för gnomerna och goblinerna.  De letar alltid efter fler påfund att klämma fast på sina bilar.$B$BSå ge dig ut och skaffa delar åt mig.  Ta med dig en hög så betalar jag dig väl."}, -- quests-batch-03-sv
[1111]={t="Hamnmästare Dizzywig", o="Ta med Kravels beställning av delar till hamnmästare Dizzywig i Spärrhake.", d="Det är mitt jobb att se till att folk får det de behöver, och gnomerna där borta behöver få en delbeställning uppfylld.  Deras delar skickades till Spärrhake för en vecka sedan, men jag har inte kunnat göra resan.$B$BSå, är du redo för lite benarbete?  Gå till Spärrhake och ge den här delbeställningen till hamnmästare Dizzywig -- han är förmodligen nere vid kajerna.$B$BGör det här åt mig, så har jag fler jobb åt dig.$B$BJobb, min vän, med allvarlig vinstpotential ..."}, -- quests-batch-12-sv
[1112]={t="Delar till Kravel", o="Lämna Kravels delar till Kravel Koalbeard på Skimmerslätterna.", d="Här är Kravels paket, $n. Och när du levererar det, säg till honom... om han vill ha fler specialbeställningar får han betala sin skuld!"}, -- quests-batch-29-sv
[1113]={t="Ivrighetens hjärtan", o="Mästeralkemist Faranell i Undercity vill ha 20 ivrighetens hjärtan.", d="Varför jag behöver en sällsynt typ av guano, kan du fråga. Jo, för detta experiment vill jag se vilken effekt två diametralt motsatta kemiska substanser kan ha på varandra, särskilt när båda kombineras med ett ständigt toxiskt medel för att säkerställa de mest... fasansfulla resultaten.$b$bI de nordöstra topparna av Tirisfalgläntena ligger det Scharlakansklostret. Där samlas de galna lärjungarna av Scharlakanskorståget. Dräp dem och bringa mig deras ivriga hjärtan.$b$bVår blandning kommer att bli högst ondskefull!"}, -- quests-batch-09-sv
[1115]={t="Ryktesspridaren", o="Tala med Krazek i Bytesbukten.", d="Nu när vi har gjort en tjänst för gnomerna är det dags att göra goblinerna en tjänst! $B$BJag har hört att goblinracerpiloten Nazz Steamboil inte alltid använde det namnet. Jag undrar varför han ändrade det. Jag undrar om det är en hemlighet, och... jag undrar om han värderar den hemligheten.$B$BOm någon vet sanningen så är det Krazek i Bytesbukten, på den södra spetsen av Strypetörnsdalen. Tala med Krazek och fråga honom om vår goblinpilot.$B$BOm du kan få användbar information från honom, så kan vi kanske tjäna en slant på det."}, -- quests-batch-32-sv
[1116]={t="Drömstoft i träsket", o="Ta med 10 korn Drömstoft till Krazek i Bytesbukten.  Drömstoft samlas från drakungarna i Sorgeträsket.", d="Att få information om Nazz är en rejäl tjänst, $n.  Ja, en rejäl tjänst.  Men du har kommit hela vägen från Skimmerslätterna för att få den ... är du villig att resa lite till?$B$BMedan jag kontaktar mina källor, varför samlar du inte något åt mig, va?$B$BHm ... vad ska det bli?  Vad sägs om drömstoft, från drakungarna i Sorgeträsket.  Ja, jag skulle älska lite drömstoft till min snusdosa!$B$BSkaffa det åt mig, $n, så ger jag dig informationen du söker."}, -- quests-batch-21-sv
[1147]={t="Svärmen växer", o="Döda 5 silitidssökare, 5 silitidskupdroner och 5 silitidsinvaderare och återvänd till Moktar Krin i Tusen nålar.", d="Hmm. Det verkar som om Belgrom anser att those monster är ett hot. Han vill att de ska drivas tillbaka till vilka djup som helst som de kröp upp ifrån.$B$BJag antar att det inte räckte med att döda dvärgarna som skickades av Upptäckarförbundet – nu måste jag skicka ett halvdött krigsparti in i ännu en strid. Vi kommer inte kunna göra det själva; inte i det här tillståndet. Utgrävningsplatsen ligger söder om här. Det borde inte finnas fler dvärgar att ta hand om. Känner du dig kapabel att svinga ett blad eller en stav och göra din del för att hjälpa oss?"}, -- quests-batch-32-sv
[1149]={t="Trosprovet", o="Om du har tro, hoppa från plankorna med utsikt över Tusen nålar.", d="Så, du har sökt upp mig, eller kanske för ödet dig till mig? Det spelar ingen roll. Du är här nu, och därför börjar din resa på nytt.$B$BMånga fasetter utgör en varelse: anden, kroppen, sinnet. Några av dessa kan mätas efter en kulturs traditioner. Andra kan vi bara hoppas existerar inom oss. Om du går med på det ska jag pröva några av fasetterna inom dig.$B$BKlarar du det blir du starkare. Misslyckas du kommer du att inse Nethers vidd.$B$BDet första är ett Trosprov."}, -- quests-batch-15-sv
[1150]={t="Uthållighetstest", o="För Grenkas klo till Dorn Plainstalker i Tusen nålar.", d="Det gläder mig att se att ditt mod förblir orubbligt i ljuset av vad du redan har åstadkommit. Eftersom din tro är intakt är det dags att testa din kropp.$B$BFörst är ett uthållighetstest. Bege dig tillsammans med vänner till Roguefeather-lyan väster om Frivindsposten. Ta dig ner i djupen av deras tillhåll och förstör deras förråd. Då bör du ha provocerat deras vrede, och om du lyckas överleva tillräckligt länge kommer Grenka Bloodscreech själv efter dig – döda henne och bringa mig hennes klo för att slutföra ditt test."}, -- quests-batch-04-sv
[1151]={t="Styrkeprov", o="Ta med fragment av Rok'Alim till Dorn Plainstalker i Tusen nålar.", d="Under de gamla gudarnas tid bebod elementaler stora delar av denna värld. De tillbad de gamla gudarna, och gudarna höll elementalerna bundna till denna värld genom sin makt. När de gamla gudarna förvisades försvann elementalerna från vår värld och återvänder nu endast på befallning av kraftfulla magiker.$B$BDet finns dock undantag. Vissa elementaler var kraftfulla nog att stanna kvar här på egen hand. En sådan elemental är Rok'Alim.$B$BFör att testa din styrka, leta upp Rok'Alim i Tusen nålar och dräp honom."}, -- quests-batch-14-sv
[1152]={t="Kunskapsprov", o="Hitta Braug Dimspirit nära ingången till Klodjupsstigen i Stenklobergen.", d="Din tid med mig är nästan över. Jag är kunnig, men Kunskapsprovet är inte mitt att ge. Det finns läxor att lära och platser att besöka som andra gör anspråk på.$B$BOm du är beredd, sök då upp Braug Dimspirit--han är en shaman med stor visdom. Han kommer att pröva dig vidare, så lyssna på hans ord, $n.$B$BNär du är redo, hitta tunneln som förbinder Stenklobergen med Askdalen: Braug bor i närheten. Och var försiktig, $n, nattalverna kanske vill hindra ditt prov."}, -- quests-batch-23-sv
[1154]={t="Kunskapsprov", o="Hitta Aspekternas arv och lämna det till Braug Dimspirit nära ingången till Klodjupsstigen i Stenklobergen.", d="Du har klarat Dorns prov, och nu söker du klara din nästa prövning. Mycket bra. Men hittills har dina utmaningar varit barnsliga. Det är lätt att pröva din kropp--ditt sinne är en helt annan sak.$B$BJag förklarar det enkelt: hitta boken jag nämner, studera den och svara på min fråga om dess innehåll.$B$BVilken bok, undrar du säkert? Aspekternas arv. Den finns på botten av Dor'danil i södra Askdalen, skyddad av döda druider och deras dräpare."}, -- quests-batch-24-sv
[1159]={t="Kunskapsprov", o="Hitta Parqual Fintallas i Understaden.", d="Bra gjort, $n. Du har klarat den första delen av Kunskapsprovet, men det finns ännu en fråga att besvara. Men den frågan är inte min att ställa.$B$BSök upp Parqual Fintallas i Lordaeron-staden. Han var en stor historiker för människorna innan Pesten drabbade honom. Nu fortsätter han att söka upplysning, men av en annan natur.$B$BHan kommer att ha ytterligare ett krav på dig innan han frågar dig något, men du har klarat dig mästerligt hittills--jag är säker på att du övervinner hans hinder."}, -- quests-batch-26-sv
[1160]={t="Kunskapsprov", o="Hitta The Beginnings of the Undead Threat och återlämna den till Parqual Fintallas i Undercity.", d="Jag ska berätta vad du måste söka, och jag kommer till och med att ställa min fråga, men inte för att du vill bevisa dig själv. Kunskap är långt viktigare än styrka. Även om andra verkar gå om dig i förmåga, kommer din kunskap om världen att vara mer värdefull.$B$BGå till klostret i norra Tirisfalgläntena. I biblioteket där finns en bok kallad Beginnings of the Undead Threat. Den användes av de nu korrupta paladinerna där för att träna dem att bekämpa mitt folk.$B$Bbringa den till mig"}, -- quests-batch-22-sv
[1175]={t="Ett gupp på vägen", o="Döda 10 Saltstone-basilisker, 10 Saltstone-kristallhudar och 6 Saltstone-stirrare åt banmästare Zherin på Skimmerslätterna.", d="Efter den stora kraschen mellan goblinernas Red Thunder-racer och en basilisk anställde Kronkrider mig för att sköta banan. Jag vet inte vad alla djur där ute på slätterna lever på för att växa sig så stora, men vi måste vara försiktiga och gallra ut dem så att de inte vandrar ut på banan när ett lopp pågår.$b$bVet du vad. Om du vill gå ut och tjäna lite pengar, gå ut och ta bort basiliskerna från området."}, -- quests-batch-05-sv
[1177]={t="Hungrig!", o="Mudcrush Durtfeet i norra Dammträsket vill ha 12 Myrfen-huvuden.", d="Mud stor oger.$b$bMig hungrig.$b$bGå slå fiskig. Ta mat till Mud.$b$bDu ger Mud mat eller Mud äter dig."}, -- quests-batch-13-sv
[1180]={t="Goblinsponsring", o="Tala med hamnmästare Lozgil i Bytesbukten.", d="Tillbaka till det du kom hit för. Jag vet att jag lovade Pozzik att jag skulle leverera en ny bränsleregulator åt honom, men jag har ännu inte fått den. Revilgaz borta i Bytesbukten sa att han skulle skicka över den, men det kan vara så att den på något sätt hamnat mellan stolarna.$b$bOm det stämmer finns det inte mycket vi kan göra. Vi kan åtminstone ta reda på om den skickades iväg från Bytesbukten.$b$bTa kontakt med hamnmästare Lozgil där borta, han bör kunna kontrollera lastregistren."}, -- quests-batch-23-sv
[1182]={t="Goblin-sponsring", o="Lämna ritningarna för bränsleregulatorn till baron Revilgaz i Bytesbukten.", d="Hör här, Äventyrsbolagets shreddrar ute i Lake Nazferiti (i norra Strypetörnsdalen) har utrustats med en ny modell av bränsleregulator. Jag tänkte att Pozzik skulle kunna dra nytta av den om han kunde få tag på detaljerna. Tyvärr verkar Cozzle, förmannen där ute, vara lite smartare än jag gett honom kredit för.$b$bDu verkar dock ha större chans att hitta ritningarna. Jag vet att han förvarar dem i sitt hus, men de är nästan helt säkert inlåsta."}, -- quests-batch-31-sv
[1187]={t="Razzerics finjustering", o="Hämta Seaforium-boostern till Razzeric på Skimmerslätterna.", d="Pozzik är en fantastisk mekaniker, det vet jag, men han är rädd för att bara maxa eldkraften och hänga med på resan. Inte jag däremot.$b$bNär Pozzik är klar med en racer tar jag lite tid på mig för att göra mina egna modifieringar – du vet, lossa på kontrollerna, ta bort delar av ramen och tillsätta mer kraft!$b$bJag beställde en seaforium-booster från Shreev på Gizmorium i Gadgetzan, men tydligen kraschade zeppelinen den skickades med i Dammträsket! Jag måste ha den, $n!"}, -- quests-batch-29-sv
[1201]={t="Theramore-spioner", o="Döda 9 Theramore-infiltratörer och återvänd sedan till Nazeer Bloodpike i byn Brackenwall.", d="Horden och Alliansen håller en orolig vapenvila.  Utkantsstrider och hemliga aktioner utförs av den ena sidan mot den andra, och det är vår plikt att se till att Horden har övertaget!$B$BNu finns chansen att göra just det.$B$BAlliansens infiltratörer har intagit positioner öster om byn Brackenwall.  De spionerar på byn och rapporterar våra rörelser till Theramore, vilket vi inte kan tillåta.$B$BJaga ned infiltratörerna och döda dem.  Skicka ett tydligt budskap till deras överordnade att vi inte tolererar deras spioners närvaro!"}, -- quests-batch-07-sv
[1202]={t="Theramores kajer", o="Ta med Kaptenens dokument till Nazeer Bloodpike i byn Brackenwall.", d="$n, två av våra spioner skickades för att stjäla dokument från ett skepp vid Theramores kajer.  De fick tag i papperna men blev upptäckta och tvingades kasta dokumenten i havet.$B$BEn spion flydde senare, men kunde inte återfå bytet.  Han rapporterade sitt misslyckande till mig, och nu ger jag uppgiften åt dig.$B$BDokumenten ligger i en kista, i vattnet någonstans under Theramores kajer.  Hitta dokumenten, $n, och ta dem till mig."}, -- quests-batch-06-sv
[1203]={t="Jarl behöver en klinga", o="Ta med ett bredsvärd av månstål till Jarl i Dammträsket.", d="Jag har saker att skära.  Jag kan inte säga vad jag ska skära, men ... jag behöver en klinga åt mig.  En viss klinga ...$B$BNågra kallar den ett bredsvärd av månstål.  Jag kallar den ett svingblad.$B$BHjälper du mig?  Kanske hittar du det i stan, kanske pratar du med en smed så gör han ett speciellt.$B$BMen somna inte på det här.  Det jag ska skära håller inte för evigt ..."}, -- quests-batch-13-sv
[1205]={t="Deadmire", o="För Deadmires tand till Melor i Åskbrunn.", d="Deadmire är en uråldrig krokodil i Dammvattensmyren. Och det är dags för honom att dö.$B$BOld gamla ben gnisslar när han drar sin enorma kropp genom träsket, och även om han fortfarande rör sig med ungdomens styrka och snabbhet, plågar hans åldrande kropp den stora anden inom honom, en ande vars låga inte kommer att vackla.$B$BMen nu lever han i ständig, vansinnig smärta. Du måste avsluta livet för denna ädla varelse, $n. Du måste leda Deadmire till frid."}, -- quests-batch-20-sv
[1206]={t="Jarl behöver ögon", o="Ta med 40 ospräckta mörkdimmeögon till \"Swamp Eye\" Jarl vid Träskljusherrgården.", d="Ögonsaft är bra saft att dricka.  Synd att de flesta kryp bara har två ögon.$B$BMen spindlar har massor av ögon.  Massor och åter massor.  Och mörkdimmeögonsaft är smaskig.  Len och salt!  Ospräckta spindelögon ... jag känner smaken redan.$B$BMörkdimmespindlarna finns väster om här, i Mörkdimmegrottan.  Man undrar om spindlarna är uppkallade efter grottan ... eller är det tvärtom?"}, -- quests-batch-11-sv
[1218]={t="Lugnande kryddor", o="Ta med 3 lugnande kryddor till \"Swamp Eye\" Jarl i Dammträsket.", d="Jag gillar att laga mat.  God träskmat.  Stekta gröna grodlår och sånt.$B$BOch för matlagning behöver jag krydda.  Lugnande krydda.  Sedan gör jag en gryta och kokar ihop den och slevar i mig den och ger dig lite också.$B$BTycker du om gryta?"}, -- quests-batch-01-sv
[1238]={t="Den förlorade rapporten", o="Ta med Spionens rapport till Nazeer Bloodpike i byn Brackenwall.", d="När man siktar igenom den lösa jorden hittas en orchs avhuggna hand.  Och i handen hålls ett rör snidat av ben.  Och i röret finns ett smutsfläckat pergament.$B$BPergamentet är en rapport som skrivits av en orch som tillbringade veckor med att spionera på staden Theramore.$B$BEfter att ha skummat pergamentet är det klart att det måste föras till orchernas spionmästare i byn Brackenwall."}, -- quests-batch-06-sv
[1239]={t="Det avhuggna huvudet", o="Ta med Trotsig orchs huvud till Nazeer Bloodpike i byn Brackenwall.", d="Ihärdigt grävande avslöjar huvudet av en manlig orch, taggigt avhugget vid halsen.  Hans läppar är frusna i ett morrande, och de mörka ögonen stirrar trotsigt."}, -- quests-batch-07-sv
[1240]={t="Trollens häxdoktor", o="Ta Trotsig orchs huvud till Kin'weelay vid Grom'gol-baslägret i Strypetörnsdalen.", d="Vi måste få veta vad som hände kring Margs död!  Och det enda sättet att få veta det, $n, är genom trollens häxmagi.$B$BTa Margs huvud till Kin'weelay i Strypetörnsdalen, vid Grom'gol-baslägret.$B$BKin'weelay är den mäktigaste häxdoktorn bland Mörkspjutstrollen.  Om någon kan tala med Marg Nighteyes ande är det han."}, -- quests-batch-03-sv
[1251]={t="Den svarta skölden", o="Ta med Svärtad järnsköld till Krog i byn Brackenwall.", d="En järnsköld, svärtad av elden som rasade genom värdshuset, sitter fast på den förfallna skorstenen, en av de få kvarvarande delarna av byggnaden som en gång utgjorde värdshuset Shady Rest.$b$bSkölden kan lossas från skorstenens tegel."}, -- quests-batch-05-sv
[1268]={t="Misstänkta hovspår", o="Rapportera om de misstänkta spåren vid värdshuset Shady Rest till Krog i byn Brackenwall.", d="Rader av hovspår leder bort från det fortfarande rykande skelettet av värdshuset Shady Rest. Det finns minst några synliga avtryck, med fler rader av spår som knappt syns i träskets mjuka lera."}, -- quests-batch-03-sv
[1269]={t="Löjtnant Paval Reethe", o="Ta med Reethes bricka till Krog i byn Brackenwall.", d="En glimt av ljus på marken fångar din blick under spillrorna. När du borstar bort skräp och aska som fastnat på föremålet avslöjas en insignia av ett guldankare på vitt, emaljerat på ytan: Theramores tecken.$b$bUnder ankaret är namnet \"Löjtnant Paval Reethe\" präglat."}, -- quests-batch-12-sv
[1270]={t="Stinkys flykt", o="Eskortera \"Stinky\" Ignatz och tala sedan med Mebok Mizzyrix i Spärrhake.", d="Äntligen, något som inte vill äta upp mig!!$B$BJag behöver hjälp med att hantera krypen häromkring, och du passar in, $gbuddy:lady;.$B$BEn goblin från Spärrhake vid namn Mebok Mizzyrix behöver några bogbean-blad till en dryck, eller något ... Jag bryr mig ärligt talat inte om varför -- hans pengar var bra och jag känner det här träsket, så här är jag.$B$BSynd att jag blev omringad innan jag hittade bogbeanen!  Kan du hjälpa mig härifrån och hålla utkik bakom ryggen på mig medan jag letar efter Meboks växt?Hjälp Stinky hitta bogbean-blad"}, -- quests-batch-06-sv
[1273]={t="Förhör av Reethe", o="Gå med Ogron för att tala med Reethe, och återvänd sedan till Krog i byn Brackenwall.", d="Det tog lång tid, men jag hittade Reethe. Han gömmer sig bra för en människa.$b$bOgron orolig att han kan vara galen efter så lång tid i träsket. Du följer med mig så vi går och får svar av honom.Förhör Reethe med Ogron"}, -- quests-batch-04-sv
[1321]={t="Den svarta skölden", o="Visa Svärtad järnsköld för Do'gol i byn Brackenwall.", d="Hmm ... jag ser inget ovanligt med den här skölden. Vi borde låta Do'gol, smeden, ta en titt på den, och se om han kan berätta mer om den, men jag skulle inte hysa något hopp ..."}, -- quests-batch-13-sv
[1322]={t="Den svarta skölden", o="Skaffa 6 syrahaltiga giftsäckar åt Do'gol i byn Brackenwall.", d="Hmmm, det finns skrift här på själva kanten av skölden, men den är svår att läsa på grund av allt brända.$b$bJag behöver syra för att göra den tydlig. Gift från Darkfang-spindlarna i träsket skulle duga bra. Skaffa några av deras säckar åt mig så kan jag rengöra den här."}, -- quests-batch-08-sv
[1361]={t="Regthar Deathgate", o="Tala med Regthar Deathgate.", d="En krigare av Horden, Regthar Deathgate, rekryterar agenter för ett uppdrag i landet Ödelandet. Tala med honom om du vill anmäla dig som frivillig. Han är stationerad i Kargmarkerna, i en serie bunkrar väster om Korsvägen.$B$BOch vässa dina vapen. Ödelandet är en plats sargad av krig."}, -- quests-batch-13-sv
[1362]={t="Kolkar i Ödelandet", o="Tala med Felgur Twocuts vid Spökvandrarposten i Ödelandet.", d="Kolkar-kentaurena lever i Ödelandet, och deras styrkor har spridit sig in i Kargmarkerna. Detta är ett känt faktum och vi har Horden-agenter som hanterar dem här.$B$BMen så länge kentaurena är starka i Ödelandet kommer de alltid att utgöra ett hot. Det är dags att vi gör oss av med det hotet.$B$BTala med Felgur Twocuts vid Spökvandrarposten i Ödelandet. Han skickades dit för att samla underrättelser om kentaurena. Han vet hur man bäst hanterar Kolkar i Ödelandet."}, -- quests-batch-29-sv
[1365]={t="Khan Dez'hepah", o="Ta med Khan Dez'hepahs huvud till Felgur Twocuts i Ödelandet.", d="Kolkar är inte de enda kentaurerna i Ödelandet.  Många klaner vandrar över de här torra slätterna, slåss och dör mot varandra.  Och det är bra att de slåss sinsemellan, för de är starka och brutala.  Om kentaurerna enades mot oss skulle de vara en hård fiende.$B$BVi måste ta itu med dem innan de enas.$B$BDin första uppgift är att splittra Kolkar-klanen.  Gör det genom att döda dess ledare, Khan Dez'hepah.$B$BKolkarbyn ligger nordost om här.  Gå, och må lyckan följa dig."}, -- quests-batch-06-sv
[1366]={t="Kentaurpremie", o="Ta med 15 kentauröron till Felgur Twocuts i Ödelandet.", d="Nu när du har skrämt kentaurklanerna är det dags att tappa blod på dem.  När du reser genom Ödelandet, jaga kentaurer.  Jag bryr mig inte om vilken klan du jagar.  Samla bara öron.  En hög med öron.$B$BGenom att försvaga deras antal försvagar du deras beslutsamhet, och kväver alla tankar på expansion.$B$BLycka till på jakten, $n."}, -- quests-batch-06-sv
[1367]={t="Magramalliansen", o="Nå anseendet Vänlig hos Magram och tala sedan med Warug.", d="För att besegra kentaurerna måste vi använda deras hat mot dem.  Vi ska alliera oss med en av klanerna och genom dem lära oss hur vi besegrar alla klanerna.$B$BOm du väljer att alliera dig med Magram, döda då deras fiender, Gelkis.  Det ger dig respekt bland Magram.  När du har tjänat tillräckligt, möt Magrams talesman Warug, i utkanten av Magrambyn, i sydöstra Ödelandet."}, -- quests-batch-06-sv
[1368]={t="Gelkisalliansen", o="Nå anseendet Vänlig hos Gelkis och tala sedan med Uthek den vise.", d="För att besegra kentaurerna måste vi använda deras hat mot dem.  Vi ska alliera oss med en av klanerna och genom dem lära oss hur vi besegrar alla klanerna.$B$BOm du väljer att alliera dig med Gelkis, döda då deras mest hatade rival, Magram.  När du har vunnit Gelkis respekt, möt Gelkis shaman Uthek den vise, i utkanten av Gelkisbyn, i sydvästra Ödelandet."}, -- quests-batch-14-sv
[1370]={t="Stjäla förnödenheter", o="Ta med 6 påsar Slarvigt torkat kött till Uthek den vise i Gelkisbyn.", d="När vi inte är i krig jagar vi kött.  Kött ger oss styrka, och fulla magar kämpar hårdare än tomma.$B$BSamma gäller Magram.  De lagrar extra kött så att de kan strida längre mellan jakterna.  Om du plundrar deras by i öster och tar deras köttförråd kommer deras styrka att svikta."}, -- quests-batch-30-sv
[1373]={t="Ongeku", o="Behåll ditt rykte hos Gelkis och lämna ett draenethyst-fragment till Uthek the Wise i Gelkis by i Ödelandet.", d="Du har mer att bevisa, och din nästa uppgift kommer att ta dig långt bort, så för tillfället kommer Gelkis att bekämpa Magram utan dig.$B$BJorden viskar många hemligheter till dem som lyssnar. En hemlighet jag hör handlar om en röd kristall. Den kallas draenethyst och är ny för vår jord. Den kommer från en plats där berg flyger och där demoner härskar.$B$Bbring mig ett fragment av draenethyst, så kommer det att göra min magi stark! Fragmentet finns på en plats som kallas Sorgeträsket, i händerna på den förlorade Ongeku."}, -- quests-batch-24-sv
[1389]={t="Draenetystkristaller", o="Ta med 6 draenetystkristaller till Magtoor vid The Harborage i Sorgeträsket.", d="De förlorade som bor i Fallow Sanctuary ser ut som vi, men de är monster ... drivna till vansinne av strapatserna på vår resa till Azeroth.  En gång våra bröder, bor de nu i Fallow Sanctuary i öster och fångar eller dödar alla som vandrar nära.$B$BOch de har stulit något heligt för oss--draenetystkristaller.$B$BVi saknar kraften att gå in i Fallow Sanctuary och återta vår stulna draenetyst bland deras hyddor och lägereldar, men utan de kristallerna ... kan även vi gå vilse."}, -- quests-batch-27-sv
[1394]={t="Sista passagen", o="Tala med Dorn Plainstalker i Tusen nålar.", d="Du har gjort väl ifrån dig, $n. Du har klarat mitt prov, och proven före mitt. Återvänd till Dorn i Tusen nålar. Han kommer att känna förändringen inom dig, och se att ditt sinne, din kropp och din ande är starka nog för att du ska belönas för din möda.$B$BHåll dig trogen balansen du har visat genom alla de här prövningarna, $n. Dorn kommer att pröva dig igen i framtiden om du gör det."}, -- quests-batch-10-sv
[1418]={t="Neeka Bloodscar", o="Tala med Neeka Bloodscar.", d="Ofärdsmarken är hård och ligger nära Alliansens land Loch Modan, så kommunikationen mellan Stonard och utposten Kargath i Ofärdsmarken bryts ofta.$B$BBevisa dig, $n.  Res till Ofärdsmarken och tala med Neeka Bloodscar, huvudspanare vid utposten Kargath.  Tala med henne och skicka sedan hennes rapport tillbaka till mig."}, -- quests-batch-22-sv
[1419]={t="Koyottjuvar", o="Ta med 30 koyotkäkben till Neeka Bloodscar i Kargath.", d="Har du tillbringat många dagar i Ofärdsmarken, $c?  Har du känt dess hetta? Har du mött bestarna som vandrar över dess dammiga slätter?  Det är dags att du gör det.$B$BKlippkoyoter är en seg ras.  Seg, och djärv nog att smyga in i Kargath och stjäla från våra matförråd.  Hjälp till att befria utposten från de här tjuvarna!$B$BJaga klippkoyoter, $n.  Jaga dem och ta med mig deras käkben.  Ta med tillräckligt många, så tror jag kanske på dig när du säger att du känner Ofärdsmarken."}, -- quests-batch-25-sv
[1420]={t="Rapportera till Helgrum", o="Ta med Neekas rapport till Helgrum den snabbe i Stonard.", d="Jag skrev en ny rapport åt Helgrum i Stonard.  Ta den till honom.$B$BOch om du anser dig vara ett springbud, förirra dig då inte.  Eller falla för en fiende."}, -- quests-batch-26-sv
[1429]={t="Den förvisade Atal'ai", o="Lämna knippet av Atal'ai-artefakter till den förvisade Atal'ai i Bakländerna.", d="Medan du trotsade farorna i Tårarnas pöl återvände en av mina spejare med en rulle skriven i blod på torkat kött. Det verkar vara en rättslig dom mot en präst från Atal'ai-stammen.$b$bDenna präst dömdes till ett öde värre än döden bland Atal'ai.$b$bHan förvisades för att leva långt i norr i Bakländerna, tillsammans med Vissenbark-trollen.$b$bJag kommer att knyta ihop dessa artefakter. Du ska söka upp den förvisade och upptäcka deras sanna användning. Återvänd till mig när din resa är fullbordad."}, -- quests-batch-32-sv
[1480]={t="Fördärvaren", o="Ta med Flådd demonhud till Maurin Bonesplitter i Ödelandet.", d="Den sönderrivna huden luktar ruttet och är märkligt följsam för något som ser torrt och sprött ut.$B$BNär du rullar upp den kan du tydligt se de röda tecknen av något slags språk på ena sidan. Längst ner på huden finns en mycket tydlig symbol som du gissar är en slags signatur.$B$BKanske är det något Maurin kunde berätta mer om?"}, -- quests-batch-11-sv
[1481]={t="Fördärvaren", o="Lämna en Shadowstalker-skalps till Maurin Bonesplitter i Ödelandet.", d="Jag tror att jag kan finna denna demonherre om jag har rätt reagenser.$B$BOm han verkligen är så kraftfull som jag misstänker, kommer jag att behöva föremål insamlade från dödliga varelser. Men du agerar i krigsledarens namn, så jag är säker på att du kommer att acceptera min uppgift.$B$BFörst måste jag bryta alla skydd han har mot spådom. För detta behöver jag skalpen från en satyr – men inte vilken satyr som helst. Skalpen måste komma från en Hatefury-skuggpirsare.$B$BSök efter dem bland de forna ruinerna i nordöstra Ödelandet."}, -- quests-batch-32-sv
[1482]={t="Den fördärvade", o="För med en orakelkristall till Maurin Bonesplitter i Ödelandet.", d="En orakelkristall skulle passa utmärkt. De tillverkas av naga för deras orakel att använda.$B$BNordväst härifrån, längs kusten, finns ett enormt korallrev som naga har gjort till sitt hem när de är så nära stranden. Du kan hitta deras orakel där. Slitherblade är dödliga och kommer inte att reagera vänligt på dina intrång, så var försiktig och skynda dig.$B$B", p="När du återvänder ska vi se till att hitta denna demonherre Azrethoc."}, -- quests-batch-31-sv
[1948]={t="Kraftföremål", o="För med dig 1 jade och den bultladdade törnen till Tabetha i Dammträsket.", d="Att tillverka en magikers trollstav är inte lätt. Sällsynta substanser krävs, och ett kärl måste skapas som kan lagra stora mängder magisk energi. Du måste samla dessa ting och föra dem till mig.$B$BJag har skrivit ner på detta pergament vad du behöver, samt instruktioner om hur du får tag på det. För med dig exakt det som står på listan och följ mina skrivna anvisningar till punkt och pricka, för om du inte gör det kan det gå... illa när vi tillverkar din stav."}, -- quests-batch-32-sv
[1949]={t="Dolda hemligheter", o="Tala med Magus Tirth på Skimmerslätterna.", d="För att tillverka din trollstav finns det nyckelavsnitt i en viss bok som jag måste läsa. Boken heter Rituals of Power och är skriven av Magus Tirth.$B$BJag har inget exemplar av hans bok, och inget av världens stora bibliotek äger den. Du måste därför tala med Tirth och få den av honom.$B$BLycka till. Tirth brukade vara en stor magiker och lärd, men nu tillbringar han sin tid vid gnom- och goblinloppen på Skimmerslätterna med att dricka och spela."}, -- quests-batch-32-sv
[1951]={t="Maktens ritualer", o="Ta med boken Maktens ritualer till Tabetha i Dammträsket.", d="Hm ... nu när jag tänker efter har jag inte min bok!  Du förstår, jag hade lite spelskulder och för att betala av dem sålde jag sista exemplaret av Maktens ritualer till en medlem av prästerskapet ....$B$BEn medlem av Scharlakansröda brödraskapet.  Han måste ha tagit den till deras bibliotek i Scharlakansklostret i Tirisfalgläntorna!$B$BOm du vill ha den boken måste du gå till klostret för att hitta den.  Och ledsen för allt besvär.  Jag är inte mig själv nuförtiden ..."}, -- quests-batch-16-sv
[1954]={t="Den infernala klotet", o="Lämna ett infernalt klot till Tabetha i Dammträsket.", d="Det första steget är att skaffa ett klot med kraft. Häxmästarna i Brinnande klingan har fina klot av hög kvalitet... det är synd att de har bundit demoner i dem! Men vi kan fixa det, ja det kan vi.$B$BGå till Ödelandet och ryck ett infernalt klot från en frammanare av Brinnande klingan. Du hittar frammanare vid Mannoroc-kulten.$B$BNär du har klotet, återvänd till mig."}, -- quests-batch-32-sv
[2202]={t="Uldaman-reagens", o="Lämna 12 magentafungisvampar till Jarkal Mossmeld i Kargath.", d="Jag har hört talas om en nyupptäckt växt som kallas magentafungisvampar. De växer i klungor djupt inne i utgrävningsplatsen i Uldaman; de kan finnas på andra ställen, men för tillfället är det den enda platsen jag vet att de finns på. Jag vill studera deras potentiella användning inom alkemi, och det är där du kommer in.$B$BHitta klungorna med magentahattar och ta med mig ett dussin hattar. Var varnad, klungorna kan spruta ut giftsporer om de skakas.$B$B", c="Gör detta för mig, så blandar jag ihop en sats av mina starkare läkande drycker till dig!"}, -- quests-batch-32-sv
[2280]={t="Platinaskivorna", o="Ta den miniatyra versionen av Norgannons skivor till en av de vise i Dunderklippan.", d="Att röra vid Norgannons skivor får åter din hand att pirra.  Den här gången hörs dock ett märkligt malande ljud inifrån skivorna.$B$BDin ryggsäck blir plötsligt tyngre än den var förut.  Inuti upptäcker du en miniatyrversion av skivorna!$B$BUtan tvekan skulle ett föremål av det här slaget vara ovärderligt för någon som är intresserad av Azeroths uråldriga historia.  De vise i Dunderklippan är sådana historiker, kända över hela Horden; kanske kan de ha god nytta av det."}, -- quests-batch-28-sv
[2283]={t="Halsbandsåterhämtning", o="Leta efter ett värdefullt halsband i Uldamans utgrävningsplats och ta tillbaka det till Dran Droffers i Orgrimmar.  Halsbandet kan vara skadat.", d="Vi har arbete åt dig, om du har mage för det!$B$BDjupt inne i Ofärdsmarken finns utgrävningsplatsen Uldaman. Vi har hört en historia om någon idiotisk paladin som dog där nyligen. Varför vi ens bryr oss är att han hade ett mycket värdefullt halsband på sig. Det ska ha tre stora ädelstenar: en rubin, en safir och en topas.$B$BSaken är den: vi vill ha det, och vi betalar TOPPSILVER för att få det. Det kan vara skadat, men det varken här eller där; vi lagar vilka repor som än finns på det."}, -- quests-batch-21-sv
[2342]={t="Återvunna skatter", o="Hämta Patrick Garretts familjeskatt från deras familjekista i den södra samlingshallen i Uldaman och bringa den till honom i Understaden.", d="Att sopa fladdermuskvalen med den här kvasten anstår inte en Garrett! Jag har tjänat några mynt på det här förbannade jobbet, och jag är villig att spendera dem på dig för att förbättra min situation.$B$BGarrettfamiljens föredragna vapen är inlåst i vår kista i den södra samlingshallen i Uldaman från den tid då vi Garretts slet där som grävare. Utan det kommer jag att sitta fast här för evigt - bokstavligen - och sopa upp efter dessa infernala fladdermöss.$B$BÅtervinn min familjs skatt och bringa den till mig! Hjälp mig att återställa mitt födelselod!"}, -- quests-batch-21-sv
[2418]={t="Kraftstenar", o="Lämna 8 kraftstenar från Dentrium och 8 kraftstenar från An'Alleum till Rigglefuzz i Ofärdsmarken.", d="För ett tag sedan hade jag en incident med mörkjärnsdvärgarna. De tog med mig till Angorfästningen för att studera två typer av märkliga stenar från Uldaman. Jag upptäckte att stenarna var hållbara och stabila kraftkällor om de behandlades på rätt sätt. Det är fantastiskt vad man kan hitta på den där gamla utgrävningsplatsen!$B$BAv och vidare, efter att jag berättat hemligheten om stenarna för dem kastade de ut mig från Angorfästningen och började gräva efter fler i Uldaman.$B$BJag vill ha those stenar själv! Hämta båda typerna så ska jag betala dig rikligt!"}, -- quests-batch-27-sv
[2752]={t="Om järnskulder", o="Lämna över fyra bronsstridsyxor och fyra bronskrigshammare till Orokk Omosh i Orgrimmar.", d="Orokk ser ivern i dina ögon, $n. Som en svamp suger du åt dig Omoshs visdom.$B$BTre lektioner ska jag lära dig!$B$BÅtervänd till städets hetta, känn smedjans glöd och skapa fyra bronsstridsyxor och fyra bronskrigshammare åt Orokk. Först då kommer du att lära dig om järnskuldern."}, -- quests-batch-32-sv
[2841]={t="Maskinkrig", o="Hämta Ritningar till borrigg och Thermapluggs kassaskåpskombination från Gnomeregan och ta dem till Nogg i Orgrimmar.\\r\\n", d="Gnomteknik - för två år sedan var dess vanligaste användning som slutklämmen i ett skämt. Tiderna har verkligen förändrats. Nu har de byggt en ny maskin som är bättre än alla våra skredarmodeller tillsammans. Jag behöver ritningarna, $n!$B$BTyvärr är planerna inlåsta i ett kassaskåp nära Mekgenjör Thermaplugg. Och till råga på allt känns kombinationen till kassaskåpet bara av Mekgenjör Thermaplugg.$B$BGör vad du än måste för att få den kombinationen, $n. Bryt sedan upp skåpet och ta tillbaka ritningarna!"}, -- quests-batch-29-sv
[2842]={t="Överingenjör Scooty", o="Tala med Scooty i Bytesbukten.", d="Så snart vi fick ord från Kernobee om den nya gnomiska riggen, började Scooty och jag arbeta på Transpolyporter 6000: det snabbaste och mest pålitliga sättet att ta sig till Gnomeregan.$B$BDen är äntligen redo för passagerare, $n. Om du vill prova den, bege dig till Bytesbukten och tala med Scooty vid vindryttarnas utpost. För att komma till Bytesbukten, ta båten från Spärrhake.$B$BSjälvklart kan du alltid försöka ta dig till Gnomeregan genom de dvärginfesterade bergen i Dun Morogh!"}, -- quests-batch-05-sv
[2843]={t="Gnomer-borta!", o="Vänta medan Scooty kalibrerar Goblintranspondatorn.", d="Så länge du har transpondatorn i din ägo behöver du bara kliva på plattan så teleporteras du till Gnomeregan.$B$BDu kan uppleva några ovanliga biverkningar, men inga av dem bör vara permanenta ... längre.$B$BJag glömde nästan den viktigaste delen - att komma tillbaka. När du är redo att komma tillbaka, kliv bara på transpolyporterplattan i Gnomeregan!$B$BNu ska transpondatorn kalibreras efter din storlek och vikt.\\r\\nGoblintranspondator"}, -- quests-batch-28-sv
[2861]={t="Tabethas uppdrag", o="Tala med Tabetha i Dammträsket.", d="Ryktet säger att Tabetha, en magikerkollega som bor djupt inne i Dammträsket, har ett gammalt räkenskap att göra upp med en viss sandtroll i Zul'Farrak. Om du talar med Tabetha kan hon berätta mer.$B$BOch ta med dig några vänner, $n. Om Tabetha ber dig bege dig till Zul'Farrak kommer du inte vilja gå dit ensam.$B$BDu hittar Tabethas stuga väster om Theramore, precis norr om Stonemaul Ruin."}, -- quests-batch-32-sv
[2932]={t="Dystert budskap", o="Samla Vissenbarkskallar och placera dem på Nimboyas pik. Placera Nimboyas tyngda pik i en av Vissenbarksbyn i Bakländerna, och återvänd sedan till Nimboya i Strypetörnsdalen.", d="Vissenbarkstrollen var en gång allierade med Horden, men de förrådde Thrall... och det måste straffas!$B$BHär, ta min pik och bege dig till Bakländerna, långt i norr. Du finner det nordost om Tarrens kvarn, en by som hålls av våra allierade, De bortglömda.$B$BNär du når Bakländerna, jaga vissenbarkstroll. Samla deras skallar och driv ner min pik i marken i en av deras mindre byar, Hiri'watha eller Zun'watha.$B$BVisa dem att deras avskyvärda handlingar får konsekvenser!", p="Placera det dystra budskapet."}, -- quests-batch-20-sv
[2945]={t="Smutsig ring", o="Hitta ett sätt att få bort smutsen från den smutsiga ringen.", d="Du har hittat vad som ser ut att vara en ring från liket av en av mörkjärnsdvärgarna. Det är dock svårt att avgöra vilken sorts ring det är; smuts och härdade rester täcker föremålet helt, vilket gör det omöjligt att bära. Du tror att du kan ana en svag glans av ädelmetall och kanske till och med skimret av en ädelsten under resterna.$B$BOm du ska kunna använda den här ringen måste du hitta något som kan få bort de härdade resterna från den."}, -- quests-batch-32-sv
[2949]={t="Ringens återkomst", o="Du kan antingen behålla ringen, eller så kan du försöka hitta personen som är ansvarig för avtrycket och gravyrerna på insidan av ringen.", d="När du öppnar asken som skapades av Sparklematic 5200 avslöjas en glänsande ring! När du tar på dig ringen känner du hur magisk kraft strömmar genom din kropp.$B$BPå insidan av ringen finns ett litet men ändå tydligt avtryck av Orgrimmars sigill. Bredvid det finns graverade bokstäver, men endast de tre första är läsbara även efter rengöring: \"NOG...\"$B$BDetta kan antingen vara den tidigare ägarens initialer, eller kanske initialerna för ringens smed. Behåll ringen... eller leta efter \"NOG\" - svåra beslut..."}, -- quests-batch-32-sv
[3341]={t="Bringa slutet", o="Andrew Brownell vill att du dödar Amnennar den kalla och återlämnar hans skalle.", d="I Barrens ligger ett fasansfullt kaos av sammanflätade rankor kallat Razorfen Downs. Medan våra första observationer av denna plats avslöjade lite hot, är våra senaste fynd mycket mer allvarliga...$B$BQuilboarna i Razorfen Downs har allierat sig med pestan. En lich vid namn Amnennar den kalla styr dem nu, och använder kraften i sitt massiva medvetande för att kontrollera varje rörelse de gör.$B$BAmnennar har en direkt telepatisk länk till Ner'zhul; vi måste bryta detta band, $n. Ett slut måste komma för den kalla."}, -- quests-batch-20-sv
[3366]={t="Den glödande skärvan", o="Res till Spärrhake för att ta reda på vad Mardrömsskärvan betyder.", d="Skärvan är briljant grön, och även om den är solid virvlar något som ser ut som rök strax under ytan. Du kan inte låta bli att stirra in i kristallens djup; samtidigt vet du att det är något mycket oroande med den.$B$BKanske borde du se om någon i Spärrhake kan berätta mer om den här märkliga skärvan.Tala med någon om Mardrömsskärvan"}, -- quests-batch-02-sv
[3911]={t="Det sista elementet", o="Res till Svartklippans djup och återta 10 Elementens essens.", d=" Din första instinkt är att söka igenom golemerna och golemmakarna. Du minns att Vivian Lagrave också mumlade något om elementarer.\\r\\nDet finns arbete för dem som ger sig ut i djupet, $n.$B$BMörkjärnsdvärgarna har bemästrat skapandet av extremt kraftfulla golemer.$B$BFörsta rapporter från våra spioner tyder på att dvärgarna använder en unik kraftkälla för att ge sina skapelser ojämförlig dödlig kraft.$B$BFöreställ dig vad vi kunde göra med våra vederstyggligheter om vi kunde få tag på den här elementens essens! Vänd upp och ned på den staden om du måste, men kom inte tillbaka förrän du har hittat essensen! Betalningen blir värd risken."}, -- quests-batch-13-sv
[4737]={t="På jakt efter Menara Voidrender", o="Tala med Menara Voidrender i Kargmarkerna.", d="Hmph, du strävar fortfarande efter att bli mäktigare. Jag säger att det bara är en tidsfråga innan korruptionen och beroendet tar grepp om dig och du blir en slav under det du söker makt över.$B$BPfah! En dåre är du! Tiden kommer att bevisa att jag har rätt--inget annat ... bara tid.$B$BMen det verkar som att inte alla håller med Zevrost. Det verkar som att Menara skulle skapa verktyg för dig att bli mäktigare och att tygla din styrka. Om du är intresserad, gå då till Spärrhake i Kargmarkerna. Hon är där och blickar ut över staden."}, -- quests-batch-29-sv
[5342]={t="Den siste Barov", o="Res till Kylvindslägret - Alliansens territorium - och mörda Weldon Barov. Ta hans huvud och återvänd till Alexi Barov.$B$BVar varnad, Weldon är förmodligen väl skyddad av Alliansens avskum.", d="Naturligtvis, med min bror fortfarande i livet, kan det uppstå tvist om vem som är den främsta förmånstagaren till familjens förmögenhet. Det får inte ske.$B$BEn simpel rännstensunge som du är väl inte för god för lite kallblodigt mord, hoppas jag.$B$BDet är en enkel uppgift och en som jag förväntar mig att du slutför; det vill säga, om du vill göra anspråk på din belöning.$B$BWeldon sitter under Alliansens beskydd i Kylvindslägret, österut. Döda honom, lämna tillbaka hans huvud.$B$B<Alexi gäspar.>$B$BSkynda på nu."}, -- quests-batch-18-sv
[5361]={t="Släktträd", o="Lämna Klippvaktslånghornsrapport till Nataka Longhorn vid Spökvandrarposten i Ödelandet.", d="Min bror Nataka är stationerad vid Spökvandrarposten borta i Ödelandet. Jag skulle vilja be dig ... kan du ge den här rapporten till honom åt mig? Det har gått ett år sedan jag skrev senast, det har förekommit ovanlig kentaurverksamhet sedan dess och han bör bli informerad.$B$BResa till Stenklobergen norr om Korsvägen, och ta dig sedan västerut in i Den förkolnade dalen. Därifrån, ta dig söderut in i Ödelandet; där hittar du en väg söderut till Spökvandrarposten."}, -- quests-batch-04-sv
[5381]={t="Iruxos hand", o="Hämta Demonlådan från Thunder Axe-fästningen, och lämna den, tillsammans med Demonhackan, till Taiga Wisemane i Skuggbytesbyn.\\r\\n", d="Brinnande klingan har Demonlådan. I den finns den mäktiga Iruxos hand. Brinnande klingan använder den för att öppna demoniska portaler vid Mannorockulten. Vi måste stoppa strömmen av demoner som kommer in i vår värld, $n!$B$BAnvänd den här demonhackan på den röda kristallen i Thunder Axe-fästningen för att få tillgång till Demonlådan."}, -- quests-batch-12-sv
[5386]={t="Dagens fångst", o="Tala med Jinar'Zillen i Skuggbytesbyn och lämna sedan 2 blodmagfiskar till Nataka Longhorn.", d="Doften av stekt fisk har saknats här vid Spökvandrarposten under lång tid. Trollen i Skuggbytesbyn är bäst på att fånga fisk... men tyvärr, med all kentaurens aktivitet har jag lite tid att göra en resa till trollen. Hrm...$B$BGör mig en tjänst och res till Skuggbytesbyn. Tala med den lokale fiskaren Jinar'Zillen och ta med min favorit, blodmagfisk, tillbaka till mig. Vägen söderut härifrån leder dig västerut till trollbyn."}, -- quests-batch-05-sv
[5501]={t="Bensamlare", o="Ta med 10 kodoben från Kodokyrkogården till Bibbly F'utzbuckle vid Kormeks hydda.", d="Vi sitter på en guldgruva här, säger jag dig - en guldgruva!  Kodoben kommer att förändra världen för alltid ... Jag har kunder som tillverkar möbler, musikinstrument och till och med sprängpulver av dem.$B$BDet kommer en karavan förbi som hämtar mina kodoben och sedan säljer dem i Skuggbytesbyn.  Om du kan ta dig till kodokyrkogården söder om här och ge mig tio kodoben, ger jag dig något i gengäld.  Är vi överens?"}, -- quests-batch-01-sv
[5561]={t="Kodosamling", o="Ta med fem Tämjda kodoer och Kodokombobulatorn tillbaka till Smeed Scrabblescrew vid Scrabblescrews läger.", d="Bibbly tror att han är den enda goblinen i Ödelandet som vet hur man tjänar pengar.  Tja, den enda karavan som är modig nog att resa här omkring är beroende av mig.  Ända sedan jag lärde mig att föryngra och kontrollera åldrade och döende kodoer med min kodokombobulator ingick karavanägaren Cork, Rigger och jag ett partnerskap.$B$BTa kombobulatorn och använd den på varje uråldrig, åldrad eller döende kodo; den ger odjuret en chock och gör det till en tämjd kodo som tvingas följa dig.  När du har tämjt en kodo, ta tillbaka den till mig."}, -- quests-batch-14-sv
[5741]={t="Ljusets spira", o="Hämta Ljusets spira och återlämna den sedan till Azore Aldamort vid tornet i Ethel Rethor.\\r\\n", d="Brinnande klingan i Thunder Axe-fästningen österut ryktas ha fått tag på Ljusets spira av nagorna. Legenden säger att spiran kan sänka hela städer under de stora haven. Brinnande klingan får inte tillåtas besitta en sådan makt.$B$BDärför måste du själv hämta spiran!  Den innehas av en siare från Brinnande klingan, som studerar spiran från ett av Thunder Axes vakttorn."}, -- quests-batch-02-sv
[5762]={t="Hemet Nesingwary", o="För med dig Kravels låda till Hemet Nesingwary i Strypetörnsdalen.", d="Jag har ett paket till en gammal kund, en dvärg vid namn Hemet Nesingwary. Paketet tog veckor att anlända, och Hemet är för länge sedan borta. Han sa att han skulle till Strypetörnsdalen för att jaga djuren där, men han lämnade mig pengar för att skicka leveransen när jag kunde. $B$BHemet är en rik dvärg och det är en god idé att hålla kontakten med de rika, eller hur? Så... vill du leverera paketet åt mig?$B$BJag har hört att Hemet har ett läger i Strypetörnsdalen, norr om Grom'gol."}, -- quests-batch-02-sv
[5763]={t="Jakten i Strypetörnsdalen", o="För Roons kodohorn till Hemet Nesingwary i Strypetörnsdalen.", d="För länge sedan kom en dvärg till det här landet. Hans namn var Hemet och han önskade jaga stora odjur. Hans skicklighet med geväret var häpnadsväckande, och vi tillbringade många dagar med att jaga tillsammans. Även fiendskapen mellan våra folk glömdes.$B$BNär han lämnade Ödelandet för Strypetörnsdalen, svor jag på att en dag välkomna honom tillbaka så att vi kan jaga igen. Nu är den tiden.$B$BTa med det här kodohornet till Hemet. Han kommer att förstå att det är från mig. Du hittar honom i Strypetörnsdalen, norr om Grom'gol-baslägret."}, -- quests-batch-06-sv
[5821]={t="Livvakt att hyra", o="Eskortera Gizelton-kravanen förbi kentaurbyn Kolkar. Tala med Smeed vid Scrabblescrews läger för att få din belöning.", d="Under normala omständigheter skulle Rigger och jag leda våra kodoer förbi Kolkar-kentaurerna. Då och då hör vi kentaurernas krigstrummor, och när vi hör dem stannar vi. Det är inte bra för affärerna att vara död!$B$BJag ska säga dig något $c, om du skyddar oss förbi Kolkar-byn gör vi det värt din möda.$B$BDet är bara ett kort avstånd, allt du behöver göra är att hålla karavanen intakt så kan du hämta din belöning av Smeed Scrabblescrew - han finns en bit ner längs vägen. Vi gör lite affärer tillsammans.Eskortera Gizelton-kravanen förbi Kolkar-kentaurbyn"}, -- quests-batch-12-sv
[5943]={t="Gizelton-kravanen", o="Eskortera Gizelton-kravanen genom Mannorockulten. Tala med Smeed vid Scrabblescrews läger för att få din belöning.", d="Du ser ut som en duglig $r. Kanske är du ute efter att tjäna lite pengar? Cork och jag startade den här karavanen för att tjäna en hacka; vi anade inte vilka faror det innebär att försöka tjäna en slant!$B$BLängre fram ligger Mannorockulten ... vanligtvis ignorerar demonerna oss men något har skrämt upp kodoerna den här gången. Jag betalar dig för att skydda karavanen förbi Mannorockulten. När vi väl är säkert förbi kan du få din belöning av vår affärspartner Smeed vid Scrabblescrews läger.Eskortera Gizelton-kravanen förbi Mannorockulten"}, -- quests-batch-02-sv
[6134]={p="Jag har en stark misstanke om att Magram är MYCKET intresserade av det här kletet. Jag planerar att sälja det till dem."}, -- quests-batch-32-sv
[6141]={t="Broder Anton", o="Tala med broder Anton i Ödelandet.", d="Min vapenbroder, broder Anton, hörde rykten om ett angrepp av odöda i det avlägsna Kalimdor, i ett land känt som Ödelandet.  Anton bokade genast resa dit för att söka upp och förgöra det odöda hotet!$B$BHan söker dem som har modet och beslutsamheten att hjälpa honom.  Om ditt hjärta är sant, tala då med Anton.  Han finns i Ödelandet, i Alliansens stad Nijels udde."}, -- quests-batch-09-sv
[6142]={t="Betesmusslor", o="Hitta 10 bitar mjukskalig musselkött och ta dem till Mai'Lahii i Skuggbytesbyn.", d="Du ser ut som en fiskare, $c! Jag älskar att fiska - har fiskat hela mitt liv. Det bästa betet man kan använda är mjukskaligt musselkött; fiskarna kan helt enkelt inte motstå det, du förstår vad jag menar?$B$BLängre norrut kommer du att hitta ett vrak utanför kusten. Mjukskaliga musslor ligger strödda över hela området. Om du tar med mig 10 bitar mjukskaligt musselkött ska jag ge dig något i utbyte."}, -- quests-batch-14-sv
[6143]={t="Annat att ta itu med", o="Döda 7 Slitherblade-myrmidoner, 7 Slitherblade-nagor och 5 Slitherblade-trollkvinnor, och tala sedan med Drulzegar i Skuggbytesbyn i Ödelandet.", d="Kanske har du hört, kanske inte ... min besättning och jag var ute och fiskade nära Ranazjarön, norr om skeppsvraket utanför kusten längre norrut. Vi brukade fiska där jämt; nu tänker jag bara på hur jag ska kunna hämnas mina stupade kamrater.$B$BNagorna anföll oss en morgon och dödade alla utom mig.$B$BSamvetet mitt klarar inte skulden, $c; jag vill att du ger dig av och steker de där nagorna åt mig. Jag ska se till att det blir värt besväret; tror du att du kan hjälpa mig med det?"}, -- quests-batch-01-sv
[6161]={t="Gör anspråk på Rackmores skatt!", o="Hitta Rackmores silvernyckel.  Hitta Rackmores guldnyckel.  Hitta och öppna Rackmores kista.", d="Rackmores loggbok berättar om hur hans skepp seglade mot Fjädermånsfästet när det angreps av sjölevande varelser. För att hindra att hans skatt föll i fiendens händer gömde han sin kista på Ranazjarön.$B$BFör att öppna kistan krävs två nycklar, en av silver och en av guld.  Dessa nycklar gick förlorade, men om nycklarna och kistan hittas väntar en skatt!"}, -- quests-batch-15-sv
[6521]={t="En ohelig allians", o="För med dig ambassadör Malcins huvud till Varimathras i Understaden.", d="Malcin påstår att han befinner sig utanför Knivkärrets kullar. Denna ambassadör måste dödas – hans uppdrag är ett misslyckande i Lichkungens ögon.$B$BHans närvaro där förklarar mycket av det vi upptäckt om området – vissa av piggsvinsfolket har blivit skrämmande kraftfulla samtidigt som de visar tecken på pesten på sitt eget sätt. Det måste sannerligen vara ett tecken på någon sorts överenskommelse de har slutit.$B$BHitta Malcin och dräp honom, $n. Återvänd till mig när dådet är utfört."}, -- quests-batch-14-sv
[6522]={t="En ohelig allians", o="Ta Liten skriftrulle till Varimathras i Understaden.", d="Min dam,$B$BDu vet mycket väl vad det är vi erbjuder. Chansen för dig att ta Kargmarkerna och landen bortom är stor. Vi vill helt enkelt ha din hjälp i gengäld. Med hjälp menar vi inget annat än att du ger oss friheten att agera i området.$B$BVar snäll och låt oss diskutera detta vidare. Vi har stor makt och är villiga att dela med dem som är kloka nog att ansluta sig till oss. Jag stannar utanför Knivkärrets kullar tills vidare.$B$BMed vänliga hälsningar,$BAmbassadör Malcin"}, -- quests-batch-15-sv
[6610]={t="Musslovertärta", o="Dirge Quikcleave vill att du hämtar följande föremål:$B$B12 jätteägg. Du hittar dessa hos rokar som vandrar i Tanaris eller hos andra stora fågelarter.$B$B10 bitar smakrik musselkött. De hittas i musslor, naturligtvis!$B$B20 bitar Alterac-schweizer. Bege dig till ett mejerier!$B$BSamla alla föremål och återvänd till Dirge.", d="Har du någonsin hört talas om en musslovertärta? Självklart har du inte det! Det är mitt senaste och främsta kulinariska mästerverk. Åh, $n, bara tanken på en musslovertärta får mig att dregla.$B$BTyvärr har jag slut på ingredienser för att göra någon! Hur om vi gör en deal? Du samlar ingredienserna jag behöver för att göra en musslovertärta, så ska jag lära dig de finare detaljerna i exotisk kokkonst och jag slänger till och med med ett par musslovertärter på köpet! Deal??$B$BHär är vad jag behöver:"}, -- quests-batch-32-sv
[6627]={t="Kunskapsprov", o="Svara framgångsrikt på Braug Dimspirits fråga och tala sedan med honom igen. Han stannar i Stenklobergen när du är redo.", d="Du har tagit med mig boken, och nu är det dags för din fråga. Är du redo?$B$BTiden är ingen fråga, $c, så känn dig inte pressad. Du får ta så lång tid du vill på dig att svara.Svara rätt på Braug Dimspirits fråga"}, -- quests-batch-27-sv
[6628]={t="Kunskapsprov", o="Svara framgångsrikt på Parqual Fintallas fråga och tala sedan med honom igen. Han stannar i Understaden tills du är redo.", d="Så, tiden är åter inne. Som lärdomsstudent har du visat stor uthållighet genom att åta dig min uppgift.$B$BOch nu erbjuder jag dig din fråga. Om du är redo, tala med mig igen, och ta all den tid du behöver, $n--det finns ingen press att svara snabbt.Svara rätt på Parqual Fintallas fråga"}, -- quests-batch-28-sv
[7067]={t="Pariarens instruktioner", o="Läs pariarens instruktioner. Hämta sedan Unionens amulett från Maraudon och lämna tillbaka den till kentaureparianen i södra Ödelandet.", d="Trots att jag är förvisad som kättare är min tro fortfarande sann – det är det som driver mig framåt. Men för att mitt öde ska fullbordas behöver jag hjälp från en utomstående... någon som inte tillhör någon kentaurstam.$B$BUppgiften kräver att någon går in i Maraudons heliga hallar – en grav som mitt folk skyddar, och där endast de mest hängivna någonsin tillåts träda in.$B$BOm du går med på att hjälpa mig behöver du bara nicka. Jag ska ge dig ett pergament med mina instruktioner. Läs igenom det och fundera över mina ord."}, -- quests-batch-32-sv
[7141]={t="Slaget om Alterac", o="Gå in i Alteracdalen, besegra Hordens general Drek'thar och återvänd sedan till prospektören Stonehewer i Alteracbergen.", d="Upptäckarförbundet tror att det finns artefakter i Alteracdalen, men Frostvargsorcherna låter oss inte utforska.  Vi kan inte låta Horden stoppa våra vetenskapliga strävanden!  Besegra Frostvargarnas general, Drek'Thar.  Med honom död förlorar orcherna sitt övertag.$B$BDrek'Thar finns i Frostvargsfästet, i södra Alteracdalen.  Besegra honom och återvänd sedan till mig.Besegra Drek'thar."}, -- quests-batch-16-sv
[7142]={t="Striden om Alterac", o="Gå in i Alteracdalen och besegra dvärggeneralen Vanndar Stormpike.  Återvänd sedan till Voggah Deathgrip i Alteracbergen.", d="Stormpike-dvärgarna och deras allierade har invaderat Alteracdalen, och vi måste driva ut dem!  För att vinna striden om Alterac måste vi besegra deras general, Vanndar Stormpike!$B$BDu hittar Vanndar i Dun Baldar, i norra Alteracdalen.$B$BFörgör honom, $n, och återvänd sedan till mig.Besegra Vanndar Stormpike."}, -- quests-batch-18-sv
[7321]={t="Lugnande sköldpaddssoppa", o="Lämna 10 stycken sköldpaddskött och lite lugnande kryddor till Christoph Jeffcoat i Tarrens kvarn.", d="Vem säger att de odöda inte kan någonting om matlagning? Ta mitt hemliga recept på sköldpaddssoppa som exempel. Jag har känt folk som skulle ha återvänt från döden bara för att njuta av en skål! Heh, heh...$B$BPå tal om det, jag har inte kunnat laga någon på sistone. Jag brukade själv bege mig till Lordameresjön för att jaga snapjaws, those nasty things, men jag kan inte slita mig loss från mitt arbete här.$B$BOm du hämtar lite sköldpaddskött från snapjaws och lugnande kryddor, ska jag visa dig hur det går till!"}, -- quests-batch-32-sv
[8427]={t="Slaget om Krigssångsklyftan", o="Ta med 3 Krigssångsklyftans hedersmärken till en krigsbringare från Horden utanför slagfälten.", d="Striden i Krigssångsklyftan mot Silvervingarnas väktare är av stor vikt.  Under täckmantel av att skydda en skog som inte tillhör dem försöker Alliansen förvägra Horden en av våra största virkeskällor.$B$BLåt inte det ske, $n!  Kom tillbaka till mig med bevis på att du tjänat Horden på ett värdigt sätt!"}, -- quests-batch-22-sv
[8436]={t="Erövra Arathibäckenet", o="Ta med 3 Arathibäckenets hedersmärken till en krigsbringare från Horden utanför slagfälten.", d="Vår konflikt med Alliansen har eskalerat till ett sant krig.  Inte längre används eller förväntas falska förevändningar för att gå in i strid av någondera sidan vid det här laget.$B$BStriden om Arathibäckenet gäller resurser, rent och skärt.  Antingen får Alliansen resurserna och använder dem mot oss eller så får vi dem och använder dem för att hålla vår krigsinsats igång.  Hjälp Skändarna att upprätthålla flödet av resurser vi behöver, $n!"}, -- quests-batch-23-sv
[8551]={t="Kaptenens kista", o="Lämna Smotts kista till Hecklebury Smotts i Bytesbukten.", d="Jag brukade segla ett skepp härifrån hela vägen till Spärrhake i Kalimdor. Jag var en framgångsrik kapten med ett oklanderligt rykte.$B$BTills...$B$BDessa förbannade havsjättar ruinerade mig! De krossade mitt skepp, dödade min besättning och satte mig i en livbåt till Bytesbukten. Och en av jättarna, Gorlash, stal min kaptenskista. Han sa att han ville ha den som en snusdosa. Vilket vågspel!$B$BJag har hört att Gorlash vandrar längs kusten öster om här. Hitta honom och hämta min kista! Gör det, så har du förtjänat en kaptens tacksamhet."}, -- quests-batch-19-sv
[8961]={t="Eldens tre kungar", o="Samla Incendius incendicit, Glödskådarens glöd och Asharells aska, tillsammans med en Helgad eldskål, och återvänd med dem till Bodley inne i Svartklippeberget.", d="För att frammana Lord Valthalak måste vi först samla ihop de andra två tredjedelarna av amuletten. För att göra det behöver vi en eldskål och några speciella kol att bränna i den.$B$BDet finns tre eldadelsmän, Lord Incedius i Svartklippans djup, Pyrovakten Glödskådaren i Svartklippsspiran och Exekutor Asharell i Brinnande stäppen, som har det vi behöver. Samla en del av deras kvarlevor från var och en och återvänd sedan till mig med en Helgad eldskål, som kan köpas av Silvergryningen om du är Ärad hos dem."}, -- quests-batch-25-sv
[79007]={t="... och lappen du hittade", o="Förkolnade rester av lappen är din enda vägvisare.", d="<Medan det svaga skenet från glöden mörknar snavar du över resterna av en nyligen släckt eld.\\r\\n\\r\\nBland de utspridda förnödenheterna upptäcker du en bränd lapp.>\\r\\n\\r\\n\"Allt som brinner är inte förlorat. Hitta tvillinglandet, hitta platsen.\""}, -- quests-batch-25-sv
[79229]={t="Landsvägsrån", o="Hitta någon i Ödelandet som känner till det plundrade lägret.", d="Lägerplatsen framför dig är en makaber syn. Att döma av kvarlevorna var offren två människor och en dvärg. Märken på benen tyder på ett vilt angrepp, men de plundrade förnödenheterna visar att det inte var ett djur. Såren stämmer inte heller med kentaurernas vapen.\\r\\n\\r\\nKanske skulle en erfaren skrotletare i de här trakterna veta vad man ska göra av detta."}, -- quests-batch-10-sv
[79360]={t="�Elementarhjälp", o="Besegra Charlga Razorflank i Knivkärrets snårskog och samla information om piggsvinsfolkets planer.", d="Nu när du har bemästrat elementen har du en förpliktelse mot dem, och därmed mot hela Azeroth. Vi kallar på dem om hjälp, vi kräver inte deras kraft. Det är dags att du återgäldar tjänsterna du fått. Och jag tror jag vet hur.\\r\\n\\r\\nPiggsvinsfolket vrider elementen för egna syften, och verkar utvidga sitt grepp inom de här gränserna. Gå in i deras snårskog och sätt stopp för vad de än smider för planer. De här landen måste skyddas.Ta den Trasiga anteckningen till Rau Cliffrunner i Tusen nålar."}, -- quests-batch-29-sv
[79361]={t="Storm, jord och eld", o="Samla $1oa förvridna eldtotems, $2oa förvridna jordtotems, $3oa förvridna lufttotems och $4oa förvridna vattentotems åt Prate Cloudseer i Tusen nålar.", d="Så, piggsvinsfolket tänker översvämma Tusen nålar med sin förvridna shamanism, gör de? Det verkar nästan ofattbart, men du har själv sett att dessa varelser inte ska tas lätt på.\\r\\n\\r\\nJag hade velat fortsätta din träning på allvar, men det finns ingen tid för det nu. Dessa land är hem för många olika varelser, vän som fiende, och ingen av dem förtjänar ett sådant öde. Vi måste agera.\\r\\n\\r\\nTa den här boken. Den var avsedd för studier, men kan nu hålla nyckeln till att skingra den kommande stormen."}, -- quests-batch-22-sv
[79442]={t="Ovädrets vapen", o="Leverera Ovädrets öga till Bath'rah vindväktaren i Alteracbergen.", d="Vårt folk kan inte tacka dig nog, men jag har ingen verklig användning för det här ögat. Jag har hört talas om en gammal shaman i Alteracbergen som har ett öga för stormelementarmagi. Kanske kan han tillverka något åt dig."}, -- quests-batch-23-sv
[79624]={t="Alla kan laga mat", o="Hitta en oger som kan läsa det oläsliga receptet.", d="Receptet verkar vara på någon sorts kötträtt. Det är skrivet på ett språk du inte förstår. Ogerska är din bästa gissning, med tanke på källan och ämnet.\\r\\n\\r\\nOger är vanligtvis inte kulinariska typer men om du kände någon med en sådan böjelse kunde de översätta receptet åt dig."}, -- quests-batch-15-sv
[79677]={o="Skonk kan laga mat, men behöver ingredienser. Du skriver upp. Hitta ingredienser. Skonk mer fokuserad på själva lagningen; inte riktigt en logistikkille."}, -- quests-batch-32-sv
[81570]={t="Jarl behöver en klinga", o="Ta med ett bredsvärd av månstål till Jarl i Dammträsket.", d="Jag har saker att skära.  Jag kan inte säga vad jag ska skära, men ... jag behöver en klinga åt mig.  En viss klinga ...$B$BNågra kallar den ett bredsvärd av månstål.  Jag kallar den ett svingblad.$B$BHjälper du mig?  Kanske hittar du det i stan, kanske pratar du med en smed så gör han ett speciellt.$B$BMen somna inte på det här.  Det jag ska skära håller inte för evigt ..."}, -- quests-batch-03-sv
[86576]={t="Blodvredesprylar", o="Ta med $1oa glittrande solstenar till Mor'rogal.", d="Förutom att sprida sin smuts över Den förkolnade dalen samlar Blodvredes harpyor på allt glänsande de kan hitta. Jag har hört att de samlar på olika guldgula solstenar som dekoration. Jag har ingen nytta av sådana prylar, men Mor'rogal har nämnt att han använt dem förut.\\r\\n\\r\\nMedan du bekämpar dalens harpyor, håll utkik efter glittrande solstenar. Ta med alla du hittar till Mor'rogal, uppe på kullarna ovanför oss."}, -- quests-batch-07-sv
[86784]={t="Pinnar och ben", o="Samla $1oa torra grenar och ta dem till Eleanor Shackleton.", d="Min kollega Eleanor Shackleton är stolt över att resa i vildmarken och överleva mot väder och monster. Hon har just nu läger inte långt härifrån, i kullarna i väster, och jag minns ett råd hon en gång gav mig: \"När du tror att du har tillräckligt med ved, samla fem gånger mer.\"\\r\\n\\r\\nOm du har lite ledig tid kan du samla ved i den här korgen och ta den till hennes läger. Jag är säker på att hon kan ge dig några tips om tillvaron som en resande äventyrare."}, -- quests-batch-18-sv
[91920]={t="Vilda ögon", o="Samla 3 murlocögon och ta dem till apotekare Renferrel vid Gravvalvet.", d="Jag skulle inte våga ifrågasätta effektiviteten hos apotekare Renferrels formler, men jag skulle ljuga om jag sa att brygden gjorde någon märkbar skillnad.\\r\\n\\r\\nLängs stranden av Lordameresjön finns en svärm av murlocs, och väsentligt nog har murlocs ögon. Jag misstänker att apotekarens villighet att prova nya saker hålls tillbaka av hans nyliga besatthet av hjärtan. Ta med honom några.\\r\\n\\r\\nOm mitt val står mellan att oundvikligen dö en andra död eller att få Renferrel att döda mig för att jag ifrågasatt hans metoder, väljer jag det senare."}, -- quests-batch-17-sv
[92401]={o="Det finns saker där som jag inte kan hantera, men om du är villig behöver jag få veta vad som hänt min make.", d="Undersök försvinnandet av Edward Heartweaver i Lordaerons ruiner."}, -- quests-batch-32-sv
[92421]={o="Om vår ärorika kapten Garek Bandarion fortfarande hade varit med oss, så vet jag vad han hade önskat. Att slutföra det han påbörjade och hela våra fränder. För Lordaeron!"}, -- quests-batch-32-sv
[92434]={t="Blod på gatorna", o="Hitta ett sätt in i Dalaran längs Lordameresjön.", d="Vad det än var som fick Dalarans barriär att sänkas har det lämnat staden i uppror. Eftersom du har tagit hand om deras patruller finns det ingen bättre tid än nu för oss att ta oss in och upptäcka deras hemligheter.\\r\\n\\r\\nTa nyckeln du hittade vid interneringslägret och sök upp deras kloaker längs stadens norra gräns. Med lite tur hade de där magikerna ingen anledning att lägga en skyddsbesvärjelse över en så ... obehaglig ingång.Hitta ett sätt in i Dalaran längs Lordameresjön"}, -- quests-batch-10-sv
[92519]={t="Påfyllning av sjukavdelningen", o="Hämta en låda Förpackade tonika vid Jorells labb i Go'shek-gården och återvänd till doktor Gregory Victor i Hammarfall.", d="Apotekare Jorell skulle ha tagit med oss en låda motgifter och elixir för flera dagar sedan, men vi står fortfarande med tomma händer. Den där dåren har förmodligen förgiftat sig själv igen genom att brygga i den dåligt ventilerade kåken han kallar sitt labb.\\r\\n\\r\\nOm du vill hjälpa vår avdelning ytterligare vore du en mycket mer pålitlig person för det här jobbet.\\r\\n\\r\\nFölj vägen till Go'shek-gården, söder och lite väster om här. Du hittar den sannolikt packad och redo att gå, med Jorell antingen försvunnen eller ointresserad av sina skyldigheter."}, -- quests-batch-25-sv
[92706]={t="EFTERLYST: Bruuz", o="Ta med Bruuz ryggfena till Gazlowe i Spärrhake.", d="Alla sportfiskare, hör upp!\\r\\n\\r\\nEn jättehaj har cirklat i vattnet nära lastbryggan och angripit sjömän och småbåtar. Hamnarbetarna har gett den öknamnet \"Bruuz\". En rejäl belöning utlovas den som ger mig dess fena!\\r\\n\\r\\n-- Gazlowe"}, -- quests-batch-10-sv
[92743]={p="Gör detta för mig, så ska jag avslöja Magrams största styrka."}, -- quests-batch-32-sv
[92867]={t="Mark att behålla", o="Besegra inkräktarna från Boulderfist, Syndikatet och Vissenbark i Stromgardefästet och återvänd till markförvaltare Lomar.", d="Vårt arv må vara på väg att falla sönder, men det här är inte vår sista skans. Vi har mer i reserv, och det måste förbli dolt för sitt eget skydd.\\r\\n\\r\\nStödet växer för att bevara våra återstående skulpturer och heliga gravplatser. Pöbeln som har tagit sig bostad i vårt gamla kungarike har ingen aning om hämnden som väntar dem.\\r\\n\\r\\nDriv tillbaka Boulderfist och Syndikatet. De måste lära sig att Stromgarde inte bara är näve, örn och stenar."}, -- quests-batch-31-sv
[93125]={t="På väg hem", o="Behåll ditt anseende hos Gelkis och eskortera Rokren ut ur de Utstöttas gömställe. Informera sedan Nerlokh nära Benens dal om vad som hände.", d="Du! Jag såg dig utanför när du slogs mot de utstötta. Jag vet inte var du kommer ifrån, men jag behöver din hjälp.\\r\\n\\r\\nJag lockades hit av mina Gelkis-bröder med en försäkran om säkerhet. Jag visste att kriget i Ödelandet eskalerade bortom vår kontroll, men jag föreställde mig aldrig att mitt eget folk skulle ta till nekromanti i ett invecklat försök att hoppa av till Magram-klanen. När jag talade emot detta hotade de att döda mig om jag någonsin satte hov utanför det här tältet!\\r\\n\\r\\nSnälla hjälp.Eskortera Rokren ut ur de Utstöttas gömställe"}, -- quests-batch-24-sv
[93176]={t="Mina små vänner", o="Använd föremålen i Startutrustning för entomologi för att hitta och fånga en trädtarantel, ett höviveleprov och en köttplockare.", d="Beundrar du min lilla menageri, är det så? De är mitt livsverk som odöd. Jag har tillbringat otaliga timmar med att studera dem: deras anatomi, deras kost, till och med deras sociala ritualer.\\r\\n\\r\\nVill du ansluta dig till mig i hobbyn? Här, ta det här paketet. Anteckningarna och materialet i det bör få dig att komma igång. Om du tappar bort det måste du köpa ett nytt av mig för en liten avgift."}, -- quests-batch-28-sv
[93225]={t="Snidade kentaurtotemer", o="Skaffa $1oa snidade kentaurtotemer genom att döda kentaurer av vilken klan som helst i hela Ödelandet, och lämna dem sedan till Gurda Wildmane vid Spökvandrarposten.", d="Jag har lagt märke till att kentaurer från olika klaner ibland samlas utanför bosättningarna och bedriver handel. Jag har observerat detta under många nätter och till synes med varje klan; viktigast är att jag har sett valutan de använder: snidade totemer.\\r\\n\\r\\nJag tror att vi kan vända utvecklingen till vår fördel med antingen Gelkis eller Magram om vi levererar en tung bunt totemer direkt till dem. Jag har redan börjat snida några, men jag tvivlar på att de lätt låter sig luras utan några äkta."}, -- quests-batch-08-sv
[93429]={t="Blod av mitt blod", o="Döda 10 Förlorade i Fallow Sanctuary.", d="Även om de är vårt släkte har de Förlorade i Fallow Sanctuary blivit varelser av ren våldsamhet och hat.\\r\\n\\r\\nDet kan inte finnas någon återlösning eller frälsning för dem. De är dömda att vandra i det här träsket som själlösa, hatfulla varelser hela sina liv.\\r\\n\\r\\nDeras lidande måste ta slut. Någon måste befria dem från deras misär. En makaber uppgift, jag vet, men skulle du göra det för att skydda oss som är kvar?"}, -- quests-batch-22-sv
[93430]={t="Ta tillbaka betet", o="Hitta den Förlorade-fiskare som stal Pelluks bete och ta tillbaka det.", d="Nu har de verkligen gjort det! Som om de eländena inte redan var nog att hantera har en av dem stulit mitt lyckobete!\\r\\n\\r\\nJag var just ute och fiskade i morse, när en kom upp ur gyttjan, skar av min lina och sprang iväg med den. Tjuven är nästan säkert en av de Förlorades egna fiskare, som hoppas kunna använda betet själva.\\r\\n\\r\\nTja, vår fisktillgång beror på det betet, så jag behöver få tillbaka det. De Förlorade fiskar längs stränderna öster om här. Hitta den tjuven, $r!"}, -- quests-batch-28-sv
[93464]={o="Jag ber dig att finna denna magiker, $r. Hans kunskap skulle kunna vara av enormt värde för oss."}, -- quests-batch-32-sv
[93604]={t="Agamaggans blod", o="Ge dig av till Knivkärrets kullar och skaffa Agamaggans virulenta blod, och lämna det sedan till Kog'thug den modige vid Borstryggens tillflyktsort i Ödelandet. Kog'thug ansåg det värt att påminna om att Agamaggans blod inne i Knivkärrets snårskog inte räcker.", d="Stor $R hört om Knivkärrets kullar? <Fnys.> Förstås inte! Stor plats i Kargmarkerna. Massor av törnen. Kan inte missa.\\r\\n\\r\\nAgamaggan dog där. Viktig plats för alla piggsvinsfolk. Nu borstrygg inte tillåten. Tillhör snörvlande-fnysande Knivkärret. Knivkärret respekterar inte piggsvinsfolkets historia!\\r\\n\\r\\nAgamaggans blod föder dalen. Växer törnen. STORA. Större än fjuttigt alvhalsband någonsin kunde!\\r\\n\\r\\nGå till kullarna. Hämta blod till Kog'thug. Unket blod från snårskogen duger inte. Behöver GOTT blod!\\r\\n\\r\\nGe blod, få halsband, vinn."}, -- quests-batch-27-sv
[93663]={t="Borttappad under transport", o="Hitta den saknade kuriren och se till att Dars sändning levereras till The Harborage.", d="Draeneierna vid Harborage är skickliga fiskare och villiga att trala farligare vatten än jag. Vi handlar ibland. De ger oss en del av sin fångst, och jag erbjuder en del av våra överskottsförnödenheter.\\r\\n\\r\\nJag hade skickat en goblinkurir för att leverera min senaste sändning, men han kom aldrig tillbaka. En krokolisk gjorde säkert en måltid av honom.\\r\\n\\r\\nViktigare är att mitt rykte i affärsvärlden står på spel. Den sändningen måste hittas och levereras till hamnen. Snälla, hitta den om du kan. Leta vid vattnet längs vägen."}, -- quests-batch-27-sv
[93678]={p="Även om mina svar inte är definitiva, ta gärna med dig dessa anteckningar tillbaka till träsket. Jag hoppas att du förstår varför jag inte följer med."}, -- quests-batch-32-sv
[93680]={t="Nyckeln till staden", o="Skaffa Nyckel till Dalarans kloaker åt magus Wordeen Voidglare i Tarrens kvarn.", d="Alliansen hade en armé av magiker kända som Kirin Tor. Även om de var mäktiga visade sig den demoniska Brinnande legionen vara ännu mäktigare. I ett enda slag jämnade ärkedemonen Archimonde deras stad med marken som om den vore en barnleksak. De som blev kvar reducerades till blott egendomslösa luffare.\\r\\n\\r\\nTills de byggde upp Dalaran igen. Och dessutom på Mörka damens egen dörrtrösk!\\r\\n\\r\\nSök i deras läger efter något som kan ta oss in i staden obemärkt. Jag måste veta mer."}, -- quests-batch-12-sv
[93976]={d="Ta det här. När du lämnar över det, låt henne veta att jag skickade dig. Och säg åt henne att vi är kvitt."}, -- quests-batch-32-sv
[94215]={t="Hantverksorder: Dryck för fri handling", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Dryck för fri handling, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-28-sv
[94220]={t="Hantverksorder: Dolk med pärlhandtag", o="Skaffa föremålen som kunden begärt och leverera dem till platsen markerad på din karta. Denna order måste vara i din ägo för att slutföra transaktionen.", d="<Skrivet med blekt bläck begär noten en $2oa dolk med pärlhandtag, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order är överförbar.>"}, -- quests-batch-32-sv
[94221]={t="Hantverksorder: Guldstav", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Guldstav, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-32-sv
[94222]={t="Hantverksorder: Regnbågsskimrande hammare", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Regnbågsskimrande hammare, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-21-sv
[94239]={t="Hantverksorder: Fina läderbyxor", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Fina läderbyxor, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-32-sv
[94251]={t="Hantverksorder: Fenixbyxor", o="Skaffa föremålen som kunden begärt och leverera dem till platsen markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär noten $2oa Fenixbyxor, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-32-sv
[94481]={t="En portion styrka", o="Mata $1oa Rog'mar-rekryter på träningsfältet.", d="Denna mustiga gryta håller våra rekryter mätta, tillräckligt för att fienderna ska hålla sig på avstånd.\\r\\n\\r\\nTa med den här och mata våra rekryter i väster. Lyssna inte på några klagomål. Med hur svårt det blivit att försvara våra försörjningslinjer borde de vara lyckligt lottade att vi inte ger dem smuts att äta."}, -- quests-batch-24-sv
[94483]={t="Visa hur det går till", o="Döda $1oa Farholde-präster och $2oa Farholde-spanare söder om floden.", d="Våra spanare har rapporterat träningsläger vid floden i söder. Hade jag fått besked tidigare hade det besparat oss båda besväret med att lokalisera och avlägsna människoavskummet i tid.\\r\\n\\r\\nFortsätt dina ansträngningar, $n. Att hålla tillbaka människorna till deras dyrbara lilla fäste köper oss tid att fokusera på andra aktuella ärenden.\\r\\n\\r\\nSkynda dig."}, -- quests-batch-21-sv
[94532]={o="Röj en väg för våra allierade genom att eliminera hotet."}, -- quests-batch-32-sv
[94533]={t="Snargls nos", o="Leta upp Snargl i Borstkullarna, döda honom och hämta hans nos åt Neza Bloodsnout.", d="Bland de kacklande invånarna i Borstkullarna sydväst om här finns en äldre gnoll vid namn Snargl. Ljuden som kommer från just den här gnollen är ganska obehagliga. Deras närvaro inspirerar dem omkring, vilket skapar ett problem för allierade och spanare som kommer in i området.\\r\\n\\r\\nEn trofé som minne av att vi tagit hand om den här mest obehagliga gnollfienden skulle passa fint i min samling.\\r\\n\\r\\nSkynda dig, $n."}, -- quests-batch-16-sv
[94535]={p="Res söderut, lokalisera deras läger och hämta den stulna malmen. Ta den från deras döda kroppar om det behövs."}, -- quests-batch-32-sv
[94968]={t="Muggs öga", o="Infiltrera Krol'dok-fästet och återvänd till Krom'rosh med bevis på deras ledares död.", d="Av de få som lyckades infiltrera grottan har de flesta omkommit. Det verkar som att dessa Skymningsfolk har ett fotfäste mycket större än vi trodde. Vi ska inte stå passiva medan de här kultisterna fortsätter att härja i de här landen och offra våra allierade. Vi gör slut på det här nu, $n.\\r\\n\\r\\nInfiltrera detta fäste, slakta deras styrkor och ta med mig bevis på deras ledares död."}, -- quests-batch-20-sv
[94972]={t="Skymningens foliant", o="Hämta Skymningens foliant från Krol'dok-fästet.", d="Nu när deras plats är avslöjad är det troligt att det inom det här fästet finns hemligheter som hållits väl dolda från dem vi hittills mött. Det vore klokt av oss att hitta och hämta all information som kan vara till nytta i vår kamp mot de här kultisterna.\\r\\n\\r\\nSe vad du kan avslöja, $n. Jag väntar på din återkomst."}, -- quests-batch-21-sv
[94975]={t="Ett hämndens tecken", o="Samla $1oa kultistöron från Skymningshammaren i Krol'dok-fästet.", d="Vårt arbete här är inte slutfört, $n. De här kultisterna har tillfogat våra allierade outsägligt lidande och gjort de här landen redo att tas.\\r\\n\\r\\nVi tolererar inte dessa handlingar längre.\\r\\n\\r\\nI norr ligger ett dolt grottnätverk, maskerat av den kuperade terrängen. Våra spanare talade om kultiströrelser under mörkrets täckmantel.\\r\\n\\r\\nSök upp den här grottan och hitta var de här kultisterna gömmer sig. Det är dags att leverera ett budskap de inte snart glömmer."}, -- quests-batch-19-sv
[95063]={t="Blodmästarens ring", o="Besegra Chub'chob, Blodmästare av Bolder'ok, i Blodmästarens ring, och dela sedan nyheten om att du blivit ringens nykrönta mästare med Clugfist vid Bolder'ok.", d="Okej, lyssna. Du har visat en hel del skicklighet i ringen. Du har lyckats reta upp Chub'chob mer än ord kan förklara. Bra att jag inte är du just nu.\\r\\n\\r\\nOm du undrade så bör jag påminna dig om att din anmälningsavgift inte täcker oavsiktlig död.\\r\\n\\r\\nDet har varit trevligt att känna dig, men du är på egen hand från och med nu, kompis.\\r\\n\\r\\nLycka till.Chub'chob besegrad"}, -- quests-batch-20-sv
[95119]={t="Ovänlig konkurrens", o="Döda $1oa Eastsea-bukanjärer och $2oa Eastsea-musketörer längs Östvindsstranden, norr om Krutstubinhamnen.", d="Du känner till Eastsea-besättningen? Riktigt skumt gäng, och det säger killen som driver ett ställe som heter \"Krutstubinhamnen\".\\r\\n\\r\\nDe är förstörande, blodtörstiga, och, värst av allt, äter in på min vinstmarginal. De stjäl last och sänker skepp, vilket båda slutar med att kosta mig stora pengar!\\r\\n\\r\\nVi måste ta ned hela deras verksamhet, med början hos dem närmast här. Du hittar dem längs stränderna i norr."}, -- quests-batch-25-sv
[95120]={t="EFTERLYST: Gamle Rot-Chum", o="Ta med bevis på Gamle Rot-Chums död till hamnmästare Whizzbuzz.", d="Sjömän och simmare, se upp! En särskilt aggressiv murloc, med öknamnet \"Gamle Rot-Chum\" bland de lokala fiskarna, har setts angripa roddbåtar och andra små fartyg i vattnen i söder, nära en samling murlocsinfekterade öar.\\r\\n\\r\\nEn belöning erbjuds av hamnmästare Whizzbuzz i utbyte mot bevis på varelsens död."}, -- quests-batch-23-sv
[95122]={t="Okontrollerad expansion", o="Döda $1oa Eastsea-plundrare och $2oa Eastsea-bombardörer åt hamnmästare Whizzbuzz.", d="De där Eastsea-piraterna du slog ned, även om de var farliga, var bara småfisk. De har större, ondare vapenbröder norr om här. De plundrade Windstead--tog allt byte de kunde, och brände det sedan till grunden.\\r\\n\\r\\nDe måste stoppas innan deras revir kommer längre in i landet. Gallra ut deras led så att det inte sker."}, -- quests-batch-30-sv
[95144]={t="Leverans över havet", o="Leverera Fizzgrimbles gåtfulla låda till Friz Frazzlespark vid Krutstubinhamnen i Flodängarna.", d="Hallå, kompis. Har ett paket som ska till en gammal vän till mig. Vad du än gör--\\r\\n\\r\\nÖPPNA INTE PAKETET!\\r\\n\\r\\nTa det här--försiktigt--till Friz Frazzlespark över haven till vår systerhamn i Flodängarna. Och innan du frågar, nej jag skulle inte föreslå att simma. Fungerade inte så bra för den förra killen. Åh, och luta det inte, skaka det inte, och gör inga plötsliga rörelser.\\r\\n\\r\\nJag rekommenderar att du beger dig österut till Ångvisslehamnen. Skeppet därifrån brukar erbjuda säker passage.\\r\\n\\r\\nLycka till!"}, -- quests-batch-22-sv
[95162]={o="Om vi ska ha tillräckligt med kött till Rog'mar behöver jag din hjälp med skörden."}, -- quests-batch-32-sv
[95163]={o="Några av de små har rymt över floden. De är fortfarande för små för att skördas ute på fältet, så vi måste föra tillbaka dem hit. Ta den här pinnen och ge dem en rejäl smäll! Det borde få dem att skuttra tillbaka till sina hagar."}, -- quests-batch-32-sv
[95254]={t="EFTERLYST: Trapclaw", o="Ta med Trapclaws klo till Fimbo Greasemitz.", d="Alla sportfiskare, hör upp!\\r\\n\\r\\nJag är på marknaden för lite krabbkött. Inte bara de vanliga trasorna heller, jag talar om hela klor. Jag har sett en stor krypa omkring under kajerna, stjäla bete och klippa av linor.\\r\\n\\r\\nJag betalar en belöning till den som tar med mig den sakens klo. Du får också en portion av rätten jag lagar.\\r\\n\\r\\n-- Fimbo Greasemitz"}, -- quests-batch-26-sv
[95261]={o="Hallå! Sluta stå och glo! Jag behöver inälvor, JÄTTEMYCKET av dem. Vilket djur som helst härifrån. Ju stinkigare <hic> desto bättre. Jag behöver också några ruttnelsskivlingar. De växer i den där grottan vid Windstead."}, -- quests-batch-32-sv
[95288]={t="Smugglarnas paradis", o="Samla $1oa smugglade varor åt Friz Frazzlespark vid Krutstubinhamnen.", d="Du ser ut att ha för vana att göra vad andra säger åt dig. Det gillar jag hos en springpojke. Med lite träning kan du bli en stor tillgång. Låt oss testa det.\\r\\n\\r\\nNyligen smet några av de där Eastsea-piraterna iväg med en sändning av MINA stulna varor. Det är dålig sportsmannaanda. Jag stal dem först!\\r\\n\\r\\nLektion ett, springpojke. Svik aldrig en svikare. Gå och visa dem att de rörde sig med fel goblin och ta tillbaka mina grejer. Med våld, helst."}, -- quests-batch-26-sv
[95295]={t="Jag känner en kille", o="Tala med Frizs kontakt i Bytesbukten.", d="Du gjorde bra ifrån dig med de där piraterna, springpojke. Men här är en läxa du kanske vill komma ihåg. Det som somliga kallar en pirat kallar andra en fribytare. Och man kan inte stava fribytare utan fritt byte. Och det finns ingen bättre plats för fritt byte än Bytesbukten!\\r\\n\\r\\n<Friz väntar på ditt svar.>\\r\\n\\r\\nHäng med här, grabben. Jag säger att jag behöver att du går till Bytesbukten för att träffa min kontakt. Han får varor från de lokala piraterna där-- eh, fribytarna. Kolla, gå bara och hitta Ruzzgot. Han förklarar resten."}, -- quests-batch-19-sv
[95296]={t="! Frakt och hantering", o="Tala med hamnmästare Steamfizzle vid Ångvisslehamnen i Tanaris.", d="Det låter som att du är redo för din nästa lektion, mästarn. Jag har lite förhandlingar att sköta själv här i stan, så jag behöver att du springer några ärenden åt mig medan jag är upptagen.\\r\\n\\r\\nAllt jag behöver att du gör är att ta nästa skepp där borta vid kajerna och leverera den här lådan till min kollega i Ångvisslehamnen.\\r\\n\\r\\nTitta inte på mig så där. Det blir riktigt spännande, det är jag säker på. Att få en goblin att betala sina skulder är mycket svårare än att ge det lokala slödderet en omgång, för att inte tala om att ta sig igenom tullen. Du fixar det.Tala med hamnmästare Steamfizzle vid Ångvisslehamnen i Tanaris"}, -- quests-batch-20-sv
[95314]={t="Det där gröna elixiret från Shadowvale", o="Samla $1oa flaskor viskande elixir från Shadowvale och återvänd sedan till Carolai Anise i Brill.", d="Före Gisselinvasionen var den avskilda byn Shadowvale känd för sitt Viskande elixir. Destillerat av örter som bara finns i Tyrs fall eftertraktades elixiret av apotekare, mystiker och giftblandare på samma sätt även efter att det förbjudits i staden.\\r\\n\\r\\nJag har fått förfrågningar från ett antal köpare som är ivriga att få tag på lite elixir. Res till ruinerna av Shadowvale djupt inne i Viskande skogen i väster. Jag är beredd att erbjuda betydande ersättning om du kan hämta några flaskor åt mig."}, -- quests-batch-17-sv
[95328]={t="Viskande skräckrester", o="Leverera Viskande skräckrester till fader Lankester i Krigskvarteret i Understaden.", d="Mot bättre vetande skrapar du upp och samlar de vridande resterna av odjuret. Någon i Understaden kanske har nytta av dem."}, -- quests-batch-17-sv
[95433]={t="Död åt bödeln", o="Hämta Bödelns klubba från bödeln Morg i Skymningsslöjan åt Clugfist i Bolder'ok.", d="När Clugfist lämnar Skymningen står en oger i vägen. Morg.\\r\\n\\r\\nMorg massiv oger. Nästan lika massiv som Clugfist. Men inte massivast. Han behöver småttingar för att skydda honom. Clugfist fick aldrig rättvis strid. Nu VI inte slåss rättvist.\\r\\n\\r\\nHitta Morg. Ta med många småttingar. Döda honom. Ta klubba tillbaka till Clugfist. Då Skymningen vet att de utmanar oss inte mer!Återvänd till Clugfist i Bolder'ok."}, -- quests-batch-20-sv
[95494]={t="Sårad stolthet och lejonskinn", o="Samla 6 savannlejonskinn från savannmatriarker och savannpatriarker i Kargmarkerna.", d="Jag behöver någon med en stark svärdsarm och lite extra tid över för att hjälpa mig samla lejonskinn. Det svider i min stolthet att be en främling om den här hjälpen, men jag fick nyligen en skada i benet. Tills jag har läkt är jag inte i skick att jaga själv men jag har förpliktelser att hålla.\\r\\n\\r\\nDe stora i det här området har oftast de bästa skinnen, så börja med dem."}, -- quests-batch-08-sv
[95495]={t="Eremitgarvaren", o="Ta med Bunt skinn till eremiten på åsen med utsikt över De torra kullarna i Kargmarkerna.", d="De här skinnen är på väg till en garvare jag ofta handlar med. Han är något av en eremit och bor ensam uppe på åsen bakom mig. Att klättra uppför en brant sluttning är inget jag klarar av lätt just nu så jag skulle stå i din skuld om du kunde göra den här leveransen åt mig.\\r\\n\\r\\nÅh, och angående den här garvarens ... utseende. Du behöver inte bli orolig. Trots sitt utseende är han inget hot. Jag svär att det är sant."}, -- quests-batch-07-sv
[95507]={t="Vrangs villebråd", o="Samla 8 fångat villebråd från utlösta fällor i Kargmarkerna.", d="Medan du är därute vore det till stor hjälp för mig om du kunde se till mina fällor åt mig. Jag har dem utspridda över hela dalen.\\r\\n\\r\\nTa med dig tillbaka allt smådjur jag har fångat. Håll ögonen öppna efter det andra djurlivet, dock. Det här området kan vara farligt om man inte ger akt."}, -- quests-batch-04-sv
[95508]={t="Ovälkomna gäster", o="Hjälp Walton att överleva mötet med Terry Longdrink och Kul Tiras marinsoldater.", d="Ja, jag var tidigare medlem av Kul Tiras flotta. Efter att Herr Amiral intog Theramore och inledde sin kampanj i Durotar hade jag ... \"invändningar\" mot hans metoder. Särskilt metoderna som gick ut på att avrätta civila.\\r\\n\\r\\nDet finns mer att berätta men ... vänta ... vad är det där?\\r\\n\\r\\nEn grupp män kommer uppför åsen!"}, -- quests-batch-01-sv
[95534]={d="< Resten av anteckningen är svedd och sönderriven, som om den bränts av eldmagi. >"}, -- quests-batch-32-sv
[95621]={t="Bekymmer i dalen", o="Res till den förstörda karavanen och ta reda på mer om varför Kul Tirasarna är här.", d="I morse upptäckte jag en grupp människor som sökte efter något i dalen nedanför. Jag lyckades använda mitt gevärs kikarsikte för att se bättre, och det var tydligt att det var soldater i Kul Tiras livré. \\r\\n\\r\\nOm du är villig att ta uppdrag av mig, res till platsen där de här soldaterna slagit läger nära den förstörda karavanen i söder. Döda alla du hittar och försök ta reda på varför de är här."}, -- quests-batch-06-sv
[95663]={t="Rykten om Drakgap", o="Res till Våtmarkerna och möt Dödspejaragenten i kullarna ovanför Drakgap-lägret.", d="Drakgap är en formidabel klan.\\r\\n\\r\\nDe är kända för bindande magi stark nog att få drakar att tjäna, och rykten säger att de förbereder någon uppvisning av den i Våtmarkerna. Sanning eller skryt, Dödspejarna kan inte agera på halvfärdiga viskningar. Brutna symboler förde bara så mycket till mig.\\r\\n\\r\\nEn dödspejaragent behöver en hjälpande hand i kullarna ovanför Drakgaps läger. Möt henne där. Hon avslöjar nästa steg."}, -- quests-batch-30-sv
[95697]={t="Förändrade smaker", o="Gå in i Utgrävningsplatserna i Våtmarkerna och ta tillbaka snårraptorkött.", d="Zamja säger att vi behöver mer husmanskost.\\r\\nOm vi börjar sälja raptor tror hon att det lockar kunder som vanligtvis inte besöker Borstans eldgrop.\\r\\n\\r\\nHennes idé är inte så dum. Men jag vill ha något som höjer sig över dofterna från våra födelsebyar. Vi är i Orgrimmar! Borstan borde servera en storslagen tolkning av deras bekanta favoriter.\\r\\n\\r\\nEn jägare kom nyligen tillbaka från Våtmarkerna med en jättelik klo från snårraptorerna vid Utgrävningsplatserna.\\r\\n\\r\\nSugen på ett jobb?"}, -- quests-batch-29-sv
[95775]={o="Gå in i ruinerna och samla avritningar av alla tavlor du hittar där, återvänd sedan till mig."}, -- quests-batch-32-sv
[95789]={t="Skumma Saltseers", o="Samla $1oa voodoo-genomsyrade artefakter från Saltseer-pirater i Drunknade staden.", d="Hallå kompis, du ser ut som du kan klara dig i en strid.\\r\\n\\r\\nBaron Revilgaz har mig att hålla örat mot marken efter magiska föremål. Ryktet på gatan säger att en sjunken trollruin mystiskt har blivit, eh, osjunken, vilket betyder att det finns en massa oanspråkstagna varor, om du förstår vad jag menar.\\r\\n\\r\\nProblemet är att det också har fångat piraternas uppmärksamhet! Inte vilka pirater som helst, Saltseers samlar specifikt på magiska artefakter. Jag behöver att du går in i Drunknade staden, röjer ut dem och tar deras stulna artefakter."}, -- quests-batch-19-sv
[95884]={t="Offerstenen", o="Hitta Offerstenen i Berens fara i Silvertallsskogen.", d="<Anteckningslappen är mestadels oläslig. Det som ändå går att läsa är anteckningar om förberedelser för ett offer.\\r\\n\\r\\nEn offersten nämns, liksom en ritual.\\r\\n\\r\\nKanske kan du hitta den här offerstenen i närheten.>"}, -- quests-batch-30-sv
[95951]={o="Först ska du få egna spjut. Det här är mitt. Gå till människlägret i väster och ta deras trä. Ta med en kniv. Du kan vässa deras timmer till bra spjut för att sticka med. Sen tar du med dem tillbaka."}, -- quests-batch-32-sv
[95955]={t="Spetsa dem", o="Spetsa $1oa sötvattenskrokoliskar och återvänd sedan till Tran'jani i Rog'mar.", d="Du har spjuten, nu ska du lära dig kasta dem.\\r\\n\\r\\nFlodängarna är fulla av krokoliskar. Otäcka saker. Nappar åt dig om du inte är snabb. Perfekt för målövning, hehe.\\r\\n\\r\\nGå och spetsa en hel hög av dem. Sen kommer du tillbaka till gamle Tran'jani för ditt pris. Om du kan spetsa en krokolisk kan du spetsa vad som helst."}, -- quests-batch-28-sv
[95982]={t="Inte mitt problem", o="Ta med $1oa Salt skaldjursgryta till Jasper Geartoggle i Krutstubinhamnen.", d="Folk fortsätter att dumpa sina lurviga vänner här som om jag visste vad jag gjorde. Och sedan skyller de på mig om de kommer tillbaka och deras häst eller varg eller ... vad de nu tog med sig är död eller har sprungit iväg. Vad ser jag ut som, driver jag en välgörenhetsorganisation?\\r\\n\\r\\nDu ser ut som du vet hur man hanterar ett tråg. Skulle du kunna fixa lite käk som jag kan använda för att hålla de här best-djuren i schack?\\r\\n\\r\\nOm du inte kan göra det själv kanske någon är villig att sälja dig lite. Och skynda dig! Det sista jag behöver är en stampede av hungriga djur."}, -- quests-batch-27-sv
[95992]={t="EFTERLYST: Spökkäft", o="Ta med Spökkäftens huggtand till Tan'jani i Rog'mar.", d="De här vattnen är förrädiska. Mina huvudjägare håller stigarna fria så gott de kan, men det finns ett odjur som smyger i floderna som inte ens vi kan fånga. Spännande, va?\\r\\n\\r\\nBossen säger att vi måste röja ut det, så vi har en liten tävling på gång. Hitta den vita som patrullerar floderna och ta med mig dess huggtand. Den som sticker den hala krokoliskan vinner hela potten. Bara se till att inte själv bli biten, hehe!\\r\\n\\r\\n-- Tan'jani"}, -- quests-batch-20-sv
[95998]={t="Ute i det fria", o="Sitt nära Sams enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hallå där, $c. Jag ser att du har en äventyrares uppsyn. Bra för dig. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDet är en stor vid värld där ute och du måste lära dig att trivas i vildmarken för att lyckas. Jag vet inte hur det står till med dina friluftsfärdigheter men jag tror jag kan lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden, ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-05-sv
[96016]={t="Ovädrets vapen", o="Leverera Ovädrets öga till Bath'rah vindväktaren i Alteracbergen.", d="Du gjorde bra ifrån dig, och jag ser att du kliar efter din belöning. Tyvärr säger jag att jag inte precis är en dvärg med många ägodelar.\\r\\n\\r\\n<Veyric gestikulerar brett mot sin avlägsna plats.>\\r\\n\\r\\nJag ska säga dig vad, dock. Jag hör att ett troll vid namn Vindväktaren bor ute i Alteracbergen. Han är en mäktig shaman själv, och expert på stormelementarer. Om du tar den där elementarkärnan till honom slår jag vad om att han kan göra dig ett vapen värdigt din seger."}, -- quests-batch-22-sv
[96046]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Yarr Hammerstone i Kharanos för att lära dig tillverka ett lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-01-sv
[96063]={t="Gasformigt guld", o="Samla $1oa flaskor kärrgas åt Sleebo Fizzlespout.", d="Framtidens bränsle är inte kol eller olja, det är gas, raring! De där träskiga dammarna i sydväst spyr ut det i tonvis, och jag har just den uppfinning som behövs för att utnyttja det--en ny sorts motor som drivs av grejen. Gasen är verkligen besvärlig att samla in, dock.\\r\\n\\r\\nOm du känner för att ge ett ödmjukt bidrag till vetenskapens och industrins framtid, varför hjälper du mig inte att få tag på lite av den gasen? Du kan se den komma upp från ventiler nära vattnet."}, -- quests-batch-16-sv
[96101]={t="Ute i det fria", o="Sitt nära Raans enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hälsningar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-15-sv
[96104]={t="Löparens sång", o="Ta med en Oskadad höglöparnäbb till Neza Bloodsnout i Rog'mar.", d="De här märkena är från ett lejon. Att döma av dem är det här ett särskilt stort--ledaren för den närliggande flocken.\\r\\n\\r\\nJag skulle gärna jaga odjuret själv, men du har förtur. I stället ska jag hjälpa dig.\\r\\n\\r\\nJag kan göra en visselpipa som härmar ropet från en sårad höglöpare. Du kan använda den för att locka ut lejonet. Jag behöver bara en av deras näbbar för att ge den rätt ljud.\\r\\n\\r\\nDet finns höglöpare över hela slätterna. Hitta en näbb åt mig så kan jakten börja!"}, -- quests-batch-23-sv
[96105]={d="Jag önskar dig lycka till i din jakt. Må du återvända i ära."}, -- quests-batch-32-sv
[96108]={t="Giftspetsar", o="Ta med 4 prover av Glänthuggormsgift till Neza Bloodsnout i Rog'mar.", d="Pilar är alltid nödvändiga, men ibland behöver du något mer potent för att fälla ditt byte.\\r\\n\\r\\nDet är här giftbeläggningar kommer in i bilden. De förstör köttet, men om du behöver något dött gör de jobbet.\\r\\n\\r\\nGifter kan antingen brygdas eller, om du är modig, samlas in. Du verkar mig vara det senare.\\r\\n\\r\\nHuggormarna vid dammarna i söder producerar ett kraftfullt gift. Om jag har bedömt dig rätt tror jag att du kunde samla in lite av det."}, -- quests-batch-25-sv
[96222]={p="Ta med nyckeln till mig, så har jag ett förslag till dig."}, -- quests-batch-32-sv
[96241]={t="Prata toxiner, mon", o="Använd toxinutvinnaren för att samla $1oa prov av toxin från Dysterhöjden från de gnagda liken vid Dysterhöjden.", d="Nåt konstigt är på gång där borta vid Dysterhöjden. Gamle Mazu'kon har hört allt om de otäcka nya krypen som kryper omkring där.\\r\\n\\r\\nNågra säger att de där krypen har ett gift med unika egenskaper och det gör mig nyfiken. Ta min utvinnare. Använd den på de döda kropparna som ligger runt den platsen för att få fram giftet. Gör det så står jag i skuld till dig, mon."}, -- quests-batch-03-sv
[96259]={t="Försvara de döda", o="Döda $1oa Dysterhöjdens ungar och $2oa Dysterhöjdens soldater.", d="Det finns en uråldrig taurenisk gravplats på platsen som kallas Dysterhöjden, strax nordväst om det här lägret. På sistone har den invaderats av en särskilt grym kull spindlar. Dessa spindlar utgör inte bara ett hot mot Mulgores folk, de skadar också en plats som de flesta tauren anser vara helig.\\r\\n\\r\\nDet vore en stor tjänst om du kunde resa till Dysterhöjden och sätta stopp för det här angreppet. Förfäderna kommer säkert att le mot dig om du ser till att det blir gjort."}, -- quests-batch-14-sv
[96260]={t="Starkare än stål", o="Samla $1oa trådar kristallint silke från Dysterhöjdens spinnare.", d="Har du hört vad som drabbade gravplatsen vid Dysterhöjden? Jättespindlar--ryktet säger att deras gift är så starkt att det kan väcka de döda--har spridit sig som en löpeld. Otrevlig historia, om du frågar mig.\\r\\n\\r\\nEn av spanarna som skickades ut för att undersöka kom tillbaka halvdöd och täckt av ett otroligt motståndskraftigt, kristallint spindelsilke. Jag samlade in vad jag kunde, men jag skulle högt värdesätta fler prover av det här silket för ytterligare studier.\\r\\n\\r\\nTa med mer av det kristallina silket så belönar jag dig."}, -- quests-batch-01-sv
[96261]={t="Honummödern", o="Döda Honummödern Valraxx vid Dysterhöjden.", d="Som ofta är fallet med angrepp som det vi står inför vid Dysterhöjden leder en enda mäktig matriark ofta till en snabb spridning av en fientlig spindelpopulation.\\r\\n\\r\\nOm vi vill driva bort dessa bestar för gott måste vi söka upp urmodern och göra slut på henne. När du går till Dysterhöjden, sök upp honummödern där och förgör henne. Jag råder dig att ta med allierade och vara redo på vad som helst. Det här verkar inte vara några vanliga spindlar."}, -- quests-batch-26-sv
[96294]={t="En mörkare sanning", o="Ta med brevet du hittade på Honummödern Valraxx till Muln Earthfury vid Himmelsväktarplatån.", d="<Honummödern du just dödade är ingen spindel alls, utan snarare en nattalv-druid som antagit en förvriden djurform. En mängd frågor översvämmar ditt sinne om spindlarnas natur--och syfte--vid Dysterhöjden.\\r\\n\\r\\nDu ser en lapp titta fram ur vecken på den döda alvens dräkt. Kanske kan det här dokumentet besvara några av frågorna som fyller ditt huvud.>"}, -- quests-batch-16-sv
[96604]={t="Ute i det fria", o="Sitt nära Brakks enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Lok-tar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-10-sv
[96605]={t="Ute i det fria", o="Sitt nära Kagas enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hälsningar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-15-sv
[96606]={t="Ute i det fria", o="Sitt nära Lyreenas enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hälsningar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-13-sv
[96607]={t="Ute i det fria", o="Sitt nära Eleanors enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hälsningar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-05-sv
[96608]={t="Ute i det fria", o="Sitt nära Erics enkla lägereld och vänta tills du får förstärkningen Ökning vila.", d="Hälsningar, $c. Jag ser att du har en äventyrares uppsyn. Det är bra. Världen behöver fler av oss rastlösa själar, som söker fortun och ära.\\r\\n\\r\\nDu måste lära dig att trivas i vildmarken för att lyckas i det här yrket. Jag vet inte hur det står till med dina friluftsfärdigheter men jag kan nog lära dig ett och annat, om du är villig att lära.\\r\\n\\r\\nSätt dig vid elden och ta det bekvämt. Jag går igenom det med dig."}, -- quests-batch-11-sv
[96626]={t="Lägerlivets grunder: Matlagning", o="Tala med Tomas i Guldby för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-11-sv
[96627]={t="Äventyraren", o="Tala med Sam Sarsparilla nära Guldby.", d="$n, du har hittills visat din kompetens som beskyddare. Därför anförtror jag dig nu en ovanlig uppgift.\\r\\n\\r\\nJag har hört talas om en ny äventyrare längre fram på vägen vid Guldby. Gå och se vad han gör."}, -- quests-batch-14-sv
[96629]={t="Lägerlivets grunder: Matlagning", o="Tala med Gremlock Pilsnor i Kharanos för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-08-sv
[96630]={t="Äventyraren", o="Ta med dagboken till Lyreena Duskblade nära Dolanaar.", d="<Dagboken verkar vara ganska enkel och beskriver livet och äventyren för någon du aldrig hört talas om.\\r\\n\\r\\nDet finns flera anteckningar som nämner läger. Det verkar vara ganska ... roligt.>"}, -- quests-batch-14-sv
[96634]={t="Lägerlivets grunder: Matlagning", o="Tala med Zarrin i Dolanaar för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-04-sv
[96638]={t="Äventyraren", o="Tala med Raan Wildwind nära byn Shen'dar.", d="Fler och fler äventyrare som du har sökt ära och fortun utanför tryggheten i Thendallunden. Det finns en sådan äventyrare som har slagit läger utanför byn Shen'dar, längs vägen som leder sydväst ut från Thendallunden.\\r\\n\\r\\nSök upp honom och se vad du kan lära dig av honom som kan hjälpa dig på dina egna resor."}, -- quests-batch-05-sv
[96646]={t="Lägerlivets grunder: Matlagning", o="Tala med Zerril Softbreeze i byn Shen'dar för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-15-sv
[96652]={t="Äventyraren", o="Ta med dagboken till Brakk nära Knivkullen.", d="<Dagboken verkar vara ganska enkel och beskriver livet och äventyren för någon du aldrig hört talas om.\\r\\n\\r\\nDet finns flera anteckningar som nämner läger. Det verkar vara ganska ... roligt.>"}, -- quests-batch-11-sv
[96655]={t="Lägerlivets grunder: Matlagning", o="Tala med kocken Torka i Knivkullen för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-01-sv
[96656]={t="Äventyraren", o="Tala med Eleanor Shackleton nära Brill.", d="$n, du har hittills visat dig pålitlig i dina insatser mot Scharlakanskorståget. Därför anförtror jag dig nu en ovanlig uppgift.\\r\\n\\r\\nJag har hört talas om en ny äventyrare längre fram på vägen vid Brill. Gå och se vad hon gör."}, -- quests-batch-13-sv
[96658]={t="Lägerlivets grunder: Matlagning", o="Tala med William Pickman i Brill för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-09-sv
[96659]={t="Äventyraren", o="Lämna förnödenhetsknytet till Kaga Wildhoof nära Blodhovsbyn.", d="Vänta, $n. Jag har en sak till som jag vill be dig om, innan du lämnar oss.\\r\\n\\r\\nDet finns en äventyrare vid namn Kaga Wildhoof som har slagit läger strax utanför Blodhovsbyn. Hon har hjälpt mig mycket tidigare, och nu ser jag min chans att betala tillbaka. Skulle du kunna lämna de här förnödenheterna till henne?"}, -- quests-batch-04-sv
[96661]={t="Lägerlivets grunder: Matlagning", o="Tala med Pyall Silentstride i Blodhovsbyn för att lära dig bli kock.", d="Så du vill veta mer om lägerliv, va? Bra för dig, $c. Det första steget varje äventyrare måste ta är att bli kock och lära sig göra en lägereld.\\r\\n\\r\\nMatlagning handlar inte bara om att laga god mat. Det är också grunden för ditt läger."}, -- quests-batch-13-sv
[96774]={t="Uråldrig gurubashiidol", o="Återta en uråldrig gurubashiidol från Drunknade staden.", d="De uråldriga gurubashierna i Strypetörnsdalen var da mästare på mörk blodmagi. Ryktet säger de använde idoler av rent äktsilver för att kanalisera det där dåliga dåliga voodoot.\\r\\n\\r\\nGamle Mazu'kon skulle älska att få tag på en av de där idolerna ... för akademiska skäl, ser ya. Vad sägs om att du samlar några vänner och gör lite smash and grab på den där drunknade staden som sticker upp ur havet utanför Strypetörnsdalens kust? Döda den mest imponerande prästen du hittar där inne, och de har säkert det jag letar efter."}, -- quests-batch-08-sv
[96781]={o="Om du hoppas finna honom är han troligtvis bland Syndikatet i Strahnbrad."}, -- quests-batch-32-sv
[96783]={o="För att infiltrera fästet utan att väcka misstankar behöver du en förklädnad. Se om du kan hitta en hos Syndikatet utanför fästet, vid Northfold Manor."}, -- quests-batch-32-sv
[96800]={t="Försenad", o="Hämta boken Runmästarnas förlorade magi från Scharlakansklostret.", d="Du där, $c. Jag har en sak som jag skulle kunna behöva hjälp med.\\r\\n\\r\\nJag råkar skriva en avhandling om de forna runmästarna hos Vildhammar i Grim Batol, och det finns en särskild bok jag behöver för att slutföra min forskning. Enligt våra register lånade en magiker vid namn Doan ut boken från det gamla biblioteket i Dalaran före det tredje kriget och lämnade aldrig tillbaka den!\\r\\n\\r\\nArkanist Doan har nu förskansat sig i Scharlakansklostret i Tirisfalgläntorna. Hämta boken åt mig så blir du väl belönad."}, -- quests-batch-03-sv
[96821]={t="Ta till benen", o="Döda 6 Ridgeshade-kryp och 6 Ridgeshade-lurare i södra Durotar, och rapportera sedan till Gar'thok i Knivkullen.", d="Vi ser färre och färre resenärer från Knivkullen nuförtiden. Skorpiderna var aldrig särskilt roliga, men nu hör jag att det finns spindlar som bygger sina näste längs vägen.\\r\\n\\r\\nOm dina resor tar dig norrut, döda några av spindlarna på vägen. Låt sedan Knivkullen få veta att stigen är lite säkrare för dem."}, -- quests-batch-04-sv
[96822]={t="För äran", o="Samla Plundrarens stridsyxa, Plundrarens båge och Plundrarens sköld från utkanterna av Tiragardefästet och lämna dem sedan till Turroc i Knivkullen.", d="Vi förlorade många tappra krigare från Horden när vi plundrade Tiragardefästet. Nu när människorna har förstärkt ruinerna kan vi inte samla in deras kvarlevor för att ära deras död på rätt sätt.\\r\\n\\r\\nGå till ruinerna som omger fästet och sök efter vapnen som lämnats av våra stupade fränder. Vi kommer att ställa ut dem på en hedersplats."}, -- quests-batch-15-sv
[96825]={t="Den här frukten kan bita tillbaka", o="Kocken Torka i Knivkullen vill att du samlar 8 kaktusfikon från Knivmankemarkerna väster om staden.", d="Våra jägare och fiskare tar med sig gott om smakrik mat till våra trupper - men det är sällan de får något sött.\\r\\n\\r\\nJag har sett en kaktus som ger en taggig, välsmakande frukt. Men den växer bara i kullarna i väster, där de eländiga piggsvinsfolken slår läger. Ta dig förbi piggsvinsfolken och ta med mig några av de frukterna. Och var försiktig - frukterna är lika taggiga som piggsvinsfolken!"}, -- quests-batch-07-sv
[96895]={t="Silvergryningens sändebud", o="Hitta medlemmen av Silvergryningen nära ingången till Understaden.", d="Jag vet inte om du hörde, men två sändebud från Silvergryningen kom nyss förbi här. Jag har inget emot Silvergryningen, men jag gillar inte att de nosar runt i Tirisfal utan uppsikt heller. De var båda bortglömda ... men det gör mig inte mindre nervös.\\r\\n\\r\\nEn av dem gick just förbi här, på väg sydost. Det finns en grupp Gisselkultister som snokar runt i utkanten av staden i den riktningen. Om de två hörde om dem råder det ingen tvekan om att det skulle ha väckt deras uppmärksamhet."}, -- quests-batch-17-sv
[96896]={t="En rättfärdig sak", o="Iaktta samtalet mellan Danitha Morr och Leonid Barthalomew den Vördade.", d="Danitha och jag kämpade mot Gisslet i försvaret av Understaden när Naxxramas angrep. Vi förlorade många goda vänner den dagen, inklusive hjälten efter vilken det här fästet är uppkallat--Garek Bandarion.\\r\\n\\r\\nHan kan mycket väl ha varit den första bortglömda som återupptäckte hur man använder Ljuset som paladin. Jag är uppmuntrad av att se hans arv och potential leva vidare här med Danitha och hennes följe.\\r\\n\\r\\nOm bara resten av de bortglömda kände likadant ..."}, -- quests-batch-18-sv
[96897]={t="De fördömdas kult", o="Döda $1oa mörka neofyter och $2oa mörka verkställare i Tirisfalgläntorna.", d="Gisslet är en pest över våra land, och deras levande tjänare är värst av dem. Folket i Tirisfal har nog att brottas med mellan de själlösa döda och Scharlakanskorståget. Om du vill göra något gott, hjälp mig sätta stopp för detta avskum."}, -- quests-batch-16-sv
[96898]={t="Krigets kvarlevor", o="Samla $1oa nekrotiska kristallfragment i Tirisfalgläntorna.", d="Det var inte länge sedan Naxxramas citadell tyngde ned över den här staden, med avsikt att utplåna de bortglömda från kartan. Både de bortglömda och Silvergryningen förlorade mycket den dagen för att säkra de bortglömdas framtid.\\r\\n\\r\\nUnder striden splittrades den stora nekrotiska fokuseringskristallen som satt ovanpå Naxxramas och dess fragment spreds över hela det här området. Jag misstänker att det är därför kultisterna är här. Hjälp mig att hämta fragmenten och beröva Gisslet dem."}, -- quests-batch-18-sv
[96899]={t="Bandarionfästet", o="Möt Leonid Barthalomew vid Bandarionfästet i Tirisfalgläntorna.", d="Du har gjort något stort för Silvergryningens sak här idag, och jag tackar dig. Jag vet inte hur bekant du är med fästningen Bandarionfästet, men min befälhavare och jag var på väg dit för att möta paladinerna som bor där. Det var innan vi fick veta om De fördömdas kults närvaro.\\r\\n\\r\\nOm du vill veta mer om Silvergryningen och vårt uppdrag, sök upp min befälhavare vid Bandarionfästet, nordväst om här. Jag stannar här för att städa upp resten av den här röran."}, -- quests-batch-18-sv
[96986]={t="Gravriddaren", o="Besegra Atrexis Gravriddaren i staden Dalaran åt Melisara i Tarrens kvarn.", d="I den undre delen av magikerstaden i norr finns en förrädare mot vårt släkte. En nekromantiker med en oroande talang. Han reser en armé av odöda rakt under Kirin Tors näsa.\\r\\n\\r\\nJag bryr mig inte om magikerstadens öde, $n, men den här gravriddaren spottar i ansiktet på allt vi bortglömda står för. Gör slut på honom. Visa honom att ingen är bortom Mörka damens räckvidd."}, -- quests-batch-16-sv
[96987]={t="Opportunistisk utbildning", o="Samla Dalarans grundande från staden Dalaran åt Rexxie Copperclutch vid kloakingången.", d="Jaha, om det inte är en likasinnad entreprenör. Smyga in i Dalaran i så oroliga tider? Tsk tsk.\\r\\n\\r\\nSån $r gillar jag!\\r\\n\\r\\nMedan våra magikervänner här är upptagna kanske vi kan hitta några 'felplacerade' skatter. De har hela bibliotek ägnade åt fin arkan magi. Om du kunde ta med mig en av deras hemliga böcker kunde jag sälja den för en rejäl slant. Delar vinsten med dig.\\r\\n\\r\\nHallå, titta inte på mig så där. Du är ju inte direkt här på studiebesök själv. Är du med eller inte?"}, -- quests-batch-10-sv
[96988]={t="Kraftkälla", o="Samla $1oa spruckna vaktpostkärnor i staden Dalaran åt doktor Martin Felben i Understaden.", d="När staden Dalaran är belägrad av sina egna konstruktioner är det det perfekta tillfället att, låt oss säga, låna några prover.\\r\\n\\r\\nFöreställ dig en armé av arkandrivna vederstyggligheter. Mörka damen skulle inte ha något val än att erkänna min alkemiska skicklighet. Kanske till och med ge mig ledningen för Kungliga apotekarsällskapet?\\r\\n\\r\\nGå till staden och hitta konstruktionernas kärnor. De är osannolikt att ge dem frivilligt, så gör vad du måste."}, -- quests-batch-08-sv
[97003]={t="Chol'aruk Slukaren", o="Ta med Chol'aruks huvud till Gur'ak i Kargmarkerna.", d="Du där, $c. Jag behöver din hjälp. Det går rykten om ett odjur som har sitt näste djupt inne i en grotta vid Thorn Hill, nordost om här. Knivmankarna kallar det Chol'aruk eller \"Slukaren\". Det sägs vara fem gånger så stort som ett vanligt piggsvinsfolk med en blodtörst som aldrig kan stillas.\\r\\n\\r\\nDe flesta tror inte på berättelserna. Men det gör jag--eftersom jag har slagits mot dess like förut.\\r\\n\\r\\nSök upp dess näste och döda Chol'aruk. Ta med mig dess huvud. Jag varnar dig dock--förbered dig väl och gå inte ensam.\\r\\n\\r\\nBlod och åska, $c."}, -- quests-batch-10-sv
[97196]={t="Kallbringarens öga", o="Återta Kallbringarens öga från Knivkärrets kullar.", d="Det finns en tjänare till Lichkungen som har sitt hem djupt inne i Dödskallens piggsvinsfolks näste känt som Knivkärrets kullar. Det är känt för oss att han använder ett siarklot för att observera och styra sina underhavandes rörelser på andra håll.\\r\\n\\r\\nMed den här artefakten skulle vi kunna jaga ned Gisslets hemliga agenter och göra slut på dem och det hot de utgör mot Kalimdor för alltid.\\r\\n\\r\\nGå in i Knivkärrets kullar till Amnennar Kallbringarens näste och hämta sfären känd som Kallbringarens öga åt mig."}, -- quests-batch-21-sv
[97200]={o="Tala med mig när du har tillräckligt med guld, så ska jag lära dig att rida raptor."}, -- quests-batch-32-sv
[97223]={t="Blodklomatriarken", o="Ta med Blodklomatriarkens ägg till Xar'Ti i Sen'jins by.", d="Alla raptorer du ser framför dig är sådana jag har tränat själv. De kommer från hela Kalimdor, men några av de finaste kommer från Blodklo-raptorerna på öarna utanför vår kust.\\r\\n\\r\\nEn raptor bland dem, Blodklomatriarken, är särskilt vild och har dödat många från vår by och har blivit för farlig för att lämna vid våra gränser. Om du kan slå ned henne, återvänd med hennes ägg så att vi kan uppfostra ungarna som allierade i stället för fiender."}, -- quests-batch-11-sv
[97225]={t="Bortglömda loaidoler", o="Samla $1oa bortglömda loaidoler från Ekoöarna. Ta med dem till mästare Gadrin i Sen'jins by.", d="När vi flydde från öarna som Zalazane och hans likar nu bebor lämnade vi efter oss många dyrbara idoler som hjälper oss att kommunicera med andarna vi dyrkar: våra loa. De är av stor vikt för vår stam.\\r\\n\\r\\nZalazanes anhängare visar ingen vördnad för våra loa och har spritt ut dessa idoler över den största av öarna.\\r\\n\\r\\nDet här är en handling som inte kommer att passera obemärkt om vi inte kan samla ihop idolerna, och att förolämpa en loa är en allvarlig sak.\\r\\n\\r\\nGå, hitta så många loaidoler du kan och lämna tillbaka dem till mig."}, -- quests-batch-14-sv
[97253]={t="Delar och bitar", o="Samla $1oa handfullar komplicerade delar från det övre piratlägret söder om Spärrhake och återvänd sedan till Wrenix den eländige i Spärrhake.", d="Hej, har du en sekund?\\r\\n\\r\\nAlltså, tydligen har ingen av dem jag skickat för att ta itu med det senaste pirat-problemet kommit tillbaka levande. Efter fem eller sex försök tänkte jag \"tänk om jag skickade en maskin istället?\" Det visade sig att krumsablar fungerar som skruvmejslar i nödfall, och innan jag hann styra den hem var den redan i bitar och utspridd över deras läger!\\r\\n\\r\\nJag behöver tillbaka de där delarna, och eftersom det här är ett litet snabbt hämtuppdrag skulle jag gissa att dina chanser att överleva är MYCKET högre än de andras. Vad säger du?"}, -- quests-batch-03-sv
[97265]={t="Hata Hatraseri", o="Besegra olika Hatraseri-satyrer vid Sargeron i Ödelandet och återvänd sedan till Aka'rai i Skuggbytesbyn.", d="Har du nånsin slutit en deal med en satyr, mon?\\r\\n\\r\\nJag har. Hur kunde jag motstå? Löftet om makt, kunskap som långt överstiger vad någon vanlig bok kan erbjuda ... allt tillsammans med en ivrig och karismatisk undersåte. Vad mer kunde jag begära?\\r\\n\\r\\nBah, naturligtvis skulle de aldrig böja knä för en dödlig. Jag förhandlade när jag inte hade något, bara för att kastas åt sidan med ännu mindre.\\r\\n\\r\\nNu vill jag ha hämnd. Hämnd mot Hatraseri. Plundra deras läger i nordost! Färga jorden med deras vidriga blod."}, -- quests-batch-12-sv
[97279]={t="Förirrade vapen", o="Samla $1oa övergivna övningsvapen och återvänd sedan till Kzan Thornslash i Lyan.", d="Med en tillströmning av nya rekryter som du har det varit svårt att hålla våra vapen försörjda. Vår vapensmed Kzan har ont om övningsvapen och jag skulle vilja se vilka färdigheter du har för att få en uppfattning om vad jag har att arbeta med. Som tur är har jag en lösning på båda.\\r\\n\\r\\nMedan du är därute och skärper dina tänder på vildsvin, rädda sex övergivna övningsvapen. Våra misslyckade rekryter lämnade dem liggande på marken. När du har gjort det, lämna dem till vår vapensmed Kzan bakom mig i Lyan."}, -- quests-batch-04-sv
[97287]={t="Skarpa förhandlingar", o="Tala med Bilden av ärkemagiker Modera nära Dalaran.", d="Du har gjort rätt i att infiltrera magikernas stad, men jag tror att det är dags för oss att vara mer ... förhandlingsvilliga.\\r\\n\\r\\nSå mycket det än smärtar mig att erkänna finns det ingen annan plats på Azeroth med en så vidsträckt kunskap om det arkana. Mitt briljanta arbete bleknar fortfarande i jämförelse med den uråldriga visdom som Kirin Tor har samlat på sig genom åren. Jag tycker att det är hög tid att vi beviljas tillträde till det här exklusiva ordenssällskapet, inte sant?\\r\\n\\r\\nTa stoftkornet du skaffade. De ger säkert vad som helst för att få tillbaka det. Vad som helst."}, -- quests-batch-22-sv
[97332]={t="Dubbelt felplacerat förtroende", o="Leverera Två gånger ombeställt paket till hamnmästare Whizzbuzz vid Krutstubinhamnen i Flodängarna.", d="Så mycket som jag ogillar killen har jag hört vad Blodskalp-stammen gör med sina fångar, och det är inte vackert. Jag är glad att Zimmix klarade sig.\\r\\n\\r\\nJag har dock ännu en brådskande leverans och jag litar INTE på att han tar den. Problemet? Ingen annan kommer att vara tillgänglig för att ta den innan han gör det. Du, däremot, har räddat förlorad last och en tillfångatagen goblin, så du ser ganska pålitlig ut härifrån.\\r\\n\\r\\nHar jag någon chans att övertala dig att ta det här till Whizzbuzz vid Krutstubinhamnen?"}, -- quests-batch-27-sv
[97386]={t="Grom'gols offensiv", o="Befälhavare Aggro'gosh vid Grom'gol-baslägret vill att du dödar oger vid Mosh'Ogg-ogerhögen.", d="$n! Din ankomst är lägligt, som alltid.\\r\\n\\r\\nDu har gett värdefull hjälp till försvaret av Grom'gol, och vi är tacksamma. Efter din senaste framstöt mot ogerna i närheten skickade vi ut en spanare för att se om det finns fler där ute som kan försöka utkräva hämnd mot oss. Det visar sig att det finns en grotta långt österut som de har gjort anspråk på som sitt näste.\\r\\n\\r\\nSamla en vän eller två och gör det mycket tydligt att vi inte tolererar ännu ett hot mot vår bosättning, nu eller någonsin!"}, -- quests-batch-25-sv
[97453]={o="Jag sprang iväg och jag mår bra, men nu låter de mig inte leka utanför lägret längre. Kan du göra det säkert för mig, och sedan berätta för min mamma?"}, -- quests-batch-32-sv
[97538]={t="Pigment till färger", o="Tah Vinterhov i Dunderklippan vill ha $1oa dyörtsskidor från Mirkfallonsjön.", d="Hälsningar, vän. Får jag be dig om en tjänst? Jag har just slut på rött pigment till mina färger, och jag söker någon med yngre hovar som kan göra den långa resan in i Stenklobergen åt mig.\\r\\n\\r\\nMitt i bergspasset ligger en stor cirkelrund sjö, Mirkfallonsjön, där en unik växt växer i vattnet. Skidorna på den här växten, dyört, blir klarröda när de torkas. Samla skidorna från den här växten åt mig, så belönar jag dig väl för din möda."}, -- quests-batch-05-sv
[97539]={t="Sidenmjuka suturer", o="Lämna tillbaka 12 Kirurgiskt spindelsilke till doktor Gregory Victor i Hammarfall, Arathihöglandet.", d="Det här lägret lämnas åt att ruttna. Belägringsskadorna står kvar, oreparerade, som om försummelse vore policy. Jag tillåter inte samma förfall här. Sjukstugan lyder under mig, och jag tänker hålla den funktionsduglig.\\r\\n\\r\\nVi har nästan slut på förnödenheter. Jag kommer att behöva mer utrustning--tillräckligt för att hålla arbetarna och vakterna på fötter.\\r\\n\\r\\nUnder press kan vi göra en ganska effektiv fältsutur med tvinnat spindelsilke.\\r\\n\\r\\n$C, ta med mig lite från spindlarna som smyger runt i det här höglandet."}, -- quests-batch-26-sv
[97558]={t="Skinn åt de bortglömda", o="Ta med $1oa skymningsfladdermusvinghinnor, $2oa mörkhundsskinn och $3oa vidrigfenmurlocskinn till Shelene Rhobart.", d="En del av tillvaron som odöd som ingen nämner är vad som händer när vi skadas. Hur läker huden hos en odöd sig själv?\\r\\n\\r\\nTja, det gör den inte.\\r\\n\\r\\nVårt är ett förbannat liv, $n. Vi måste ta från de levande för att förlänga vår egen existens.\\r\\n\\r\\nNär vi skadas måste vi ersätta vår hud, vilket oftast betyder djurhudar. Eftersom olika hudtjocklekar passar bättre på olika ställen på våra kroppar är variation nyckeln!\\r\\n\\r\\nTa med mig vingmembran från en skymningsfladdermus, skinn från en mörkhund och hud från en Vidrigfen-murloc."}, -- quests-batch-18-sv
[97663]={o="Nu är jag helt slut på förnödenheter och saknar studiematerial medan jag återhämtar mig. Kan du bege dig österut för att leta efter min packning och själv göra avritningar av ristningarna?"}, -- quests-batch-32-sv
[97884]={t="Sunnygladdes vapenhus", o="Res till Sunnyglade i Flodängarna och hämta boken med Tremayne-familjens smidestekniker.", d="Du ser ut som en frisk, kraftfull $r. Jag söker någon som kan resa till Sunnyglade, i Flodängarna strax norr om Rödåsbergen.\\r\\n\\r\\nMin familj ägde ett vapenhus där en gång. Nu föreställer jag mig att det är ett utbränt skal, men jag skulle vilja att du hämtar en bok som innehåller min familjs ärvda rustningstillverkningstekniker. Den fanns ursprungligen i källaren, så förhoppningsvis har den inte fallit offer för elementen än."}, -- quests-batch-19-sv
[97907]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Krunn i Knivkullen för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-02-sv
[97923]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Gelman Stonehand i Stormvind för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-11-sv
[97935]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Brek Stonehoof i Dunderklippan för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-14-sv
[97948]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Kurdram Stonehammer i Auberdine för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-10-sv
[97953]={t="Lägerlivets grunder: Förtrollning", o="Tala med Vance Undergloom i Brill för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Förtrollare gör allting bättre och är alltid välkomna i alla läger ute i vildmarken.\\r\\n\\r\\nJag tror jag känner någon som kan lära dig tillverka en Förtrollad luta till ditt läger. Det är så viktigt att hitta underhållning under din vilotid, och den här lilla magin kan hjälpa till att se till att du är redo att möta alla sorters utmaningar när du ger dig ut på den gamla dammiga stigen igen."}, -- quests-batch-17-sv
[97959]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Brom Killian i Understaden för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-08-sv
[97961]={t="Lägerlivets grunder: Skrädderi", o="Tala med Bowen Brisboise på vägen till Brill från Dödsklockan för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Skrädderi är ett förvånansvärt kraftfullt hantverk att satsa på, och jag är säker på att det kommer att tjäna dig väl.\\r\\n\\r\\nJag känner någon som kan lära dig tillverka ett Fraktionsbaner till ditt läger, förutsatt att du har färdigheten för det. Inspiration och moral är en nyckeldel av framgång på varje slagfält, och ett inspirerande baner kan göra mycket för att hålla dig energisk."}, -- quests-batch-17-sv
[97967]={t="Lägerlivets grunder: Fiske", o="Tala med Fenn Fairweather i byn Shen'dar för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Du kanske inte tror det, men din skicklighet som fiskare kan faktiskt komma väl till pass i lägret.\\r\\n\\r\\nJag tror jag känner någon som kan lära dig tillverka en Fiskskål till ditt läger. Du kan använda den här inredningen för att sprida lite glädje åt dig själv och dina medäventyrare. En glad äventyrare är en stark äventyrare och jag är säker på att din stridsförmåga kommer att avspegla det."}, -- quests-batch-29-sv
[97970]={t="Lägerlivets grunder: Gruvbrytning", o="Tala med Messana Crestwind i byn Shen'dar för att lära dig tillverka lägerutrustning för ditt yrke när du har visat skicklighet i din färdighet.", d="Gruvbrytning är inte det mest glamorösa, men det är hederligt arbete och ett fint yrke för dig att utforska.\\r\\n\\r\\nJag tror att jag känner någon som kan lära dig tillverka en ledsten till ditt läger. Bygg en sådan, så kommer alla som vill svinga ett svärd gärna att samlas kring din eld och suga i sig det extra \"trycket\" den kan ge för att öka deras stridsförmåga."}, -- quests-batch-02-sv
[97985]={t="Dundrande hjärtan", o="Döda Stormhjärta i Tusen nålar och skaffa dess hjärta.", d="Fascinerande, eller hur? Det här är första gången jag får ta del av hemligheterna bakom skapandet av vederstyggligheter.\\r\\n\\r\\nJag har studerat de här anteckningarna, och det verkar som att vi behöver ett hjärta. Ett enormt ett!\\r\\n\\r\\nJag har hört att det finns en åsködla av imponerande storlek där, kallad Stormhjärta, som patrullerar längs kanjonkanten i Tusen nålar. Med ett sådant namn måste den ha det perfekta hjärtat. Jag måste ha det hjärtat!\\r\\n\\r\\nÅh, och jag föreslår att du tar med dig vänner. Stormhjärta är inte direkt känd för att vara tam."}, -- quests-batch-01-sv
[98069]={t="Stulna förnödenheter från Frivindsposten", o="Lämna de 8 stulna förnödenheterna till Jandia.", d="De eländiga harpyorna! De anföll den senaste karavanen som jag hade planerat skulle leverera förnödenheter till Frivindsposten. Vi har tillräckligt med förnödenheter just nu, men utan fler får vi snart ont om dem.\\r\\n\\r\\nJag vet inte vad harpyorna tänker göra med de extra förnödenheterna, men jag vore tacksam om du ville hämta tillbaka dem åt mig. De har sitt näste väster om här. De finns både vid foten av klippväggen och inne i en grotta högst upp."}, -- quests-batch-01-sv
[98070]={t="Stoppa skriken", o="Döda $1oa skrikande harpyor, $2oa skrikande Roguefeather-harpyor och $3oa skrikande Windcaller-harpyor.", d="Skrikkanjonen är hem för ett lokalt harpygäng känt för sin vilda natur och sina plundringstaktiker. De har lagt bakhåll för de senaste proviantkaravanerna som varit modiga nog att ta sig igenom platsen.\\r\\n\\r\\nJag fruktar att om inget görs snart kommer inga karavaner våga ta sig till Frivindsposten.\\r\\n\\r\\nGå och döda så många av de här harpyorna du kan. Kom tillbaka till mig när det är gjort, så belönar jag dig väl för mödan."}, -- quests-batch-05-sv
[98094]={t="Spanarstöd", o="Högexekutor Darthalia vill att du levererar uppdaterade order till dödspejare Masoj, söder om Tarrens kvarn, utanför Dun Garok.", d="Nu när vi kan lita på att du levererar kritisk information till våra spioner längre fram finns det en extra uppgift åt dig.\\r\\n\\r\\nTa det här till dödspejare Masoj nästan rakt söder om oss. Han har mer åt dig att göra när du kommit dit och räckt över det till honom. Han är posterad på högre mark norr om den ruttna vingården som de kallar Nethanders gård.\\r\\n\\r\\nVår plan att ta kontroll över de här landen fortskrider stadigt."}, -- quests-batch-02-sv
[98095]={t="Värdefulla utsiktsplatser", o="Dödspejare Masoj vill att du placerar de tre Apotekarens flaskor på toppar runt Hillsbrads förberg och återvänder till honom.", d="Vårt högkvarter sätter in strategiska trupper med hjälp av fladdermusryttare. Nyckelpunkter runt förbergen har förlorat sina signalfyrar.\\r\\n\\r\\nTa de här flaskorna. Dra ut korken på tre platser: kullarna som gränsar till Dun Garok, platån som blickar ut över Dunholde Keep och den sista på åsen vid Udden ovanför staden Hillsbrad. Ångorna som sprids blir som en kraftfull stämgaffel för fladdermössens sinnen och drar dem till de önskade avlämningsplatserna igen.\\r\\n\\r\\nLeta efter krossade tomma flaskor och förnya våra märken."}, -- quests-batch-06-sv
[98248]={d="Bredvid texten finns en grovt ritad karta över området nära den ovannämnda destinationen.>"}, -- quests-batch-32-sv
[98251]={t="Aldrig tillbaka", o="Döda $1oa skuggehornshjortar och $2oa askdalsbjörnar och återvänd till Va'xug Firefure nordväst om Nedfallna himlens sjö.", d="Gaaah!\\r\\n\\r\\nJag är så arg. De sa att Askdalen var lätt att följa. Lätt för vem? Bestarna? Fåglarna?\\r\\n\\r\\nEtt ögonblick samlade jag en ört, nästa sitter jag fast i den här ravinen. Måste jag verkligen gå runt halva skogen för att nå dit jag stod för bara några ögonblick sedan?\\r\\n\\r\\nNär jag är så här blir mina trollformler instabila och beter sig ... annorlunda.\\r\\n\\r\\nKan du gallra ut djurlivet i närheten? Även deras dumma hovar irriterar mig. Jag föraktar den här förbannade skogen."}, -- quests-batch-09-sv
[98252]={t="Tomhetens stig", o="Visa Va'xugs Kilroggs öga vägen tillbaka till Askdalens huvudväg.", d="Visa mitt Kilroggs öga vägen ut ur den här ravinen och tillbaka till Askdalsvägen. Håll det i rörelse så följer jag efter när jag ser en fri väg.\\r\\n\\r\\nJag stannar här--en av oss bör behålla orienteringen. Om du tappar bort vägen kan jag leda dig tillbaka genom ögat. Jag tänker inte låta oss båda irra blinda i den här ondskefulla skogen.\\r\\n\\r\\nJag kan hålla kanalen i fyra minuter. Inte längre. Nå vägen innan synen bryts, eller kom tillbaka till mig så försöker vi igen."}, -- quests-batch-08-sv
[98389]={t="Ett ljus i mörkret", o="Befria $1oa nätfångade offer i Nattnätshålan åt Aramis Hammerhand i Dödsklockan.", d="Hälsningar, $c. Ja, jag är en paladin. Inte ens döden kan stoppa Ljuset.\\r\\n\\r\\nDet här är något mitt släkte har gemensamt med alla de bortglömda--vi har övervunnit det som de levande betraktar som sitt slut. Men även bland våra egna finns de som fruktar oss; de misstänker att vi ska slå ned dem som något vidunder.\\r\\n\\r\\nI sanning är vårt förhållande till odödheten komplicerat, men jag är inte här för att skada våra egna. Hjälp mig visa de andra detta. Ge dig av till Nattnätshålan i nordväst och befria de nyligen uppväckta dårarna som fastnat i spindlarnas nät där."}, -- quests-batch-07-sv
[98545]={t="Leonids brev", o="Leverera Förseglat brev till Glix Xizzix i Understaden.", d="Eftersom du är här skulle jag vilja att du levererar det här brevet till en gammal vän till mig i Understaden. Jag skulle levererat det själv men jag har en något färgstark historia med Mörka damen, och det vore bättre om en neutral tredje part gjorde leveransen.\\r\\n\\r\\nDu letar efter en goblin vid namn Glix Xizzix i Handelskvarteret i Understaden. Jag är säker på att han gärna ersätter dig för din tid.\\r\\n\\r\\n<Leonid låter ut ett lågt fniss när han räcker dig brevet.>"}, -- quests-batch-16-sv
[98887]={t="Konflikt på Mörkspjutsöarna", o="Ta med 3 Mörkspjutsöarnas hedersmärken till en krigsbringare från Horden utanför slagfälten.", d="Theramores expeditionsstyrka är seg och fortsätter skicka förstärkningar för att stärka sin position på Mörkspjutsöarna. $B$BGå, visa dem Hordens makt! Ta med mig bevis på din seger på det här viktiga slagfältet så blir du väl belönad."}, -- quests-batch-09-sv
[99048]={t="En saknad hand", o="Hitta Heglan Shadeeye norr om Tiragardefästet.", d="En medlem av Den krossade handen, en grupp mer ... subtila stridsmän, bevakade Tiragardefästet på avstånd. Hennes rapporter slutade plötsligt komma in.\\r\\n\\r\\nJag tvivlar på att människorna skulle ha fångat henne, så jag är orolig att något farligare är i görningen. Se om du kan hitta henne. Förhoppningsvis är budskapen bara försenade."}, -- quests-batch-07-sv
[99049]={t="Hot underifrån", o="Hitta spår av vad som angrep Heglan Shadeeye.", d="Området i närheten är förstört med tydliga tecken på en strid. Vad det än var som lade ett bakhåll för Heglan kom inte oskadd därifrån. Det finns förmodligen spår i närheten av vad som hände.\\r\\n\\r\\nOrgnil vill förmodligen se alla bevis som angriparna lämnat efter sig."}, -- quests-batch-12-sv
[99051]={t="Hot underifrån", o="Samla $1oa nagaryggfenor.", d="Det vore inte första gången de där ormarna besvärar oss. De behöver få lära sig att deras närvaro inte tolereras här.\\r\\n\\r\\nHitta var deras spanare slår läger och slakta dem. Ta med deras fenor som bevis. Vi måste agera snabbt för att se till att de förstår."}, -- quests-batch-13-sv
[99123]={t="Vilse i skuggorna", o="Hjälp Pal'juh att fly från Kolkarklippan och ge besked om din framgång till mästare Vornal i Sen'jins by.", d="Jag bestämde mig för att spana lite i klippan på egen hand. Tyvärr tog min magi slut vid fel tillfälle och jag har suttit gömd här sedan dess.\\r\\n\\r\\nOm du kunde hjälpa mig att fly skulle jag vara tacksam.Eskortera Pal'juh ut ur Kolkarklippan."}, -- quests-batch-09-sv
[99134]={t="Disciplin", o="Straffa $1oa dödsvakter åt exekutor Zygand.", d="Du är inte medlem i Dödsvakten och har därför ännu inte gjort mig besviken.\\r\\n\\r\\nSom belöning för din relativa brist på inkompetens ska du straffa de som har visat sådana talanger i överflöd.\\r\\n\\r\\nSnabbt nu--$n, är det så?--annars lägger jag till ditt namn i min bok för någon annans belöning."}, -- quests-batch-17-sv
[99141]={t="Tålamod", o="Skaffa rapporter från dödsvakt Dillinger, dödsvakt Kristof och Gordo åt exekutor Zygand.", d="Missta dig inte, $c--Mörka damen kräver att hennes vilja utförs perfekt. Som Exekutor är det min plikt att se till att det sker.\\r\\n\\r\\nRapporter från flera av mina dödsvakter är försenade. Onödigt att säga att mitt tålamod har tagit slut. Skaffa deras rapporter och ta dem till mig i Mörka damens namn.\\r\\n\\r\\nDu hittar dödsvakt Dillinger strax väster om här, vid kyrkogården. Dödsvakt Kristof är stationerad vid mellanstationen i öster. Och se till vederstyggligheten Gordo; han vandrar västerut nära Stillwater Pond."}, -- quests-batch-17-sv
[99142]={t="Gravört", o="Samla $1oa gravört och leverera tillbaka dem till apotekarlärling Holland.", d="Om du är på väg österut, mot Balnirs gård, har jag mer du kan göra åt mig. Bra hjälp är så förbaskat svår att hitta nuförtiden, vilket ditt möte med Gordo belyser så tydligt.\\r\\n\\r\\nNär jag skaffar undergångsört gör jag några mindre alkemiska förändringar och planterar om dem på den gården för att odla min yttersta skapelse. Jag kallar den gravört, och den ska bli förebudet om mitt ärorika öde.\\r\\n\\r\\nHåll gärna ett öga på Gisslet i området medan du är där. De verkar ... dras ... till örten. Märkligt."}, -- quests-batch-18-sv
[99144]={t="Söka tillflykt", o="Hjälp Bareth Dawnstone att fly från Korsfararens utpost, och rapportera hans säkerhet till Shari Stilwell i Brill.", d="Ljuset välsigne dig för att du hittade mig. Jag var på väg från Bandarionfästet för att leverera ett meddelande till Shari Stilwell i Brill när de här monstren fångade mig. De bär Ljuset med ett hat i sina hjärtan som får det som är kvar av mitt blod att koka. Det går emot allt jag mediterar för ... allt jag strävar efter att skydda!\\r\\n\\r\\n<Bareth Dawnstone samlar sig.>\\r\\n\\r\\nJag vet att vissa fortfarande har invändningar mot mitt släkte, men jag försäkrar dig att våra avsikter är rena. Om du hjälper mig att fly härifrån vore jag evigt tacksam.Eskortera Bareth Dawnstone ut ur Korsfararens utpost"}, -- quests-batch-18-sv
[99152]={t="Som däruppe, så därnere", o="Samla $1oa svagt glödande ben åt Hilda Krossaren.", d="Även om de Fläckade i Shadowvale i sydväst definitivt är ett problem kan vi inte låta källarna under staden ruttna till ett fullskaligt Gisselupplopp mot Bandarionfästet.\\r\\n\\r\\nJag måste få de här rekryterna i form ifall det sker. Du, däremot, ska få vad jag gillar att kalla en snabbkurs.\\r\\n\\r\\nRes under Shadowvale och hämta några av deras eländiga ben så vi kan studera dem närmare. Jag behöver sådana som fortfarande har kvar en del av den ursprungliga återupplivningsmagin--det vill säga glödande."}, -- quests-batch-17-sv
[99153]={t="Den som kom undan", o="Hitta det gömda kristallfragmentet under Shadowvale åt Ephram Barbaro.", d="Hallå, du! Ryktet sprider sig snabbt i våra led. Jag hörde om jobbet du gjorde med kultisterna runt resterna av striden med Naxxramas.\\r\\n\\r\\nProblemet är att en av de där kultisterna kom undan med en bit av fokuseringskristallen. Verkar fortfarande ha lite krut i sig. Vår bästa gissning är att den finns någonstans under Shadowvale. Den antingen reser upp dem eller gör dem starkare, och du vill inte ha någotdera.\\r\\n\\r\\nHitta den kristallen innan det här går över styr."}, -- quests-batch-17-sv
[99156]={t="Bakre vaktpatrull", o="Ta med Riptears hjärta till dödsvakt Linnea.", d="Fan också! En ny rapport kom in medan du var på patrull. En lös vederstygglighet har observerats vandrande i östra Tirisfalgläntorna, nära Venomweb Vale.\\r\\n\\r\\nNågot är fel. Vederstyggligheter smiter inte bara förbi Bålverket obemärkt.\\r\\n\\r\\nHåll den här saken strikt på behöver-veta-basis. Med det sagt, en sådan varelse faller inte lätt; du behöver allierade om du vill vara mer än dess nästa måltid.\\r\\n\\r\\nSe det här till slut, så blir du vederbörligen belönad. Ta med mig dess hjärta som bevis på dådet."}, -- quests-batch-18-sv
[99211]={t="En episk ritt", o="Inspektera de pansarklädda odöda krigshästarna för att välja ditt episka riddjur.", d="Hälsningar, $n. Jag väntade mig inte att se dig tillbaka i mina enkla stall så snart igen.\\r\\n\\r\\nDu har verkligen gjort en lång resa. Jag tror jag kan gissa vad som fört dig hit idag.\\r\\n\\r\\nDu har nu tillräckligt med kraft, erfarenhet och skicklighet för att rida våra skickligaste och mest fruktade krigshästar. De pansarklädda odjuren bär dig genom vilken prövning som helst, till och med förbi själva dödens portar. \\r\\n\\r\\nGå och granska de pansarklädda odöda krigshästarna och kom tillbaka till mig när du har gjort ditt val."}, -- quests-batch-03-sv
}

for id, add in pairs(extra) do
    if LQ[id] == nil then LQ[id] = add end   -- skriv aldrig over granskat innehll
end
